/* Investing Learning Lab - glossary data - V1.0 (September 2026)
   Each entry: t term, a aliases, c category, l level (1 start here, 2 going further, 3 practitioner),
   mod the module that teaches it, d what it is, u what it is used for, m what it means for you.
   Year-specific dollar figures appear only where pinned to a stated tax or benefit year. */
window.INV_GLOSSARY = [{"t":"0DTE option","a":["zero-days-to-expiration option","zero-day option"],"c":"Asset classes","l":3,"mod":"INV-016","d":"An option traded on the day it expires. Cboe reports that 0DTE contracts were 59% of all S&P 500 index (SPX) option volume in 2025.","u":"Very short-term speculation and hedging around intraday moves.","m":"Research finds retail traders lost money on average in 0DTE S&P 500 options; they behave more like lottery tickets than investments."},
{"t":"10% early-withdrawal tax","a":["early withdrawal penalty"],"c":"Taxes","l":1,"d":"An additional 10% tax on most withdrawals from retirement accounts before age 59½, unless an exception applies.","u":"Discouraging early use of retirement savings.","m":"Exceptions include the rule of 55, 72(t) payments, disability and some others."},
{"t":"1031 exchange","a":["like-kind exchange"],"c":"Real estate","l":3,"d":"A tax-deferred exchange of investment or business real property for other like-kind real property, with strict identification (45 days) and closing (180 days) deadlines.","u":"Deferring capital gains when trading investment properties.","m":"Tax is deferred, not forgiven; a qualified intermediary is required."},
{"t":"1035 exchange","a":["section 1035 exchange"],"c":"Insurance","l":3,"mod":"INV-017","d":"A tax-free exchange of one life insurance policy or annuity contract for another under section 1035 of the Internal Revenue Code.","u":"Moving from an old, costly contract to a better one without triggering tax.","m":"Tax-free is not cost-free: the SEC warns you may pay surrender charges on the old contract and a new surrender period generally begins."},
{"t":"12b-1 fee","c":"Costs","l":2,"mod":"INV-007","d":"An annual marketing and distribution fee included in some funds' expense ratios. FINRA caps the asset-based sales charge at 0.75% a year plus a 0.25% service fee.","u":"Paying for fund distribution.","m":"You pay it every year you hold the fund."},
{"t":"401(k)","c":"Accounts","l":1,"d":"An employer-sponsored retirement plan allowing payroll contributions, pre-tax (traditional) or after-tax (Roth), with annual limits set by the IRS.","u":"The main retirement vehicle for many workers.","m":"Capture any match; choose low-cost funds from the menu."},
{"t":"403(b)","c":"Accounts","l":2,"d":"A retirement plan similar to a 401(k) for employees of public schools and certain nonprofits.","u":"Retirement saving in those sectors.","m":"Older 403(b) plans sometimes offer high-fee annuity products; check the options."},
{"t":"457(b)","c":"Accounts","l":3,"d":"A deferred compensation plan for state and local government and some nonprofit employees.","u":"Additional retirement saving.","m":"Governmental 457(b) withdrawals after leaving the employer are not subject to the 10% early-withdrawal tax."},
{"t":"50/30/20 rule","a":["balanced money formula","50-30-20 rule"],"c":"Planning","l":1,"mod":"INV-018","d":"A rule of thumb that splits take-home pay into about 50% needs, 30% wants and 20% savings and extra debt payments, popularized by Elizabeth Warren and Amelia Warren Tyagi as the Balanced Money Formula.","u":"A quick check of whether a spending plan is structurally balanced.","m":"It is a heuristic, not a finding. In expensive cities or with student loans, needs often exceed 50%; the point is to see where change would matter most."},
{"t":"529 plan","c":"Accounts","l":1,"d":"A state-sponsored education savings account with tax-free growth and withdrawals for qualified education expenses.","u":"Saving for college and certain other education costs.","m":"Many states offer a deduction; unused money can, within limits, roll to the beneficiary's Roth IRA."},
{"t":"529 superfunding","a":["five-year election"],"c":"Accounts","l":2,"mod":"INV-092","d":"Contributing up to five years' worth of annual gift exclusions to one beneficiary's 529 plan at once and electing on Form 709 to treat it as made evenly over five years (IRC 529(c)(2)(B)).","u":"Getting a large sum growing tax-free early; moving money out of a grandparent's estate.","m":"For 2026 that is up to $95,000 per donor, $190,000 per couple, per beneficiary; no more exclusion gifts to that person for five years."},
{"t":"529-to-Roth rollover","c":"Accounts","l":3,"d":"A SECURE 2.0 provision allowing unused 529 money to be rolled into the beneficiary's Roth IRA, up to a lifetime limit of $35,000, if the account has been open at least 15 years, subject to annual Roth limits.","u":"Reducing the risk of overfunding a 529.","m":"Contributions from the last five years are not eligible."},
{"t":"60/40 portfolio","c":"Portfolio","l":1,"mod":"INV-004","d":"A portfolio of about 60% stocks and 40% bonds.","u":"A classic balanced benchmark.","m":"Over 1928–2025 it grew about 8.3% a year with about 62% of stocks' volatility (with 10-year Treasuries)."},
{"t":"72(t) distributions","a":["SEPP","substantially equal periodic payments"],"c":"Retirement","l":3,"d":"A series of substantially equal periodic payments from an IRA or plan that avoids the 10% early-withdrawal tax.","u":"Accessing retirement money before 59½.","m":"Must continue for five years or until 59½, whichever is later; breaking the schedule triggers penalties."},
{"t":"83(b) election","c":"Taxes","l":3,"d":"An election, filed within 30 days of receiving restricted stock, to be taxed on its value now rather than at vesting.","u":"Early-stage company equity.","m":"Can save tax if the stock rises; the tax paid is lost if the shares are forfeited."},
{"t":"ABLE account","c":"Accounts","l":3,"d":"A tax-advantaged savings account for people whose disability began before a qualifying age, with limited effect on means-tested benefits.","u":"Saving for disability-related expenses.","m":"Complements, rather than replaces, a special needs trust."},
{"t":"ABLE to Work","c":"Accounts","l":3,"mod":"INV-102","d":"The rule allowing a working ABLE beneficiary without employer retirement contributions to contribute extra, up to the lesser of their pay or the prior year's one-person poverty line ($15,960 in the continental US for 2026), above the $20,000 standard limit. P.L. 119-21 made it permanent.","u":"Letting people with disabilities who work save more of their own earnings.","m":"A working beneficiary in 2026 could see up to $35,960 go into the account.","a":[]},
{"t":"Above-the-line deduction","a":["adjustments to income"],"c":"Taxes","l":2,"mod":"INV-029","d":"A subtraction taken before adjusted gross income is calculated, such as deductible traditional IRA or HSA contributions, student loan interest and half of self-employment tax.","u":"Lowering AGI, which many credits and income limits depend on, whether or not you itemize.","m":"These are worth more than they look, because a lower AGI can also keep you under a phase-out."},
{"t":"ACATS","a":["Automated Customer Account Transfer Service","account transfer"],"c":"Markets","l":1,"mod":"INV-104","d":"The electronic system, run by the National Securities Clearing Corporation, used for most transfers of brokerage accounts between US firms. Under FINRA Rule 11870 the old firm must validate or take exception within one business day and complete the transfer within three business days after validation.","u":"Moving an account, whole or in part, to a new brokerage.","m":"Start the transfer at the new firm. Your holdings move in kind; you do not have to sell anything."},
{"t":"Account consolidation","c":"Accounts","l":1,"mod":"INV-059","d":"Combining accounts of the same tax type, such as several old 401(k)s and IRAs into one rollover IRA, by direct rollover or transfer.","u":"Lower fees, one clear view of your allocation, and fewer beneficiary forms and RMD calculations.","m":"Aim for one account per tax type, not one account: pre-tax, Roth and taxable money cannot be merged without tax consequences.","a":[]},
{"t":"Account statement","a":["brokerage statement"],"c":"Accounts","l":1,"mod":"INV-057","d":"A periodic report from a brokerage or plan showing positions, balances, income, fees and activity. FINRA Rule 2231 requires brokerage firms to send one at least once every calendar quarter.","u":"Checking that your account reflects your decisions and separating your contributions from investment gains.","m":"Read every statement when it arrives. A return that never varies with the market is a classic sign of fraud."},
{"t":"Account takeover","a":["customer account takeover","ATO"],"c":"Behavior","l":1,"mod":"INV-104","d":"Criminals gaining unauthorized access to a financial account by stealing login or security information or using other cyber-enabled fraud.","u":"Describing a major source of theft from brokerage and bank accounts.","m":"Unique passwords, multi-factor authentication, alerts and never clicking links in messages stop most attempts."},
{"t":"Accredited investor","c":"Advice & regulation","l":3,"d":"An SEC category of investors, defined by income, net worth or credentials, permitted to buy certain private offerings.","u":"Access to private funds and deals.","m":"Qualifying does not make private investments suitable."},
{"t":"Accrued interest","c":"Asset classes","l":3,"mod":"INV-009","d":"The part of a bond's next coupon that the seller earned before the trade. The buyer pays it to the seller on top of the quoted price.","u":"Settling bond trades between coupon dates.","m":"Your trade confirmation shows the clean price plus accrued interest; you get it back in the next coupon.","a":[]},
{"t":"Active investing","c":"Strategies","l":1,"d":"Selecting securities or timing trades to try to beat a benchmark.","u":"Seeking above-market returns.","m":"After costs, most active funds have trailed their benchmarks over long periods."},
{"t":"Active participation","c":"Real estate","l":2,"mod":"INV-068","d":"A low standard of involvement in a rental, such as approving tenants, setting rents and approving repairs, while owning at least 10% of the property.","u":"Qualifying for the special $25,000 allowance for rental real estate losses.","m":"Most individual landlords meet it; limited partners in syndications generally do not.","a":[]},
{"t":"Active share","a":[],"c":"Strategies","l":2,"mod":"INV-045","d":"The percentage of a portfolio's holdings that differ from its benchmark: half the sum of the absolute differences in weights.","u":"Measuring how much actual management a fund delivers.","m":"A fund with a high fee and low active share charges a lot for the small part that is actually managed."},
{"t":"Actively managed fund","c":"Vehicles","l":1,"d":"A fund whose managers select investments trying to beat a benchmark.","u":"Seeking above-market returns.","m":"Higher costs; most trail their benchmarks over long periods (INV-043)."},
{"t":"Activities of daily living","a":["ADLs","ADL"],"c":"Insurance","l":1,"mod":"INV-083","d":"Basic self-care tasks: bathing, dressing, toileting, eating, continence and transferring in and out of a bed or chair.","u":"Measuring the need for long-term care. Tax-qualified LTC insurance generally pays when you need help with at least two for 90 days or more, or have severe cognitive impairment.","m":"Benefits start when a professional certifies you meet the trigger, not when you would like help."},
{"t":"Additional Medicare Tax","c":"Taxes","l":3,"mod":"INV-101","d":"A 0.9% tax on wages and self-employment income above $200,000 for single filers, $250,000 for joint filers and $125,000 for married filing separately (IRS Tax Topic 554).","u":"An extra Medicare tax on higher earners.","m":"It is not part of the half of SE tax you can deduct.","a":[]},
{"t":"Adjustable-rate mortgage","a":["ARM"],"c":"Real estate","l":2,"d":"A mortgage whose rate is fixed for an initial period and then adjusts periodically with an index.","u":"Lower initial payments.","m":"Know the caps and the worst-case payment."},
{"t":"Adjusted basis","c":"Taxes","l":2,"mod":"INV-035","d":"Cost basis after adjustments: increased by commissions, reinvested dividends, income already taxed on employee shares and disallowed wash-sale losses; decreased by returns of capital.","u":"Computing gain or loss: amount realized minus adjusted basis.","m":"Every documented dollar of basis is a dollar that is not taxed again.","a":[]},
{"t":"Adjusted gross income","a":["AGI"],"c":"Taxes","l":2,"d":"Gross income minus certain adjustments such as traditional IRA and HSA contributions.","u":"The basis for many thresholds and phase-outs.","m":"Lowering AGI can unlock credits and reduce taxes on other income."},
{"t":"Adjusted taxable gifts","c":"Estate","l":3,"mod":"INV-088","d":"Taxable gifts made after 1976 (above the annual exclusions and not otherwise excluded) that are added back to the taxable estate when computing estate tax.","u":"Putting lifetime gifts and transfers at death on one rate schedule.","m":"They are added back at their value when given, so later growth on gifted assets escapes estate tax.","a":[]},
{"t":"Adverse action notice","c":"Real estate","l":2,"mod":"INV-067","d":"A notice required by the Fair Credit Reporting Act when a landlord or lender takes a negative action based on a consumer report, naming the reporting company and explaining the applicant's rights to a free copy and to dispute errors.","u":"Letting applicants find and correct mistakes in their reports.","m":"Build it into your process; it is a legal requirement, not a courtesy.","a":[]},
{"t":"Advice-only planner","a":["flat-fee advisor","hourly financial planner","retainer fee","project fee"],"c":"Advice & regulation","l":2,"mod":"INV-103","d":"A planner paid a flat, hourly, retainer or one-time project fee for advice, without managing your assets for a percentage fee.","u":"Written plans, second opinions and specific decisions for people who will implement the advice themselves.","m":"The price is visible and does not rise as your portfolio grows, but you must carry out the trades and rebalancing yourself."},
{"t":"Advisory fee","a":["AUM fee","assets under management fee"],"c":"Costs","l":1,"mod":"INV-007","d":"What an investment adviser charges, often a percentage of assets managed, a flat fee or an hourly rate.","u":"Paying for investment management and planning.","m":"Know what the fee buys and how it grows as your balance grows."},
{"t":"Affinity fraud","c":"Advice & regulation","l":1,"mod":"INV-062","d":"Investment fraud aimed at members of a group, such as a religious, ethnic, professional, military or senior community, often spread by trusted members who are themselves victims.","u":"Recognizing schemes that travel through trust instead of evidence.","m":"Check the seller and the investment yourself, however much you trust the person who told you.","a":[]},
{"t":"After-repair value","a":["ARV"],"c":"Real estate","l":2,"mod":"INV-070","d":"The expected appraised value of a property once renovations are complete.","u":"Planning a BRRRR refinance, whose loan is a percentage of the appraisal.","m":"A 10% lower appraisal can leave tens of thousands of dollars stuck in the deal."},
{"t":"After-tax asset allocation","c":"Portfolio","l":3,"mod":"INV-036","d":"Your stock-bond mix measured after restating each account in after-tax dollars, for example counting a tax-deferred balance at (1 minus your future tax rate).","u":"Comparing asset placements at equal after-tax risk.","m":"Two portfolios that are both 60/40 on the statement can differ by several points of stock exposure after tax.","a":[]},
{"t":"Age 60–63 catch-up","a":["super catch-up","age 60-63 catch-up"],"c":"Accounts","l":2,"mod":"INV-031","d":"A larger catch-up contribution under SECURE 2.0 for workers who turn 60, 61, 62 or 63 during the year: $11,250 for 2026 in 401(k), 403(b), governmental 457(b) and TSP plans ($5,250 in SIMPLE plans), if the plan allows it.","u":"Letting late savers contribute more just before retirement.","m":"It reverts to the regular catch-up in the year you turn 64."},
{"t":"Age-based allocation rule","a":["110 minus age","100 minus age","age in bonds"],"c":"Portfolio","l":1,"mod":"INV-049","d":"A formula that sets the stock share from age, such as stocks = 110 minus your age, so the mix becomes more conservative every year.","u":"A simple, self-adjusting starting point for a stock-bond mix.","m":"It ignores pensions, Social Security, job stability and savings; adjust it for your whole balance sheet."},
{"t":"Alimony","a":["spousal support","separate maintenance"],"c":"Taxes","l":1,"mod":"INV-095","d":"Payments to a spouse or former spouse under a divorce or separation instrument.","u":"Supporting a lower-earning spouse after separation or divorce.","m":"Under agreements executed after 2018, alimony is not deductible by the payer and not taxable to the recipient. Older agreements keep the old treatment unless modified to adopt the new rule."},
{"t":"All Weather portfolio","a":["risk parity"],"c":"Strategies","l":3,"d":"An approach, associated with Bridgewater, that balances risk across assets expected to do well in different economic environments; risk parity weights assets by their risk contribution.","u":"Diversifying across growth and inflation regimes.","m":"Often uses leverage in institutional form; simple retail versions differ."},
{"t":"Allocation drift","a":["drift"],"c":"Portfolio","l":1,"mod":"INV-028","d":"The movement of a portfolio's actual mix away from its target as different assets earn different returns.","u":"Judging when to rebalance.","m":"A 60/40 portfolio left alone from 2000 swung from 34% stocks at the end of 2008 to 81% by 2025."},
{"t":"Allocation model","a":["model portfolio"],"c":"Portfolio","l":1,"mod":"INV-049","d":"A named, rule-based recipe for dividing money among asset classes, such as 60/40 or 25% each in four assets, usually with a rule for restoring the targets.","u":"Replacing moment-to-moment judgment with a plan you can follow in frightening markets.","m":"Pick one whose worst historical year you have looked at and could live through."},
{"t":"Alpha","a":["excess return","risk-adjusted excess return"],"c":"Strategies","l":2,"mod":"INV-043","d":"The part of an investment's return not explained by the market or by other risks it took. A fund that earned 9% when a benchmark of the same risk earned 8% has an alpha of about +1%.","u":"Judging whether a manager added value beyond an index fund of similar risk.","m":"Alpha is what an active fee buys, if anything. After costs, the average alpha across all active funds is negative."},
{"t":"Alternate payee","c":"Retirement","l":3,"mod":"INV-095","d":"The spouse, former spouse, child or other dependent named in a qualified domestic relations order to receive part of a plan participant's benefit.","u":"Identifying who receives plan money under a divorce or support order.","m":"A spouse or former spouse is taxed as if they were the participant; payments to a child are taxed to the participant.","a":[]},
{"t":"Alternate valuation date","c":"Estate","l":3,"mod":"INV-090","d":"An executor's election to value an entire estate six months after death instead of on the date of death; assets sold or distributed within those six months are valued on that date (IRC 2032).","u":"Reducing estate tax after a fall in values. Allowed only if it lowers both the gross estate and the estate tax.","m":"It lowers heirs' basis too, so it matters only for estates that owe estate tax.","a":[]},
{"t":"Alternative minimum tax","a":["AMT"],"c":"Taxes","l":3,"d":"A parallel federal tax calculation that limits certain deductions and preferences; you pay the higher of regular tax or AMT.","u":"Relevant to incentive stock options and high state taxes.","m":"Exercising ISOs can trigger AMT even without selling shares."},
{"t":"American opportunity tax credit","a":["AOTC","American opportunity credit"],"c":"Taxes","l":2,"mod":"INV-034","d":"A credit of up to $2,500 per student per year for the first four years of college (100% of the first $2,000 of qualified expenses plus 25% of the next $2,000), partly refundable, phased out between modified AGI of $80,000 and $90,000 ($160,000–$180,000 joint).","u":"Reducing the cost of college for moderate-income families.","m":"Pay $4,000 of tuition from sources other than tax-free 529 withdrawals to claim the full credit."},
{"t":"Amortization","c":"Real estate","l":2,"d":"Repaying a loan in scheduled payments that cover interest and gradually reduce principal.","u":"Mortgages and car loans.","m":"Early payments are mostly interest; extra principal payments save the most early on."},
{"t":"Anchoring","c":"Behavior","l":2,"d":"Relying too heavily on a reference number, such as the price you paid.","u":"Explaining reluctance to sell losers.","m":"The market does not know or care what you paid."},
{"t":"Ancillary probate","c":"Estate","l":2,"mod":"INV-086","d":"A second probate proceeding in another state where the decedent owned real estate.","u":"Transferring out-of-state real property, which only that state's courts can do.","m":"Owning a vacation home in another state can double the probate work; a funded revocable trust or, where allowed, a transfer-on-death deed avoids it.","a":[]},
{"t":"Annual additions limit","a":["415(c) limit"],"c":"Accounts","l":3,"mod":"INV-031","d":"The cap on everything added to one person's defined contribution account in a year, employee plus employer plus after-tax money, excluding catch-ups: $72,000 for 2026.","u":"Limiting total workplace plan contributions; the room used by the mega backdoor Roth.","m":"A worker deferring $24,500 with a $12,000 match has $35,500 of room for after-tax contributions if the plan allows them."},
{"t":"Annual gift exclusion","c":"Estate","l":2,"d":"The amount you can give each recipient per year without using any lifetime exemption or filing a gift tax return; indexed for inflation.","u":"Tax-free family gifting.","m":"Married couples can give twice the amount per recipient."},
{"t":"Annual review","c":"Planning","l":1,"mod":"INV-058","d":"A scheduled, once-a-year check of a financial plan against a fixed list: allocation, contributions, costs, taxes, insurance, beneficiaries and goals.","u":"Catching slow changes before they become expensive.","m":"Most good reviews end with no change, and a written note that you checked.","a":[]},
{"t":"Annualized installment method","c":"Taxes","l":3,"mod":"INV-101","d":"A way of figuring required estimated tax payments on Form 2210 based on when income was actually received during the year.","u":"Lowering early-quarter payments when most income arrives late in the year.","m":"Useful for seasonal or back-loaded self-employment income.","a":[]},
{"t":"Annualized return","c":"Foundations","l":1,"mod":"INV-057","d":"The constant yearly rate that, compounded, produces the same total growth as an investment achieved over a period: (1 + total return)^(1/years) - 1.","u":"Comparing results over periods of different length.","m":"A 50% gain over five years is 8.45% a year, not 10%. Do not annualize periods shorter than a year.","a":[]},
{"t":"Annuity","a":["annuity (finance)"],"c":"Foundations","l":2,"mod":"INV-002","d":"In finance math, a series of equal payments at regular intervals. The same word also names an insurance product that pays income.","u":"Loan payments, retirement withdrawals, pension streams.","m":"Know which meaning is intended: the formula, or a product with its own fees and guarantees."},
{"t":"Annuity (insurance product)","a":["fixed annuity","variable annuity","income annuity","SPIA"],"c":"Insurance","l":2,"mod":"INV-007","d":"A contract with an insurance company that can provide guaranteed income, tax-deferred growth, or both.","u":"Turning savings into lifetime income; tax-deferred accumulation.","m":"Simple income annuities can be valuable; complex variable annuities often carry high fees and surrender charges."},
{"t":"Applicable federal rate","a":["AFR","federal mid-term rate"],"c":"Taxes","l":3,"mod":"INV-074","d":"Interest rates the IRS publishes monthly by revenue ruling for short-, mid- and long-term debt.","u":"Setting minimum rates on family loans and, for 72(t), the cap: the greater of 5% or 120% of the federal mid-term rate for either of the two months before payments start.","m":"For September 2026, 120% of the mid-term rate was 5.40% (Rev. Rul. 2026-17)."},
{"t":"APR","a":["annual percentage rate"],"c":"Foundations","l":2,"mod":"INV-002","d":"The yearly interest rate quoted on loans, usually without including the effect of compounding within the year.","u":"Comparing loan and credit card rates.","m":"A 22% APR compounded monthly grows a balance at about 24.4% a year."},
{"t":"APY","a":["annual percentage yield"],"c":"Foundations","l":2,"mod":"INV-002","d":"The effective yearly return including compounding: (1 + APR ÷ m)^m − 1.","u":"Comparing savings accounts and CDs.","m":"For savings, compare APYs; for debt, convert APRs to effective rates."},
{"t":"Arithmetic average return","c":"Foundations","l":2,"mod":"INV-003","d":"The simple average of periodic returns: add them and divide by the number of periods.","u":"Estimating a single future period's expected return.","m":"Overstates what a buy-and-hold investor experienced when returns vary."},
{"t":"Arithmetic of active management","c":"Strategies","l":2,"mod":"INV-007","d":"William Sharpe's 1991 observation that, before costs, the average active dollar earns the market return, so after costs it must trail the average passive dollar.","u":"Explaining index-fund outperformance without assuming anyone is foolish.","m":"Costs are the reason the average active investor falls behind."},
{"t":"Ask","a":["offer"],"c":"Markets","l":1,"mod":"INV-005","d":"The lowest price a seller is currently willing to accept.","u":"The price you pay when you buy immediately.","m":"Large orders may fill at several ask levels ('walk the book')."},
{"t":"Assessed value","c":"Real estate","l":2,"mod":"INV-068","d":"The value a local assessor assigns to a property for tax purposes, often a set percentage of market value.","u":"The base to which the mill levy or tax rate is applied; the IRS also allows using the assessment's land-building split to allocate basis.","m":"You can usually appeal an assessment that is too high; the deadline is short.","a":[]},
{"t":"Asset","c":"Foundations","l":1,"d":"Anything of value that is owned: cash, investments, property, a business.","u":"Measuring net worth; building a portfolio.","m":"Financial assets are only half the picture; your future earnings are often your largest asset while you work."},
{"t":"Asset allocation","c":"Portfolio","l":1,"d":"How a portfolio is divided among asset classes such as stocks, bonds and cash.","u":"The main driver of a portfolio's risk and long-run return.","m":"Choosing it well matters more than choosing individual funds."},
{"t":"Asset location","c":"Taxes","l":2,"d":"Placing investments in the account type where they are taxed most favorably, such as bonds in tax-deferred accounts.","u":"Improving after-tax returns without changing the overall mix.","m":"Different from asset allocation, which is what you own."},
{"t":"Assets under management","a":["AUM","regulatory assets under management","RAUM"],"c":"Advice & regulation","l":2,"mod":"INV-103","d":"The value of the client assets an adviser manages. Regulatory assets under management also decide where an adviser registers: generally the SEC above $110 million, the states below $100 million.","u":"Setting percentage-of-assets fees and determining an adviser's regulator.","m":"An AUM fee grows automatically with your balance; the work it pays for usually does not grow as fast."},
{"t":"Assignment","a":["early assignment","exercise assignment"],"c":"Asset classes","l":3,"mod":"INV-016","d":"The notice to an option writer that a holder has exercised, obligating the writer to deliver (call) or buy (put) the underlying or pay cash. For American-style options it can come at any time before expiration.","u":"Settling exercised options through the Options Clearing Corporation and brokers.","m":"If you sell options, you may have to buy or deliver shares on short notice, and call writers face higher assignment risk just before a dividend."},
{"t":"Authorized participant","a":["AP"],"c":"Vehicles","l":3,"mod":"INV-012","d":"A large financial firm with an agreement to create and redeem an ETF's shares directly with the fund, in large blocks (often 50,000 shares or more), usually by exchanging baskets of securities.","u":"Keeping an ETF's market price close to its net asset value through arbitrage.","m":"You never deal with one, but their in-kind redemptions are why many ETFs rarely distribute capital gains."},
{"t":"Availability heuristic","c":"Behavior","l":2,"mod":"INV-060","d":"Judging how likely something is by how easily examples come to mind.","u":"Explaining why vivid news, such as a recent crash, feels more probable than it is.","m":"Base decisions on long-run data, not on the most memorable headline.","a":[]},
{"t":"Average cost basis","a":["average basis"],"c":"Taxes","l":2,"mod":"INV-035","d":"A method that uses the average cost of all shares held as the basis of each share sold. Allowed for mutual fund shares and certain dividend-reinvestment shares, not for ordinary individual stock.","u":"Simplifying basis for funds bought many times.","m":"Once chosen for a fund, it generally must continue unless the election is revoked under IRS rules."},
{"t":"Average indexed monthly earnings","a":["AIME"],"c":"Retirement","l":3,"mod":"INV-078","d":"Your average monthly earnings over your 35 highest-earning years, with earlier years scaled up by the growth in national average wages to the year you turn 60, rounded down to the dollar.","u":"The input to the Social Security benefit formula.","m":"Fewer than 35 years of work means zeros in the average; a high-earning 36th year replaces a low one."},
{"t":"Average period of customer use","c":"Taxes","l":3,"mod":"INV-070","d":"Total days in all rental periods divided by the number of rentals in the year.","u":"Deciding whether a rental is a 'rental activity' under the passive loss rules: at 7 days or less it is not.","m":"A short-term rental with a 3-night average stay is treated like a business; losses are nonpassive only if you materially participate.","a":[]},
{"t":"Backdoor Roth IRA","c":"Taxes","l":3,"d":"Making a nondeductible traditional IRA contribution and converting it to a Roth, used by those above the Roth income limits.","u":"Roth access for higher earners.","m":"The pro-rata rule taxes the conversion based on all your pre-tax IRA balances."},
{"t":"Backtest","a":["backtesting"],"c":"Portfolio","l":2,"mod":"INV-104","d":"Applying an investment rule or allocation to past market data to see how it would have performed.","u":"Building intuition about how portfolios behaved in different historical periods.","m":"A backtest is one path through history. The same 60/40 mix earned from 3.5% to 14.8% a year over different 20-year periods from 1928 to 2025."},
{"t":"Backwardation","a":["inverted market"],"c":"Asset classes","l":2,"mod":"INV-013","d":"A futures market in which contracts for later delivery cost progressively less than the nearest contract (CFTC definition). The opposite of contango.","u":"Signaling that the commodity is scarce now; estimating a positive roll yield.","m":"In backwardation, rolling futures adds to a fund's return, so the fund can beat the spot price."},
{"t":"Balance sheet","c":"Companies","l":1,"mod":"INV-006","d":"A snapshot of what a company owns (assets), owes (liabilities) and the owners' residual (equity) on one date. Assets = liabilities + equity.","u":"Judging financial strength and debt.","m":"High debt makes shares riskier because lenders are paid first."},
{"t":"Balanced fund","c":"Vehicles","l":2,"d":"A fund holding both stocks and bonds in a roughly fixed proportion, such as 60/40.","u":"One-fund diversified investing.","m":"Rebalances automatically."},
{"t":"Balloon payment","c":"Real estate","l":2,"mod":"INV-066","d":"A large lump sum due at the end of a loan whose regular payments do not fully repay it, common on commercial and some investor loans.","u":"Lowering payments during the term of a short loan.","m":"You must refinance or sell before the balloon; if rates rise or values fall first, that can be impossible.","a":[]},
{"t":"Bank sweep program","a":[],"c":"Accounts","l":2,"mod":"INV-008","d":"A brokerage feature that automatically moves uninvested cash into deposits at one or more partner banks, where it is FDIC-insured up to the limits; the brokerage or its affiliate sets the interest rate.","u":"Holding idle cash in brokerage and advisory accounts.","m":"Sweep rates can be far below money market fund yields. The SEC found gaps of almost 4 percentage points at two large firms during a period of rising rates; check your account's sweep rate."},
{"t":"Bargain element","a":["option spread"],"c":"Taxes","l":3,"mod":"INV-040","d":"The difference between a stock's market value and the option's exercise price when an option is exercised.","u":"Measuring wage income on NSOs and the AMT adjustment on ISOs.","m":"ISO bargain elements held past year-end count toward the alternative minimum tax."},
{"t":"Barista FI","c":"Independence","l":3,"d":"A partial financial independence in which part-time work covers some expenses and benefits.","u":"Semi-retirement planning.","m":"Health insurance before Medicare is often the deciding factor."},
{"t":"Basic exclusion amount","a":["lifetime exemption","BEA","estate tax exemption"],"c":"Estate","l":1,"mod":"INV-088","d":"The amount each person can transfer by lifetime taxable gifts and at death combined before federal gift or estate tax is due: $15,000,000 for 2026 (IRS, Rev. Proc. 2025-32, under Public Law 119-21), indexed for inflation from 2027.","u":"Computing the unified credit and the Form 706 filing requirement.","m":"Unless your estate plus lifetime taxable gifts exceeds it (or twice it for a married couple using portability), no federal transfer tax is due."},
{"t":"Basis point","a":["bp","bps"],"c":"Foundations","l":2,"mod":"INV-009","d":"One hundredth of a percentage point: 0.01%. 100 basis points = 1 percentage point.","u":"Quoting small changes in yields, spreads and fees without confusion.","m":"'Yields rose 25 basis points' means from, say, 4.00% to 4.25%. An expense ratio of 0.05% is 5 basis points."},
{"t":"Bear market","c":"Markets","l":1,"d":"A sustained decline, often defined as a 20% fall from a peak.","u":"Describing market conditions.","m":"Bear markets are normal; planning for them is part of investing."},
{"t":"Behavior gap","c":"Behavior","l":2,"d":"The difference between an investment's reported return and the average return its investors actually earned, due to the timing of purchases and sales.","u":"Measuring the cost of investor behavior.","m":"Chasing performance and panic selling create the gap."},
{"t":"Below-market loan","a":["gift loan"],"c":"Taxes","l":3,"mod":"INV-092","d":"A loan charging less than the applicable federal rate. Under IRC 7872, the forgone interest on a gift loan is treated as a gift to the borrower and as interest income to the lender, with exceptions for small loans.","u":"Deciding whether an interest-free family loan has tax consequences.","m":"Loans between two people totaling $10,000 or less are generally exempt; up to $100,000 the imputed interest is limited to the borrower's net investment income."},
{"t":"Benchmark","c":"Portfolio","l":1,"d":"An index or blend used to judge an investment's performance.","u":"Measuring whether a fund or strategy added value.","m":"Compare like with like: a bond fund against a bond index."},
{"t":"Benchmark plan","a":["second-lowest-cost silver plan","SLCSP"],"c":"Insurance","l":2,"mod":"INV-074","d":"The second-lowest-cost silver plan available to you in the marketplace; its premium is the starting point for your premium tax credit.","u":"Computing the credit, which you can then apply to any metal level.","m":"KFF reports the 2026 national average benchmark for a 40-year-old at $625 a month; older adults pay up to three times a 21-year-old's rate."},
{"t":"Bend points","c":"Retirement","l":3,"mod":"INV-078","d":"The dollar amounts in the Social Security benefit formula where the replacement percentage changes. For people first eligible in 2026 they are $1,286 and $7,749 of AIME: 90% below the first, 32% between them, 15% above.","u":"Calculating the primary insurance amount; they rise each year with average wages.","m":"They make the formula progressive: the first dollars of average earnings are replaced at 90%, the last at 15%.","a":[]},
{"t":"Beneficiary designation","c":"Estate","l":1,"d":"A form naming who receives an account, such as an IRA, 401(k) or life insurance policy, at death.","u":"Passing accounts directly, outside probate.","m":"It overrides your will; review it after marriage, divorce, births and deaths."},
{"t":"Beta","a":["market beta"],"c":"Portfolio","l":2,"mod":"INV-048","d":"A measure of how much an investment tends to move when the market moves. A beta of 1.5 tends to rise or fall 50% more than the market.","u":"Estimating market risk and, in the CAPM, expected return.","m":"Lowering a portfolio's overall beta is mainly done with bonds. High-beta stocks have not compounded faster than low-beta ones."},
{"t":"Bid","c":"Markets","l":1,"mod":"INV-005","d":"The highest price a buyer is currently willing to pay for a security.","u":"The price you receive when you sell immediately.","m":"In thinly traded securities the bid can be well below the last trade."},
{"t":"Bid-ask spread","a":["spread"],"c":"Markets","l":1,"mod":"INV-005","d":"The difference between the bid and the ask; a cost paid on each round trip.","u":"Measuring trading cost and liquidity.","m":"Pennies for large ETFs and stocks; much wider for small stocks, some bonds and after-hours trading."},
{"t":"Blended benchmark","a":["composite benchmark"],"c":"Portfolio","l":2,"mod":"INV-057","d":"A benchmark made by weighting several indexes in the same proportions as a portfolio's target allocation.","u":"Judging a multi-asset portfolio, an advisor or a fund against a low-cost version of the same allocation.","m":"A 60/40 portfolio should be judged against a 60/40 blend, not against the S&P 500 alone."},
{"t":"Blended family","c":"Planning","l":1,"mod":"INV-027","d":"A family that includes children from a previous relationship of one or both partners.","u":"Framing the planning question of how to provide for a new spouse and for children of an earlier marriage.","m":"Default beneficiary forms and titles often send everything to the new spouse; write your intentions into every form.","a":[]},
{"t":"Blockchain","a":["distributed ledger"],"c":"Asset classes","l":1,"mod":"INV-015","d":"A shared record of transactions, grouped into blocks that are linked in order and copied across many computers, so that no single party can quietly rewrite the history.","u":"Recording ownership and transfers of bitcoin and other crypto assets without a central bookkeeper.","m":"The ledger can be secure while the businesses built around it, such as exchanges and lenders, are not."},
{"t":"Bogleheads","c":"Strategies","l":1,"d":"Followers of Vanguard founder John C. Bogle's philosophy: low costs, broad diversification, index funds and staying the course.","u":"A widely followed DIY investing approach.","m":"Its wiki and forum are major free learning resources."},
{"t":"Bond","a":["fixed income"],"c":"Asset classes","l":1,"mod":"INV-001","d":"A loan to a government or company that pays interest and repays principal on a set date.","u":"Income and stability; balancing stock risk.","m":"Bond prices fall when interest rates rise, as in 2022."},
{"t":"Bond ladder","c":"Asset classes","l":2,"d":"A set of bonds maturing in successive years, so principal comes due on a schedule.","u":"Funding known future expenses, such as early retirement years.","m":"Holding each bond to maturity removes price risk for that year's spending."},
{"t":"Bond premium and discount","a":["premium bond","discount bond"],"c":"Asset classes","l":2,"mod":"INV-009","d":"A bond trades at a premium when its price is above par and at a discount when below; premiums arise when its coupon exceeds current market yields, discounts when it is lower.","u":"Reading bond quotes and understanding why prices drift toward par.","m":"Neither is a bargain or a rip-off by itself. At the same yield to maturity, the market has priced them to the same expected return."},
{"t":"Bonus depreciation","a":["special depreciation allowance"],"c":"Taxes","l":3,"mod":"INV-068","d":"An extra first-year deduction for qualified property with a recovery period of 20 years or less. Public Law 119-21 permanently restored the 100% allowance for property acquired and placed in service after January 19, 2025.","u":"Deducting the full cost of short-life items, such as those found by a cost segregation study, in the first year.","m":"The 27.5-year building itself does not qualify, and the deduction is only useful if you can use the resulting loss; it is recaptured as ordinary income when you sell."},
{"t":"Book value","a":["shareholders' equity"],"c":"Companies","l":2,"mod":"INV-006","d":"Assets minus liabilities on the balance sheet: the accounting value of the owners' stake.","u":"Valuing asset-heavy firms; price-to-book ratios.","m":"Brands, software and know-how are often barely recorded, so many strong firms trade far above book."},
{"t":"Book-to-market ratio","a":["B/M","book-to-market"],"c":"Valuation","l":2,"mod":"INV-046","d":"A company's book value (assets minus liabilities) divided by its market value; the inverse of price-to-book.","u":"The academic definition of value: the highest book-to-market stocks are 'value,' the lowest 'growth.'","m":"One simple lens. Companies whose main assets are brands, software or research can look expensive on book value while earning a lot."},
{"t":"Boot","c":"Real estate","l":3,"mod":"INV-068","d":"Cash or other property that is not like-kind received in an exchange, including liabilities taken off your hands that you do not replace.","u":"Measuring the taxable part of an otherwise tax-deferred exchange.","m":"Taking some cash out of a 1031 exchange makes that part of the gain taxable now.","a":[]},
{"t":"Bootstrapping","a":["bootstrap resampling","resampling"],"c":"Retirement","l":3,"mod":"INV-077","d":"Building simulated return paths by drawing whole historical years at random, with replacement, keeping each year's stock return, bond return and inflation together.","u":"Monte Carlo simulation that uses the real shape of past returns instead of a bell curve.","m":"Each year is real but the order is random, so multi-year patterns such as the 1970s inflation are broken up."},
{"t":"Bracket filling","a":["filling the bracket"],"c":"Taxes","l":2,"mod":"INV-038","d":"Adding just enough income in a year, often through a Roth conversion or IRA withdrawal, to reach the top of a chosen tax bracket without going over.","u":"Using low brackets that would otherwise go unused.","m":"Room in a bracket = bracket top + deductions - other income."},
{"t":"Break-even age","c":"Retirement","l":2,"mod":"INV-078","d":"The age at which the total received from claiming a benefit later catches up with the total from claiming earlier, ignoring interest, taxes and inflation adjustments. With an FRA of 67, waiting from 62 to 70 breaks even at about 80.4.","u":"A rough guide to how long you must live for delaying to pay off.","m":"The real question is insurance against a long life; for a married higher earner the larger check may also continue to a survivor.","a":[]},
{"t":"Breakeven inflation rate","a":["breakeven inflation"],"c":"Asset classes","l":3,"mod":"INV-010","d":"The nominal Treasury yield minus the TIPS real yield of the same maturity: the inflation rate at which the two would pay the same.","u":"Reading the market's inflation expectations and choosing between TIPS and nominal Treasuries.","m":"On September 25, 2026 the 10-year breakeven was 2.34% (5.17% minus 2.83%). If you expect higher inflation, TIPS win."},
{"t":"Breaking the buck","c":"Vehicles","l":2,"mod":"INV-008","d":"When a stable-price money market fund must re-price its shares below $1.00 because the market value per share has fallen by more than half a cent.","u":"Describing a rare failure of a money market fund's stable price.","m":"It shows that money market funds are investments, not insured deposits. The best-known case is the Reserve Primary Fund on September 16, 2008.","a":[]},
{"t":"Breakpoint","c":"Costs","l":3,"mod":"INV-007","d":"A purchase amount at which a fund's front-end sales load falls.","u":"Reducing sales charges on large purchases.","m":"Ask whether combining accounts qualifies you for a lower load."},
{"t":"Bridge years","c":"Independence","l":2,"mod":"INV-074","d":"The years between stopping work and the ages at which penalty-free retirement withdrawals (59½), Social Security (62 at the earliest) and Medicare (65) begin.","u":"Planning which accounts will pay for early retirement.","m":"A portfolio can be large enough on paper yet mostly locked behind the 59½ rule; the bridge must be built from reachable money.","a":[]},
{"t":"Broker-dealer","a":["broker","brokerage"],"c":"Markets","l":1,"mod":"INV-005","d":"A firm registered with the SEC and a member of FINRA that buys and sells securities for customers (broker) and for itself (dealer).","u":"Holding your investment accounts and executing trades.","m":"Check any firm on FINRA BrokerCheck and confirm SIPC membership."},
{"t":"Brokerage account","c":"Markets","l":1,"mod":"INV-005","d":"An account at a broker-dealer used to buy, sell and hold investments.","u":"Investing outside or inside tax-advantaged wrappers.","m":"The account type decides the tax treatment; the investments inside decide the risk."},
{"t":"Brokered CD","c":"Asset classes","l":2,"mod":"INV-008","d":"A bank certificate of deposit bought through a brokerage account rather than directly from the bank.","u":"Shopping CD rates across many banks from one account.","m":"Ask how you would get out early: if only by selling to another investor, you receive the market price, which falls when rates rise. The SEC notes deposit brokers are not licensed or approved by any agency.","a":[]},
{"t":"BRRRR","c":"Real estate","l":3,"d":"Buy, rehab, rent, refinance, repeat: a strategy of buying below value, improving the property, renting it and refinancing to pull capital out.","u":"Scaling a rental portfolio.","m":"Depends on accurate renovation costs and on lenders' appraisals; leverage cuts both ways."},
{"t":"Bubble","c":"Markets","l":1,"mod":"INV-006","d":"A period when prices rise far above what fundamentals can justify, driven by enthusiasm, then fall sharply.","u":"Describing episodes such as 1999–2000 technology stocks.","m":"Recognizable mostly in hindsight; diversification limits the damage."},
{"t":"Bucket strategy","c":"Retirement","l":2,"d":"Dividing retirement money into near-term (cash), medium-term (bonds) and long-term (stocks) buckets.","u":"Making retirement spending feel secure.","m":"Mathematically similar to a balanced portfolio; the value is behavioral."},
{"t":"Budget","a":["spending plan"],"c":"Planning","l":1,"d":"A plan for how income will be spent, saved and invested.","u":"Finding money to save; tracking progress.","m":"The goal is to direct money deliberately, not to record every coffee."},
{"t":"Bull market","c":"Markets","l":1,"d":"A sustained period of rising prices, often defined as a 20% rise from a low.","u":"Describing market conditions.","m":"Labels are descriptions after the fact, not forecasts."},
{"t":"Bunching","a":["deduction bunching"],"c":"Taxes","l":2,"mod":"INV-039","d":"Grouping several years of deductible spending, usually charitable gifts, into one tax year so that itemizing beats the standard deduction that year.","u":"Getting a deduction for gifts that would otherwise fall below the standard deduction.","m":"A donor-advised fund lets the charities still receive grants every year."},
{"t":"Buy and hold","a":["buy-and-hold"],"c":"Strategies","l":1,"mod":"INV-052","d":"Choosing a mix and keeping it through market cycles, rebalancing to targets rather than predicting the market.","u":"Capturing the market's long-run return with few decisions, low costs and low taxes.","m":"It is the benchmark any timing strategy must beat after costs, and the one it usually fails to beat."},
{"t":"Buy-sell agreement","c":"Estate","l":2,"mod":"INV-094","d":"A contract among business owners (and sometimes the business) setting who buys an owner's interest on death, disability, retirement or other events, at what price or formula, and how it is funded.","u":"Giving a departing owner's family a buyer and fair price, and remaining owners control over who their partners are.","m":"Review the price and the funding regularly, and follow the agreement's own valuation procedure.","a":[]},
{"t":"Calendar rebalancing","c":"Portfolio","l":2,"mod":"INV-028","d":"Rebalancing back to target on a fixed schedule, such as every January, whatever the drift.","u":"A simple rule that is easy to remember and automate.","m":"Combine it with a band (check on the date, act only if outside the band) to cut needless trades.","a":[]},
{"t":"Callable bond","a":["call risk","call provision"],"c":"Asset classes","l":2,"mod":"INV-009","d":"A bond the issuer may repay before maturity, usually after a set date and at par or a small premium.","u":"Giving issuers the option to refinance when rates fall.","m":"Issuers call when it suits them, when rates have fallen, so you lose a high coupon exactly when replacing it is hardest. Many municipal and corporate bonds are callable."},
{"t":"CAPE ratio","a":["Shiller P/E","cyclically adjusted price-to-earnings ratio"],"c":"Valuation","l":2,"mod":"INV-006","d":"The market's price divided by the average of the last ten years of inflation-adjusted earnings, popularized by Robert Shiller.","u":"Gauging market-wide valuation and long-term return expectations.","m":"Reached 44.2 in December 1999 and about 40.6 in September 2026 (long-run median about 16.6). A thermometer, not a timing tool."},
{"t":"Capital asset pricing model","a":["CAPM"],"c":"Portfolio","l":3,"mod":"INV-048","d":"The theory that expected return equals the risk-free rate plus beta times the market's expected premium over the risk-free rate (Sharpe, 1964).","u":"Estimating required returns and measuring alpha.","m":"It explains why diversifiable risk is not rewarded; its prediction that beta alone explains returns has not held up."},
{"t":"Capital call","a":["drawdown (private fund)"],"c":"Vehicles","l":3,"mod":"INV-014","d":"A request from a private fund's manager for investors to send part of the money they committed, usually over the first several years of the fund's life.","u":"Funding private equity, venture and private credit investments as deals are found.","m":"A commitment is a promise to pay on demand. You must keep cash ready for calls you cannot predict, and the fund agreement sets penalties for missing one."},
{"t":"Capital expenditure","a":["capex"],"c":"Companies","l":2,"mod":"INV-006","d":"Spending on long-lived assets such as buildings, equipment and software.","u":"Computing free cash flow.","m":"Businesses that need heavy capex to grow convert less profit into cash."},
{"t":"Capital gain","a":["capital gains"],"c":"Taxes","l":1,"d":"The profit when an asset is sold for more than its cost basis.","u":"Taxation of investment sales.","m":"Only realized when you sell; unrealized gains are not taxed."},
{"t":"Capital gains distribution","c":"Taxes","l":2,"mod":"INV-012","d":"A fund's payout of the net gains it realized from selling securities, passed through to shareholders.","u":"Distributing a fund's realized gains, which shareholders then report for tax.","m":"In a taxable account you owe tax on it even if you reinvest, and even in a year the fund's price fell. Check estimated distributions before buying a fund late in the year.","a":[]},
{"t":"Capital loss carryover","c":"Taxes","l":2,"mod":"INV-030","d":"Net capital losses beyond the $3,000 a year ($1,500 married filing separately) that can offset ordinary income, carried forward to later years without limit.","u":"Using large losses against future gains and income.","m":"A $12,000 net loss with no future gains takes four years to use at $3,000 a year.","a":[]},
{"t":"Capital reserve","a":["replacement reserve","capex reserve"],"c":"Real estate","l":2,"mod":"INV-065","d":"Money set aside each month for large, infrequent replacements such as a roof, water heater, HVAC system or flooring.","u":"Smoothing lumpy capital costs into a monthly budget line.","m":"A property that only cash-flows when you ignore the roof is not cash-flowing."},
{"t":"Capitalization rate","a":["cap rate"],"c":"Real estate","l":2,"d":"Net operating income divided by property value.","u":"Comparing income properties.","m":"A higher cap rate means more income per dollar of price, often with more risk."},
{"t":"Capitalization weighting","a":["cap weighting","market-cap weighting","cap-weighted"],"c":"Markets","l":1,"mod":"INV-044","d":"Holding each company in an index in proportion to its market value: share price times shares outstanding.","u":"Building indexes that mirror the market; needs almost no trading because weights move with prices.","m":"Your index fund owns the biggest companies most heavily; if a few giants dominate the market, they dominate your fund."},
{"t":"Capitulation","c":"Markets","l":2,"mod":"INV-061","d":"A phase of heavy, fearful selling late in a decline, when many investors give up at once.","u":"Describing the emotional bottom of a bear market.","m":"It is only recognizable afterward; selling in it locks in the loss.","a":[]},
{"t":"Carhart four-factor model","a":["Carhart model","four-factor model"],"c":"Strategies","l":3,"mod":"INV-048","d":"The Fama–French three factors (market, size, value) plus momentum, used by Mark Carhart (1997) to evaluate mutual funds.","u":"Separating manager skill from exposure to known factors.","m":"Much of what looks like a hot manager is exposure to momentum or other factors you could buy more cheaply."},
{"t":"Carryover basis","c":"Taxes","l":2,"mod":"INV-090","d":"The rule that a person who receives property as a gift takes the giver's adjusted cost basis (and holding period). If the property is worth less than that basis on the gift date, the recipient uses the lower value to measure a loss (IRC 1015).","u":"Measuring the recipient's gain when they sell a gifted asset.","m":"Giving appreciated shares moves the tax bill to the recipient instead of erasing it; holding them until death usually gets a stepped-up basis instead.","a":[]},
{"t":"Cash drag","c":"Costs","l":2,"mod":"INV-007","d":"The lower return from holding uninvested cash that earns little.","u":"Evaluating account sweep programs and fund cash holdings.","m":"Check what your brokerage cash actually earns."},
{"t":"Cash equivalents","c":"Asset classes","l":1,"d":"Very short-term, high-quality holdings that can be turned into cash quickly with little risk: money market funds, T-bills, short CDs.","u":"Emergency funds and near-term spending.","m":"Safe in dollars, but typically only roughly keep pace with inflation."},
{"t":"Cash flow","a":["household cash flow"],"c":"Planning","l":1,"d":"The money coming in and going out of a household over a period.","u":"The starting point of any financial plan.","m":"Positive cash flow is what funds every other goal."},
{"t":"Cash flow statement","c":"Companies","l":1,"mod":"INV-006","d":"A statement of actual cash moving in and out, grouped into operating, investing and financing activities.","u":"Testing whether profits turn into cash.","m":"Persistently weak cash flow alongside rising profits deserves scrutiny."},
{"t":"Cash sweep program","a":["cash sweep","sweep account","bank deposit sweep"],"c":"Costs","l":1,"mod":"INV-104","d":"The arrangement that automatically moves uninvested cash in a brokerage or advisory account into a default vehicle, usually a deposit at one or more partner banks or a money market fund. The firm selects the options and often, for bank sweeps, the rate.","u":"Holding cash between trades and collecting dividends and interest.","m":"Look up your sweep rate. The SEC found in 2025 that at two large firms the gap between bank sweeps and other options at times reached almost 4 percentage points."},
{"t":"Cash-flow rebalancing","c":"Portfolio","l":1,"mod":"INV-056","d":"Rebalancing by directing money that is already moving (contributions, dividends, interest, withdrawals, required distributions) toward what is underweight or away from what is overweight.","u":"Keeping a portfolio on target without selling, and so without realizing gains.","m":"For savers the paycheck is the rebalancing tool; for retirees, the choice of which fund each withdrawal comes from.","a":[]},
{"t":"Cash-on-cash return","c":"Real estate","l":2,"d":"Annual pre-tax cash flow divided by the cash you invested (down payment and costs).","u":"Measuring leveraged rental returns.","m":"Ignores appreciation and principal paydown; check both."},
{"t":"Cash-out refinance","c":"Real estate","l":2,"mod":"INV-064","d":"A refinance for more than the current balance, paying the difference to the borrower in cash.","u":"Tapping home equity for renovations, debts or other investments.","m":"It turns equity back into debt secured by your home, usually at a higher rate than a no-cash-out refinance.","a":[]},
{"t":"Catch-up contribution","c":"Accounts","l":2,"mod":"INV-002","d":"Additional contributions allowed to workplace plans and IRAs for people aged 50 and older; SECURE 2.0 added a higher catch-up for ages 60–63 in workplace plans.","u":"Accelerating late-career saving.","m":"Limits are set by the IRS each year."},
{"t":"Certainty effect","c":"Behavior","l":3,"mod":"INV-060","d":"The tendency to overweight outcomes that are certain compared with outcomes that are merely probable (Kahneman and Tversky, 1979).","u":"Explaining why people take a sure gain over a larger expected gain.","m":"Helps explain the appeal of guaranteed products; check what the guarantee costs.","a":[]},
{"t":"Certainty equivalent","a":["certainty equivalent return"],"c":"Behavior","l":3,"mod":"INV-051","d":"The guaranteed return a person would accept in place of an uncertain one; the more someone dislikes risk and losses, the lower it is.","u":"Comparing strategies by how an investor values them, not just by their average outcome.","m":"A strategy whose worst case would make you abandon your plan is worth less to you than its average suggests."},
{"t":"Certificate of deposit","a":["CD"],"c":"Asset classes","l":1,"d":"A bank deposit that pays a fixed rate for a fixed term, with a penalty for early withdrawal.","u":"Locking in a rate for money with a known date.","m":"FDIC-insured within limits; watch early-withdrawal penalties."},
{"t":"Certified Financial Planner","a":["CFP"],"c":"Advice & regulation","l":2,"d":"A professional certification requiring education, an exam, experience and adherence to a fiduciary standard when giving financial advice.","u":"Identifying trained planners.","m":"Verify certification on the CFP Board's website."},
{"t":"Chained CPI","a":["C-CPI-U"],"c":"Foundations","l":3,"mod":"INV-001","d":"A version of the CPI that accounts for consumers switching to cheaper substitutes when prices rise, so it tends to rise slightly more slowly than CPI-U.","u":"Indexing federal income-tax brackets and many tax parameters since the 2017 tax law.","m":"Brackets that rise a little more slowly than prices can push slightly more income into higher brackets over time."},
{"t":"Charitable bequest","c":"Estate","l":1,"mod":"INV-093","d":"A gift to charity that takes effect at death, through a will, trust, beneficiary designation or transfer-on-death registration.","u":"Supporting causes without giving up money during life; deductible in full from a taxable estate (IRC 2055).","m":"Leave charity pre-tax retirement money and leave family assets that get a stepped-up basis.","a":[]},
{"t":"Charitable deduction floor","a":["0.5% floor"],"c":"Taxes","l":2,"mod":"INV-039","d":"From 2026, itemizers can deduct charitable gifts only to the extent they exceed 0.5% of their contribution base (roughly AGI) (P.L. 119-21).","u":"Knowing how much of your giving is deductible.","m":"On $200,000 of AGI, the first $1,000 of gifts is not deductible."},
{"t":"Charitable gift annuity","c":"Estate","l":3,"mod":"INV-039","d":"A contract with a single charity: you give assets and the charity pays you a fixed income for life, keeping what remains.","u":"A simpler alternative to a charitable remainder trust.","m":"A one-time QCD of up to $55,000 in 2026 can fund one.","a":[]},
{"t":"Charitable lead trust","a":["CLT","CLAT","CLUT"],"c":"Estate","l":3,"mod":"INV-093","d":"A trust that pays a charity a guaranteed annuity or a fixed percentage each year for a term, then passes the remainder to family. The taxable gift is the remainder's present value at the section 7520 rate.","u":"Passing growth to heirs with little or no gift or estate tax when investments beat the 7520 rate.","m":"A specialist tool for estates near or above the exemption; if investments underperform, heirs may get nothing."},
{"t":"Charitable remainder trust","a":["CRT","CRAT","CRUT","charitable remainder unitrust","charitable remainder annuity trust"],"c":"Estate","l":3,"mod":"INV-093","d":"An irrevocable trust that pays one or more people 5% to 50% a year, for life or up to 20 years, and then gives what remains to charity. The remainder must be worth at least 10% of the initial value (IRC 664). An annuity trust pays a fixed amount; a unitrust pays a fixed percentage of each year's value.","u":"Diversifying a low-basis asset without an immediate capital gains tax while providing income and a charitable gift.","m":"You get income and a partial deduction; the remainder goes to charity, not heirs, and payments carry out the deferred gain as taxable income over time."},
{"t":"Child and dependent care credit","c":"Taxes","l":2,"mod":"INV-096","d":"A nonrefundable credit for a percentage of up to $3,000 of work-related care costs for one qualifying person, or $6,000 for two or more. From 2026 the percentage runs from 50% at low incomes down to 35%, and to 20% at higher incomes.","u":"Offsetting care costs for families without a dependent care FSA or with costs above it.","m":"The dollar limit is reduced by any FSA money you exclude, so a full $7,500 FSA leaves nothing for the credit.","a":[]},
{"t":"Child support","c":"Taxes","l":1,"mod":"INV-095","d":"Payments from one parent to the other for a child's support under a divorce, separation or support order.","u":"Sharing the cost of raising children after parents separate.","m":"It is never deductible by the payer or taxable to the recipient. Partial payments count toward child support before alimony.","a":[]},
{"t":"Child tax credit","a":["CTC","additional child tax credit"],"c":"Taxes","l":1,"mod":"INV-096","d":"A federal credit for each qualifying child under 17 at the end of the year. For 2026 it is up to $2,200 per child, with up to $1,700 refundable, reduced by $50 per $1,000 of modified AGI above $200,000 ($400,000 joint).","u":"Lowering taxes for families with children.","m":"You and each child need a work-eligible Social Security number. The credit ends the year a child turns 17; a $500 credit for other dependents can take its place."},
{"t":"Churning","a":["excessive trading"],"c":"Advice & regulation","l":2,"mod":"INV-103","d":"Trading an account mainly to generate commissions rather than to benefit the customer. Regulation Best Interest's care obligation requires a reasonable basis to believe that a series of recommended transactions is not excessive for the customer.","u":"Identifying abusive broker behavior.","m":"Frequent trades you did not initiate, each with a commission, are a warning sign; review your confirmations."},
{"t":"Circuit breaker","a":["market-wide circuit breaker"],"c":"Markets","l":2,"mod":"INV-005","d":"An automatic, market-wide trading halt triggered by large S&P 500 declines: 7% and 13% (15-minute halts before 3:25 p.m.) and 20% (halt for the day).","u":"Pausing trading during panics.","m":"Four Level 1 halts occurred in March 2020; markets reopened each time."},
{"t":"Clawback","c":"Advice & regulation","l":3,"mod":"INV-062","d":"A legal action to recover money paid out of a failed fraud, including so-called profits paid to earlier investors, for redistribution to victims.","u":"How the Madoff bankruptcy trustee recovered billions for customers.","m":"Profits withdrawn from a Ponzi scheme may have to be returned.","a":[]},
{"t":"Clearinghouse","c":"Markets","l":3,"mod":"INV-005","d":"An entity that stands between buyers and sellers, guaranteeing trades and netting obligations; brokers post collateral with it.","u":"Reducing the risk that a trade fails.","m":"Collateral demands can force brokers to restrict trading in extreme conditions, as in January 2021."},
{"t":"Cliff vesting","a":["graded vesting"],"c":"Accounts","l":2,"mod":"INV-022","d":"Vesting schedules for employer contributions: cliff vesting makes them 100% yours all at once after a set period (such as three years); graded vesting phases them in (such as 20% a year from year two to year six).","u":"Deciding how long an employee must stay to keep the match.","m":"Check your next vesting date before changing jobs; a few months can be worth thousands."},
{"t":"Closed-end fund","c":"Vehicles","l":3,"d":"A fund with a fixed number of shares that trade on an exchange, often at a premium or discount to net asset value.","u":"Specialized strategies, sometimes with leverage.","m":"Discounts can widen in stress; check leverage and fees."},
{"t":"Closet indexing","a":["closet index fund","closet indexer"],"c":"Costs","l":2,"mod":"INV-045","d":"A fund marketed and priced as actively managed whose holdings are so close to its benchmark that it behaves much like an index fund.","u":"Describing active fees paid for index-like results.","m":"Compare a fund's top holdings with its index's; a near-copy at an active price will almost surely trail by its extra fee."},
{"t":"Closing costs","c":"Real estate","l":1,"mod":"INV-063","d":"Fees and charges paid to complete a real estate purchase or a loan: lender fees, appraisal, title insurance, recording fees, prepaid interest and escrow deposits.","u":"Budgeting the cash needed to buy or refinance, beyond the down payment.","m":"Buying and later selling can cost a meaningful share of the price, which is why short stays usually favor renting.","a":[]},
{"t":"Coast FI","c":"Independence","l":3,"d":"Having saved enough that, with no further contributions, growth alone should reach your FI number by traditional retirement age.","u":"Easing off saving earlier.","m":"Relies on assumed returns over many years."},
{"t":"Coast FI number","a":["coast number"],"c":"Independence","l":3,"mod":"INV-073","d":"The amount invested today that, with no further contributions, is expected to grow to your FI number by your chosen age: FI number ÷ (1 + r) raised to the years remaining.","u":"Checking whether you can stop saving for retirement and let growth finish the job.","m":"It is very sensitive to the assumed return: one point lower can raise it by a fifth or more over 20 years."},
{"t":"COBRA","a":["COBRA continuation coverage"],"c":"Insurance","l":1,"mod":"INV-074","d":"A federal law letting workers and families keep an employer's group health plan after leaving a job, usually for up to 18 months, at up to 102% of the plan's full cost.","u":"Bridging health coverage after a job ends.","m":"It keeps your doctors and deductible progress but is often expensive; compare it with marketplace coverage before choosing."},
{"t":"Coinsurance","a":["copay","copayment"],"c":"Insurance","l":1,"mod":"INV-023","d":"Your share of a covered cost after the deductible: a percentage (coinsurance) or a flat amount (copay).","u":"Splitting costs between you and the plan until the out-of-pocket maximum.","m":"20% coinsurance on a large bill can be thousands of dollars until the cap is reached."},
{"t":"Collectibles gain","a":["collectibles tax","28% rate gain"],"c":"Taxes","l":3,"mod":"INV-013","d":"Gain on selling a collectible held more than a year, including art, antiques, gems, coins and metals such as gold, silver and platinum bullion, and gain on an interest in a trust due to appreciation of collectibles (IRS Publication 550).","u":"Taxing gold and silver coins, bullion and shares of physically backed metal trusts.","m":"Net collectibles gains face a maximum 28% federal rate instead of the 0/15/20% rates on stocks; holding a gold fund inside an IRA or 401(k) avoids the issue while the money stays there."},
{"t":"Commodity","c":"Asset classes","l":2,"d":"A raw material such as oil, grain or metal, often traded through futures contracts.","u":"Diversification and inflation hedging.","m":"Commodities produce no income; returns come from price changes and futures mechanics."},
{"t":"Common stock","c":"Markets","l":1,"mod":"INV-011","d":"Ordinary shares of ownership in a corporation, which, as the SEC puts it, entitle owners 'to vote at shareholder meetings and receive dividends.'","u":"Nearly all stock investing, including index funds.","m":"You share in all the profits above what lenders are owed, and you are last in line if the company fails.","a":[]},
{"t":"Community property","c":"Estate","l":2,"mod":"INV-090","d":"A system of marital property law in which most property acquired during the marriage belongs equally to both spouses. The nine community-property states are Arizona, California, Idaho, Louisiana, Nevada, New Mexico, Texas, Washington and Wisconsin.","u":"Dividing property at divorce and death; for tax, giving both halves a new basis at the first spouse's death (IRC 1014(b)(6)).","m":"Couples in these states can often sell appreciated assets after the first death with no capital gains tax; elsewhere only the deceased spouse's half steps up.","a":[]},
{"t":"Compound interest","a":["compounding"],"c":"Foundations","l":1,"mod":"INV-002","d":"Earning returns on both the original amount and on returns already earned.","u":"Projecting savings and debt; explaining why time matters.","m":"Growth on growth is slow at first and powerful later; it works the same way on debt."},
{"t":"Concentration risk","c":"Foundations","l":1,"mod":"INV-004","d":"The risk of holding a large share of wealth in one company, sector, property or asset.","u":"Reviewing portfolios, especially employer stock.","m":"Enron employees held 63% of their 401(k) assets in company stock at the end of 2000."},
{"t":"Confirmation bias","c":"Behavior","l":2,"d":"Seeking out information that supports what you already believe.","u":"Explaining persistent bad bets.","m":"Deliberately read the strongest case against your idea."},
{"t":"Conflict of interest","c":"Advice & regulation","l":1,"mod":"INV-103","d":"For Regulation Best Interest, the SEC defines it as an interest that might incline a broker-dealer or its representative, consciously or unconsciously, to make a recommendation that is not disinterested. Examples include proprietary products, payments from third parties and compensation arrangements.","u":"Identifying incentives that could bias a recommendation.","m":"Every way of paying for advice creates some conflict. Ask: how might your conflicts affect me, and how will you address them?","a":[]},
{"t":"Constant-percentage withdrawal","c":"Retirement","l":2,"mod":"INV-076","d":"A spending rule that withdraws the same percentage of the current balance each year.","u":"A simple rule that can never fully deplete a portfolio.","m":"Your income moves with the market: a 30% fall means a 30% smaller withdrawal the next year.","a":[]},
{"t":"Consumer Expenditure Survey","a":["CE Survey","Consumer Expenditure Surveys"],"c":"Foundations","l":2,"mod":"INV-018","d":"A survey conducted for the Bureau of Labor Statistics that records the income and spending of US households ('consumer units') by category.","u":"Seeing how typical households spend on housing, transportation, food and more.","m":"A useful reality check on your own budget; an average is not a target."},
{"t":"Consumer Price Index","a":["CPI","CPI-U"],"c":"Foundations","l":1,"mod":"INV-001","d":"A monthly index published by the Bureau of Labor Statistics that tracks the prices urban consumers pay for a large basket of goods and services. CPI-U, for all urban consumers, is the headline measure.","u":"Measuring inflation; indexing Treasury Inflation-Protected Securities, I bonds and many contracts.","m":"Your personal inflation rate can differ from the CPI depending on where you live and what you buy."},
{"t":"Contango","c":"Asset classes","l":2,"mod":"INV-013","d":"A futures market in which contracts for later delivery cost progressively more than the nearest contract (CFTC definition). The opposite of backwardation.","u":"Reading the shape of the futures curve; estimating what it costs a fund to roll its contracts forward.","m":"A commodity fund that keeps rolling into dearer contracts loses value even if the commodity's spot price never moves.","a":[]},
{"t":"Contingent beneficiary","a":["secondary beneficiary"],"c":"Estate","l":1,"mod":"INV-027","d":"The person or entity who receives an account or policy if the primary beneficiary has died or declines it.","u":"Keeping an asset out of a default process if the first-named beneficiary is gone.","m":"Name one on every retirement account and policy; in Kennedy v. DuPont (2009) no contingent beneficiary had been named."},
{"t":"Continuous compounding","c":"Foundations","l":3,"mod":"INV-002","d":"The limit of ever-more-frequent compounding: FV = PV × e^(rt).","u":"Financial mathematics and log returns.","m":"Practically, daily compounding is almost identical."},
{"t":"Conversion window","a":["tax planning window"],"c":"Retirement","l":2,"mod":"INV-038","d":"The low-income years after work stops and before Social Security and required minimum distributions begin.","u":"Timing Roth conversions and gain harvesting when brackets are emptiest.","m":"For someone retiring at 62 with RMDs at 75, it can last more than a decade."},
{"t":"Convexity","c":"Asset classes","l":3,"mod":"INV-009","d":"The curvature of the relationship between a bond's price and its yield; a second-order correction to the duration estimate.","u":"Refining price-change estimates for large rate moves.","m":"Ordinary bonds gain more when yields fall than they lose when yields rise by the same amount. Callable bonds and mortgage-backed securities can have negative convexity.","a":[]},
{"t":"Core and satellite","a":["core-and-satellite portfolio"],"c":"Portfolio","l":2,"mod":"INV-055","d":"A portfolio design in which a large core of broad, low-cost index funds is surrounded by a small, capped share of individual stocks, sector funds or other bets.","u":"Allowing personal choices without letting them take over the portfolio.","m":"Keep satellites small enough, often 10% or less, that losing them entirely would not derail your plan."},
{"t":"Corporate bond","c":"Asset classes","l":2,"d":"A bond issued by a company.","u":"Income above Treasury yields.","m":"Carries credit risk as well as interest-rate risk."},
{"t":"Correction","c":"Markets","l":1,"d":"A decline of about 10% to 20% from a recent peak.","u":"Describing market moves.","m":"Common and usually temporary for diversified portfolios."},
{"t":"Correlation","c":"Foundations","l":2,"mod":"INV-004","d":"A measure from −1 to +1 of how consistently two investments move together.","u":"Deciding which combinations reduce risk.","m":"Anything below +1 diversifies; the stock–bond correlation itself changes over time."},
{"t":"Cost basis","a":["basis"],"c":"Taxes","l":1,"d":"The original cost of an investment, adjusted for items such as reinvested dividends, used to compute gain or loss.","u":"Calculating taxable gains.","m":"Brokers report basis; keep records for older or transferred holdings."},
{"t":"Cost of attendance","a":["COA","student budget"],"c":"Planning","l":2,"mod":"INV-096","d":"A college's estimate of the full yearly cost for a student: tuition and fees, housing and food, books and supplies, transportation and personal expenses.","u":"Setting the ceiling on financial aid and comparing colleges.","m":"In 2025-26 the College Board's average budget was $30,990 for in-state students at public four-year colleges and $65,470 at private nonprofit four-year colleges."},
{"t":"Cost segregation","c":"Real estate","l":3,"d":"An engineering study that reclassifies parts of a building into shorter depreciation lives to accelerate deductions.","u":"Front-loading depreciation on rentals.","m":"Accelerated deductions increase recapture later."},
{"t":"Cost-of-living adjustment","a":["COLA"],"c":"Retirement","l":1,"mod":"INV-080","d":"A yearly increase in a benefit to keep up with inflation. Social Security benefits rose 2.8% for 2026 (SSA).","u":"Protecting the buying power of retirement income over decades.","m":"Most private pensions and most income annuities have no COLA, so their value shrinks with inflation. At 3% inflation, a fixed payment loses about 45% of its buying power in 20 years."},
{"t":"Countable resources","c":"Planning","l":2,"mod":"INV-102","d":"The assets SSA counts toward the SSI resource limit: cash, bank accounts, investments and other property that could be turned into cash, excluding items such as the home, one vehicle, household goods and the first $100,000 in an ABLE account.","u":"Determining SSI eligibility month by month.","m":"If countable resources exceed the limit at the start of a month, no SSI is paid for that month.","a":[]},
{"t":"Coupon","c":"Asset classes","l":2,"d":"A bond's stated annual interest rate on its face value.","u":"Determining the bond's cash payments.","m":"Differs from yield when the bond trades above or below face value."},
{"t":"Coverdell ESA","c":"Accounts","l":3,"d":"A tax-advantaged education savings account with a low annual contribution limit and income limits.","u":"Education saving, including K–12 expenses.","m":"Largely superseded by 529 plans for most families."},
{"t":"Covered call","c":"Asset classes","l":3,"d":"Selling call options on shares you own, collecting a premium in exchange for giving up gains above the strike price.","u":"Generating income from stock holdings.","m":"Caps upside while leaving most downside."},
{"t":"Covered interest parity","a":["interest rate parity"],"c":"Markets","l":3,"mod":"INV-054","d":"The principle that forward exchange rates adjust so that borrowing in one currency and lending in another with the rate locked in earns no riskless profit.","u":"Explaining what currency hedging costs or earns.","m":"If US short-term rates exceed foreign rates, a US investor hedging foreign assets earns roughly the difference; if lower, pays it."},
{"t":"Covered security","c":"Taxes","l":2,"mod":"INV-035","d":"A security for which the broker must report cost basis to the IRS on Form 1099-B. Generally, stock acquired after 2010; other securities were phased in later.","u":"Pre-filling basis on Form 8949.","m":"For noncovered or transferred shares, supplying basis is your job.","a":[]},
{"t":"CPI-W","c":"Foundations","l":3,"mod":"INV-001","d":"A version of the Consumer Price Index for urban wage earners and clerical workers.","u":"Setting the annual cost-of-living adjustment for Social Security benefits.","m":"Your Social Security raise each year follows this index, not the headline CPI-U."},
{"t":"Credit for other dependents","c":"Taxes","l":2,"mod":"INV-096","d":"A $500 federal credit for each dependent who does not qualify for the child tax credit, such as a 17- or 18-year-old, a full-time student under 24, or a parent you support.","u":"Recognizing the cost of supporting older children and adult relatives.","m":"It phases out at the same income levels as the child tax credit.","a":[]},
{"t":"Credit freeze","a":["security freeze","credit report freeze"],"c":"Planning","l":1,"mod":"INV-021","d":"A block, placed separately at each nationwide credit bureau, on access to your credit report for new credit. Free by federal law since September 21, 2018.","u":"Stopping identity thieves from opening new accounts in your name.","m":"It does not affect your score and lasts until you lift it; an online or phone request must be lifted within one hour."},
{"t":"Credit rating","c":"Asset classes","l":2,"d":"An agency's assessment of a borrower's likelihood of default, such as AAA through D.","u":"Comparing bond quality.","m":"Ratings can lag; they are an opinion, not a guarantee."},
{"t":"Credit report","c":"Planning","l":1,"mod":"INV-021","d":"A record kept by each nationwide credit bureau (Equifax, Experian, TransUnion) of your credit accounts, balances, payment history, certain public records and inquiries.","u":"The raw material for credit scores, and a document lenders, landlords and insurers review.","m":"You can check each report free every week at AnnualCreditReport.com. The three reports can differ; dispute errors with the bureau and the business that reported them.","a":[]},
{"t":"Credit risk","a":["default risk"],"c":"Asset classes","l":2,"mod":"INV-003","d":"The risk that a borrower fails to make promised payments.","u":"Pricing corporate and municipal bonds.","m":"Higher-yield bonds pay more because more of them default."},
{"t":"Credit score","a":["FICO score"],"c":"Planning","l":1,"d":"A number, commonly 300 to 850, summarizing credit history to predict the likelihood of repayment.","u":"Lenders, landlords and insurers use it to set terms.","m":"Paying on time and keeping balances low relative to limits matter most."},
{"t":"Credit shelter trust","a":["bypass trust","B trust","family trust"],"c":"Estate","l":3,"mod":"INV-087","d":"A trust funded at the first spouse's death with up to that spouse's exclusion amount, for the survivor and often the children, designed so its assets are not taxed again at the survivor's death.","u":"Sheltering the first spouse's exclusion and all later growth; protecting assets for children of a first marriage; using state estate-tax exemptions that are not portable.","m":"Its assets get no new cost basis at the second death. Portability is simpler for most couples; the trust wins mainly for large or fast-growing estates and in estate-tax states."},
{"t":"Credit spread","c":"Asset classes","l":2,"mod":"INV-009","d":"The extra yield a bond pays over a Treasury of similar maturity, as compensation for the risk that the issuer will not pay.","u":"Pricing corporate, municipal and other bonds relative to Treasuries.","m":"Spreads widen in recessions, which is when lower-quality bonds tend to fall along with stocks.","a":[]},
{"t":"Credit utilization","c":"Planning","l":2,"d":"Credit card balances as a percentage of total credit limits.","u":"A major factor in credit scores.","m":"Lower is better; paying cards in full keeps it low."},
{"t":"Credit-based insurance score","a":["insurance score"],"c":"Insurance","l":2,"mod":"INV-021","d":"A score built partly or entirely from credit history that estimates how likely a person is to file an insurance claim.","u":"Pricing auto and home insurance in states that allow it.","m":"Good credit can lower insurance premiums as well as loan rates; state laws limit how these scores are used."},
{"t":"Creditable coverage","a":["creditable drug coverage"],"c":"Retirement","l":3,"mod":"INV-079","d":"Prescription drug coverage, usually from an employer or union, expected to pay at least as much as standard Medicare Part D.","u":"Delaying Part D without a penalty.","m":"Keep the yearly notice your plan sends; a gap of 63 days or more without creditable coverage starts the penalty."},
{"t":"Cross-purchase agreement","c":"Estate","l":3,"mod":"INV-094","d":"A buy-sell agreement in which the other owners, rather than the company, buy a departing owner's shares, usually funded by life insurance each owner holds on the others.","u":"Keeping insurance proceeds out of the company's value for estate tax.","m":"After Connelly (2024), often preferable with few owners; the cost is each owner paying premiums on the others.","a":[]},
{"t":"Crossover point","c":"Independence","l":2,"mod":"INV-072","d":"The moment when a sustainable withdrawal from your portfolio first equals your annual spending.","u":"Tracking progress toward financial independence year by year.","m":"Reaching it makes work optional rather than necessary; it does not oblige you to stop.","a":[]},
{"t":"Crummey power","c":"Estate","l":3,"mod":"INV-092","d":"A trust clause giving beneficiaries a temporary right to withdraw each new gift, usually up to the annual exclusion, after being notified. Named for Crummey v. Commissioner (9th Cir. 1968).","u":"Making gifts to a trust present interests so they qualify for the annual exclusion, as in life-insurance trusts.","m":"The right must be real: send notices, allow a window, and be ready to honor a withdrawal.","a":[]},
{"t":"Cryptocurrency","a":["crypto","crypto asset"],"c":"Asset classes","l":2,"d":"A digital asset recorded on a blockchain, such as bitcoin.","u":"Speculation, payments, and some diversification strategies.","m":"Extremely volatile; many crypto assets are not protected by SIPC; losses can be total."},
{"t":"Currency hedging","a":["hedged share class","hedge ratio"],"c":"Portfolio","l":3,"mod":"INV-054","d":"Using forward contracts to lock in an exchange rate so a foreign investment's dollar value depends on its local-currency return rather than on currency moves.","u":"Removing currency swings, most commonly from foreign bonds.","m":"A hedge swaps the currency's unpredictable move for a known carry of roughly the difference in short-term interest rates."},
{"t":"Currency risk","c":"Portfolio","l":2,"d":"The risk that changes in exchange rates alter the value of foreign investments in your home currency.","u":"International investing.","m":"Adds both risk and diversification to foreign holdings."},
{"t":"Current yield","c":"Asset classes","l":2,"mod":"INV-009","d":"A bond's annual coupon divided by its current price.","u":"A quick measure of the income a bond pays relative to its price.","m":"It ignores the gain or loss as the price moves to par, so it misstates the return for bonds far from par. Use yield to maturity to compare bonds.","a":[]},
{"t":"Custodial care","c":"Insurance","l":1,"mod":"INV-083","d":"Non-medical help with daily living, such as bathing, dressing and eating, that does not require skilled professionals.","u":"Distinguishing care Medicare does not pay for from skilled nursing or therapy that it may cover for a short time.","m":"Most long nursing-home stays are mainly custodial care, which Medicare does not pay for.","a":[]},
{"t":"Custodial Roth IRA","c":"Accounts","l":2,"mod":"INV-027","d":"A Roth IRA held for a minor by an adult custodian. There is no minimum age, but contributions cannot exceed the child's taxable compensation for the year or the annual limit.","u":"Turning a teenager's earnings into decades of tax-free growth, and teaching ownership of a real account.","m":"$1,000 a year from 15 to 18 can grow to tens of thousands of dollars in today's money by retirement.","a":[]},
{"t":"Custodian","c":"Markets","l":3,"mod":"INV-005","d":"A financial institution that holds securities on behalf of customers.","u":"Safekeeping of assets.","m":"Customer securities at a US broker-dealer are kept separate from the firm's own assets."},
{"t":"Debt avalanche","c":"Planning","l":2,"d":"Paying off debts in order of highest interest rate first while making minimum payments on the rest.","u":"Minimizing total interest.","m":"Mathematically cheapest; works best if you stay motivated."},
{"t":"Debt service coverage ratio","a":["DSCR"],"c":"Real estate","l":3,"d":"Net operating income divided by annual loan payments.","u":"Lender underwriting for investment properties.","m":"Below 1.0 means rents do not cover the mortgage."},
{"t":"Debt snowball","c":"Planning","l":2,"d":"Paying off debts from the smallest balance first, for quick wins.","u":"Building momentum and motivation.","m":"Costs more interest than the avalanche but may help some people finish."},
{"t":"Debt-to-equity ratio","c":"Companies","l":2,"mod":"INV-006","d":"Total debt divided by shareholders' equity.","u":"Measuring financial leverage.","m":"More debt magnifies results and increases the risk of distress."},
{"t":"Deductible (insurance)","a":["insurance deductible"],"c":"Insurance","l":1,"mod":"INV-023","d":"The amount you pay for a covered loss or covered care before the insurer starts to pay.","u":"Sharing small losses with the policyholder, which lowers premiums.","m":"With an emergency fund, a higher deductible usually costs less over time."},
{"t":"Deemed filing","c":"Retirement","l":3,"mod":"INV-078","d":"The rule that, for people born on or after January 2, 1954, applying for either a retirement or a spouse's benefit counts as applying for both.","u":"It ended strategies of taking a spousal benefit first while letting your own benefit grow.","m":"It does not apply to survivor benefits, which you can still take separately from your own and switch later.","a":[]},
{"t":"Deferred income annuity","a":["DIA","longevity annuity"],"c":"Insurance","l":2,"mod":"INV-017","d":"An income annuity bought now whose lifetime payments start years later, for example buying at 65 for income starting at 80.","u":"Insuring against outliving your money at a lower cost than an immediate annuity, because payments start later and fewer buyers survive to collect.","m":"Unless the contract includes a death benefit or refund feature, nothing may be paid if you die before income starts; those features lower the income."},
{"t":"Defined contribution plan","c":"Retirement","l":2,"d":"A retirement plan, such as a 401(k), where the benefit depends on contributions and investment returns.","u":"Most private-sector retirement saving.","m":"You bear the investment and longevity risk."},
{"t":"Deflation","c":"Foundations","l":2,"mod":"INV-001","d":"A general fall in prices over time: negative inflation.","u":"Describing periods such as 1930–1932 in the United States, when prices fell 6–10% a year.","m":"Falling prices raise the real burden of debt and often accompany severe recessions; cash gains buying power, but jobs and businesses suffer."},
{"t":"Delayed retirement credits","c":"Retirement","l":2,"d":"Increases of 8% a year to your own Social Security benefit for each year you delay claiming past full retirement age, up to 70.","u":"Raising lifetime and survivor income.","m":"For many married higher earners, delaying protects the surviving spouse."},
{"t":"Dependent care FSA","a":["dependent care flexible spending account","DCAP","dependent care assistance program"],"c":"Accounts","l":1,"mod":"INV-096","d":"An employer benefit that lets you pay work-related care costs for a child under 13, or for a spouse or dependent who cannot care for themselves, with pre-tax pay. The 2026 limit is $7,500 per household ($3,750 if married filing separately).","u":"Paying for day care, preschool, after-school care, day camps and adult day care.","m":"The money avoids income tax and the 7.65% payroll tax, but reduces the costs you can count for the child and dependent care credit."},
{"t":"Depreciation","c":"Companies","l":2,"mod":"INV-006","d":"Spreading the cost of a long-lived asset over its useful life as an expense; a non-cash charge in each year.","u":"Accounting profit; for real estate, a valuable tax deduction.","m":"Explains why cash flow can exceed net income."},
{"t":"Depreciation recapture","c":"Real estate","l":3,"d":"Tax on the portion of a gain on rental property attributable to depreciation previously deducted; for real property this unrecaptured gain is taxed at up to 25%.","u":"Calculating tax when selling rentals.","m":"Depreciation lowers taxes now but increases tax on sale."},
{"t":"Derivative","c":"Asset classes","l":3,"d":"A contract whose value depends on another asset, rate or index.","u":"Hedging and speculation.","m":"Can create leverage and losses larger than expected."},
{"t":"Designated beneficiary","c":"Retirement","l":2,"mod":"INV-091","d":"An individual named as beneficiary of a retirement account, or the individual beneficiaries of a trust that meets IRS requirements. Estates and charities are not designated beneficiaries. Determined as of September 30 of the year after the owner's death.","u":"Deciding which post-death distribution rule applies.","m":"Name people (or a qualifying trust), not your estate, on retirement accounts.","a":[]},
{"t":"Designated Roth account","a":["Roth 401(k)","Roth 403(b)"],"c":"Accounts","l":2,"mod":"INV-081","d":"A Roth contribution account inside a 401(k), 403(b) or governmental 457(b) plan: after-tax contributions, tax-free qualified withdrawals.","u":"Saving Roth money through payroll, often with higher limits than a Roth IRA.","m":"Since 2024, designated Roth accounts no longer require RMDs while the owner is alive (26 U.S.C. §402A(d)(5))."},
{"t":"Developed markets","a":["developed countries"],"c":"Markets","l":1,"mod":"INV-054","d":"Countries classified by index providers as economically developed with open, accessible stock markets, such as the US, Japan, the UK, Canada, much of Western Europe and Australia.","u":"Grouping countries with similar market risks; building developed ex-US funds.","m":"Most of the non-US part of a global portfolio sits here."},
{"t":"Digital assets (estate planning)","a":["digital assets"],"c":"Estate","l":2,"mod":"INV-059","d":"Electronic records a person owns or controls, such as email, photos, online accounts and virtual currency, held by 'custodians' (the companies that store them). The Revised Uniform Fiduciary Access to Digital Assets Act, adopted state by state, sets who may access them.","u":"Planning who can reach, manage or close your online life.","m":"Under the Act an online tool's instructions rank first, then your will or other documents, then the terms of service."},
{"t":"Direct indexing","c":"Strategies","l":3,"mod":"INV-037","d":"Owning the individual stocks of an index in a separately managed account instead of a fund, so that individual losing stocks can be sold for tax losses.","u":"Harvesting more losses than a single index fund allows.","m":"Benefits shrink as the cost basis falls over time; fees and tracking differences matter.","a":[]},
{"t":"Direct primary care arrangement","a":["direct primary care","DPC"],"c":"Accounts","l":3,"mod":"INV-033","d":"A flat periodic fee paid to a primary care practice for its services. From 2026, under Public Law 119-21, such arrangements costing no more than $150 a month ($300 for more than one person) do not disqualify you from an HSA, and the fees can be paid from the HSA tax-free.","u":"Combining concierge-style primary care with an HSA.","m":"Check the monthly fee against the limit before assuming HSA eligibility."},
{"t":"Direct rollover","a":["trustee-to-trustee transfer"],"c":"Accounts","l":2,"mod":"INV-100","d":"Moving a retirement plan distribution straight to an IRA or another plan, or by a check payable to the new account, so no tax is withheld.","u":"Keeping retirement money tax-deferred when leaving a job.","m":"A check made out to you has 20% withheld, and you must replace that 20% from other money within 60 days to roll over the full amount."},
{"t":"Disability insurance","c":"Insurance","l":1,"d":"Insurance that replaces part of your income if illness or injury prevents you from working.","u":"Protecting your largest asset, your earning power.","m":"Often more important for young workers than life insurance."},
{"t":"Disabled adult child benefit","a":["DAC benefit","childhood disability benefit"],"c":"Retirement","l":3,"mod":"INV-102","d":"A Social Security benefit paid on a parent's earnings record to an unmarried adult whose disability began before age 22, once the parent receives retirement or disability benefits or dies (SSA).","u":"Income for adults disabled since childhood, in addition to or instead of SSI.","m":"Contact SSA when a parent of an adult with a disability files for benefits."},
{"t":"Discount for lack of marketability","a":["DLOM","minority discount","discount for lack of control"],"c":"Valuation","l":3,"mod":"INV-094","d":"Reductions an appraiser applies to the value of a private-company interest because it cannot easily be sold (marketability) or does not control the company (control).","u":"Valuing gifts and bequests of minority business interests for gift and estate tax.","m":"Discounts lower transfer tax but must be supported by a qualified appraisal that is adequately disclosed on the gift tax return."},
{"t":"Discount rate","c":"Foundations","l":2,"mod":"INV-002","d":"The rate used to convert future money into present value, reflecting what the money could earn elsewhere at similar risk.","u":"Pension and settlement decisions, valuation.","m":"A higher discount rate makes future payments worth less today; the choice can flip a decision."},
{"t":"Disposition effect","c":"Behavior","l":3,"d":"The tendency to sell winners too early and hold losers too long.","u":"Explaining poor timing of sales.","m":"Also usually the opposite of what is tax-efficient."},
{"t":"Disqualifying disposition","a":["qualifying disposition"],"c":"Taxes","l":3,"mod":"INV-022","d":"Selling stock from an ESPP or incentive stock option before meeting the holding period (for ESPPs, two years from grant and one year from purchase). A sale after meeting it is a qualifying disposition.","u":"Determining how much of the gain is taxed as wages.","m":"Selling ESPP shares promptly is a disqualifying disposition but removes concentration risk; the tax difference is often smaller than the risk."},
{"t":"Distributable net income","a":["DNI"],"c":"Estate","l":3,"mod":"INV-087","d":"A tax measure that determines how much of a trust's or estate's income is taxed to beneficiaries who receive distributions rather than to the trust.","u":"Allocating income tax between a trust and its beneficiaries on Form 1041 and Schedule K-1.","m":"Because trusts reach the 37% bracket above $16,000 of taxable income in 2026, distributing income to beneficiaries in lower brackets can reduce total tax."},
{"t":"Diversification","c":"Foundations","l":1,"mod":"INV-004","d":"Spreading money across investments that do not all move together, to reduce risk without necessarily reducing expected return.","u":"Portfolio construction.","m":"Removes company-specific risk nearly for free; cannot remove market-wide risk."},
{"t":"Dividend","c":"Asset classes","l":1,"mod":"INV-006","d":"A cash payment a company makes to shareholders out of profits.","u":"Income; part of total return.","m":"Dividends are not guaranteed and can be cut; an unusually high yield is a warning sign."},
{"t":"Dividend growth investing","a":["dividend growth"],"c":"Strategies","l":1,"mod":"INV-047","d":"Focusing on companies with a record of raising dividends year after year, rather than on the highest current yield.","u":"Seeking rising income from profitable companies; it tends to tilt toward quality.","m":"A reasonable core holding, but a subset of the market with a style tilt, not a safer version of it."},
{"t":"Dividend investing","c":"Strategies","l":2,"d":"Emphasizing stocks that pay steady or growing dividends.","u":"Income-focused portfolios.","m":"Total return matters more than yield; concentrated high-yield portfolios can be undiversified."},
{"t":"Dividend irrelevance theorem","a":["Miller–Modigliani","dividend irrelevance","MM theorem"],"c":"Valuation","l":3,"mod":"INV-047","d":"Miller and Modigliani's 1961 result that, without taxes and trading costs, a company's dividend policy does not change its value; only its investment decisions do.","u":"Separating the question of a good business from whether it pays a dividend.","m":"A higher yield is not a higher return. Choose on total return, diversification and cost."},
{"t":"Dividend yield","c":"Valuation","l":1,"mod":"INV-006","d":"Annual dividends per share divided by price.","u":"Measuring cash income per dollar invested.","m":"An unusually high yield often signals that a cut is expected."},
{"t":"Divorced spouse benefit","a":["Divorced-spouse benefit","ex-spouse benefit"],"c":"Retirement","l":2,"mod":"INV-095","d":"A Social Security benefit based on a former spouse's record, worth up to half of the former spouse's full-retirement-age benefit. The marriage must have lasted at least 10 years, and the claimant must be at least 62 and unmarried.","u":"Providing income to a lower-earning former spouse after a long marriage.","m":"It does not reduce the former spouse's benefit. If the ex is 62 or older but has not claimed, you must have been divorced at least two years."},
{"t":"Dollar-cost averaging","a":["DCA"],"c":"Strategies","l":1,"d":"Investing a fixed amount at regular intervals regardless of price.","u":"Regular investing from paychecks; easing into markets.","m":"With a lump sum already in hand, investing it at once has historically won more often, but DCA can reduce regret."},
{"t":"Domicile","c":"Taxes","l":2,"mod":"INV-041","d":"Your true, fixed and permanent home, the place you intend to return to whenever absent. You can have many residences but only one domicile.","u":"Deciding which state may tax all of your income.","m":"Changing it takes intent plus facts: where you live, vote, register vehicles and spend your time.","a":[]},
{"t":"Donor-advised fund","a":["DAF"],"c":"Taxes","l":2,"d":"A charitable account at a sponsoring organization: you take a deduction when you contribute and recommend grants to charities over time.","u":"Bunching deductions; giving appreciated stock.","m":"Contributions are irrevocable."},
{"t":"Downside deviation","c":"Portfolio","l":3,"mod":"INV-057","d":"A measure of risk that counts only returns below a chosen minimum: the square root of the average squared shortfall.","u":"The denominator of the Sortino ratio.","m":"It ignores pleasant surprises, which is closer to how most investors experience risk.","a":[]},
{"t":"Drawdown","a":["maximum drawdown"],"c":"Foundations","l":1,"mod":"INV-003","d":"The percentage fall from a previous peak to a subsequent low. The maximum drawdown is the worst such fall in a period.","u":"Describing the worst experience an investor would have had.","m":"Drawdowns test whether you can stay invested; plan for them before they happen."},
{"t":"DSCR loan","a":["debt service coverage ratio loan"],"c":"Real estate","l":3,"mod":"INV-066","d":"A business-purpose loan on a rental property that is underwritten mainly on whether the property's income covers the loan payments, rather than on the borrower's personal income.","u":"Financing rentals for investors with complex or self-employed income, or many properties.","m":"Expect higher rates, larger down payments and prepayment penalties than conventional loans. It is not covered by the consumer mortgage rules that protect homeowners."},
{"t":"Dual registrant","a":["dually registered"],"c":"Advice & regulation","l":2,"mod":"INV-103","d":"A firm, or a financial professional, registered both as an investment adviser and as a broker-dealer. Which legal standard applies depends on the capacity in which the firm or person acts for a given account or recommendation.","u":"Offering fee-based advisory accounts and commission brokerage accounts under one roof.","m":"Ask of each account: are you acting as my investment adviser or as my broker here? The duties differ."},
{"t":"Duration","c":"Asset classes","l":3,"d":"A measure of a bond's price sensitivity to interest rates: roughly the percentage price change for a 1-point change in rates.","u":"Managing interest-rate risk.","m":"A duration of 8 means about an 8% price fall if rates rise 1 percentage point."},
{"t":"Duty of care","c":"Advice & regulation","l":2,"mod":"INV-103","d":"Half of an investment adviser's fiduciary duty as described by the SEC: advice in the client's best interest based on the client's objectives, seeking best execution of trades the adviser places, and advice and monitoring over the course of the relationship.","u":"Judging whether an adviser's recommendations and ongoing attention meet the legal standard.","m":"If you pay for ongoing management, the adviser is expected to keep monitoring, not just to advise once.","a":[]},
{"t":"Duty of loyalty","c":"Advice & regulation","l":2,"mod":"INV-103","d":"Half of an investment adviser's fiduciary duty: the adviser may not put its own interests ahead of the client's, and must eliminate each conflict of interest or disclose it fully and fairly so the client can give informed consent.","u":"Policing conflicts such as higher-cost share classes, affiliated products and referral payments.","m":"A disclosure buried in fine print is not informed consent; ask for conflicts to be explained in plain words.","a":[]},
{"t":"Earnings per share","a":["EPS"],"c":"Companies","l":1,"mod":"INV-006","d":"Net income divided by shares outstanding.","u":"Comparing profitability over time; computing P/E.","m":"Buybacks raise EPS by shrinking the share count even when profit is flat."},
{"t":"Earnings test","a":["retirement earnings test"],"c":"Retirement","l":3,"d":"A rule that temporarily withholds Social Security benefits if you claim before full retirement age and earn above an annual limit.","u":"Working while collecting early.","m":"Withheld benefits are credited back through a higher benefit after FRA."},
{"t":"Earnings yield","c":"Valuation","l":2,"mod":"INV-006","d":"Earnings per share divided by price: the inverse of P/E.","u":"Comparing stocks with bond yields.","m":"A P/E of 25 is a 4% earnings yield."},
{"t":"Educational assistance program","a":["Section 127 plan","Section 127"],"c":"Taxes","l":2,"mod":"INV-020","d":"An employer program under Internal Revenue Code Section 127 that can provide up to $5,250 a year of tax-free education benefits, including payments toward an employee's student loans.","u":"Helping employees pay tuition or student debt without adding taxable wages.","m":"The student-loan use was made permanent by the 2025 law. Ask your employer whether it offers one."},
{"t":"EE bond","a":["Series EE savings bond","EE savings bond"],"c":"Asset classes","l":2,"mod":"INV-008","d":"A US savings bond with a fixed interest rate that the Treasury guarantees will at least double in value after 20 years. Sold electronically through TreasuryDirect, up to $10,000 per Social Security number per calendar year.","u":"Very long-term safe saving; possible tax-free use for higher education.","m":"Doubling in 20 years equals about 3.53% a year, but only if you hold the full 20 years; cash in earlier and you get the bond's stated fixed rate (2.40% for May–October 2026 issues)."},
{"t":"Effective gross income","a":["EGI"],"c":"Real estate","l":2,"mod":"INV-065","d":"Gross potential rent minus vacancy and credit loss, plus other income such as fees or laundry.","u":"The income line from which operating expenses are subtracted to get NOI.","m":"Base every ratio on effective income, not the advertised rent."},
{"t":"Effective marginal tax rate","c":"Taxes","l":3,"mod":"INV-081","d":"The extra tax owed on one more dollar of income once every knock-on effect is included, such as more Social Security becoming taxable or a deduction phasing out.","u":"Deciding how much to convert, withdraw or realize in a year.","m":"It can be much higher than your bracket rate. Test decisions with a calculator that models your whole return.","a":[]},
{"t":"Effective tax rate","c":"Taxes","l":1,"d":"Total tax divided by total income: your average rate.","u":"Understanding your overall tax burden.","m":"Always lower than your top marginal rate under a progressive system."},
{"t":"Efficient frontier","c":"Portfolio","l":3,"mod":"INV-004","d":"The set of portfolios offering the highest expected return for each level of risk.","u":"Comparing allocations.","m":"Real-world frontiers are estimates based on uncertain inputs."},
{"t":"Efficient market hypothesis","a":["EMH"],"c":"Strategies","l":2,"d":"The theory, associated with Eugene Fama, that prices reflect available information, making it hard to beat the market consistently after costs.","u":"Framing the active-versus-passive debate.","m":"Markets need not be perfectly efficient for most investors to be better off indexing."},
{"t":"Elder financial exploitation","a":["elder fraud","elder financial abuse"],"c":"Behavior","l":1,"mod":"INV-097","d":"The illegal or improper use of an older person's money or property by a stranger, caregiver, friend or relative.","u":"Recognizing and reporting abuse.","m":"People 60 and older reported $7.748 billion in losses to the FBI in 2025, most from investment scams. Warning signs include sudden withdrawals, new names on accounts and a new person controlling decisions."},
{"t":"Elective deferral","c":"Accounts","l":1,"mod":"INV-031","d":"The part of your pay you choose to have put into a 401(k), 403(b), 457(b), SIMPLE or TSP account, traditional or Roth. Limited to $24,500 for 2026 (SIMPLE $17,000), per person across plans except a governmental 457(b).","u":"Measuring contributions against the annual limit.","m":"Employer matches are not elective deferrals and do not use up your limit.","a":[]},
{"t":"Eligible designated beneficiary","a":["EDB"],"c":"Retirement","l":2,"mod":"INV-091","d":"A designated beneficiary who, at the owner's death, is the surviving spouse, the owner's child under 21, disabled, chronically ill, or not more than 10 years younger than the owner (IRC 401(a)(9)(E)(ii)).","u":"These beneficiaries may still take distributions over their own life expectancy instead of the 10-year rule.","m":"Most adult children are not eligible and must empty an inherited IRA within ten years."},
{"t":"Eligible rollover distribution","c":"Accounts","l":2,"mod":"INV-059","d":"A distribution from a plan or IRA that may be rolled over tax-free. Exclusions include required minimum distributions, hardship distributions, loans treated as distributions and substantially equal periodic payments.","u":"Deciding which payouts can keep their tax-deferred status.","m":"An old 401(k) balance paid at a job change normally qualifies; an RMD never does.","a":[]},
{"t":"Elimination period","a":["waiting period"],"c":"Insurance","l":1,"mod":"INV-083","d":"The number of days you must need care, and usually pay for it yourself, before a long-term care or disability policy starts paying, commonly 30, 90 or 180 days.","u":"Lowering premiums by self-insuring the first weeks or months of care.","m":"A longer elimination period means lower premiums but a larger bill at the start of care; make sure you have cash to cover it."},
{"t":"Emergency fund","c":"Planning","l":1,"mod":"INV-001","d":"Cash set aside for unexpected expenses or loss of income, commonly three to six months of essential spending.","u":"Absorbing shocks without debt or forced selling of investments.","m":"It is what lets your long-term investments stay invested through a crisis."},
{"t":"Emerging markets","a":["EM","emerging economies"],"c":"Markets","l":1,"mod":"INV-054","d":"Countries with developing economies and markets, such as China, India, Taiwan, Korea and Brazil, classified separately by index providers.","u":"Adding exposure to faster-growing economies and companies absent from developed indexes.","m":"Among the most volatile stock markets: the MSCI Emerging Markets Index fell about 65% in 2007-2008."},
{"t":"Employee stock ownership plan","a":["ESOP"],"c":"Retirement","l":2,"mod":"INV-094","d":"A qualified defined contribution retirement plan designed to invest primarily in the employer's own stock, overseen by the IRS and the Department of Labor.","u":"Letting an owner sell to employees as a group, with the company funding the purchase over time.","m":"Different from an employee stock purchase plan: an ESOP holds shares for employees inside a retirement plan."},
{"t":"Employee stock purchase plan","a":["ESPP"],"c":"Taxes","l":2,"d":"A plan letting employees buy company stock through payroll, often at a discount of up to 15%.","u":"Discounted share purchases.","m":"Selling soon after purchase keeps the discount while limiting concentration."},
{"t":"Employer match","a":["401(k) match"],"c":"Accounts","l":1,"mod":"INV-002","d":"Money an employer contributes to your retirement plan when you contribute, such as 50% of contributions up to 6% of pay.","u":"Boosting retirement saving.","m":"An immediate, guaranteed return on your contribution; capture it first."},
{"t":"Endowment effect","c":"Behavior","l":3,"mod":"INV-060","d":"Valuing something more highly simply because you own it.","u":"Explaining reluctance to sell inherited or long-held investments.","m":"Inherited stock deserves the same review as anything you would buy new.","a":[]},
{"t":"Enhanced premium tax credit","a":["ePTC"],"c":"Insurance","l":3,"mod":"INV-074","d":"Temporary, larger marketplace credits first enacted in 2021 that removed the 400% income cap; extended through 2025, they expired on December 31, 2025.","u":"Understanding why 2026 premiums rose sharply for many enrollees.","m":"As of September 2026 no extension had become law; plan on the original rules and treat any revival as a bonus."},
{"t":"Entity redemption agreement","a":["stock redemption agreement"],"c":"Estate","l":3,"mod":"INV-094","d":"A buy-sell agreement in which the company itself buys back a departing owner's shares, often with company-owned life insurance.","u":"Simplifying buyouts where there are many owners.","m":"The Supreme Court held in Connelly (2024) that company-owned insurance proceeds increase the company's value for the deceased owner's estate."},
{"t":"Equal weighting","a":["equal-weight index","equal weight"],"c":"Strategies","l":2,"mod":"INV-044","d":"Holding every company in an index in the same amount, regardless of size, and rebalancing back to equal amounts periodically.","u":"Reducing dependence on the largest companies; it tilts toward smaller and cheaper stocks.","m":"It is an active bet against the giants, with more trading and cost. It wins in some periods and lags for years in others."},
{"t":"Equitable distribution","c":"Planning","l":2,"mod":"INV-095","d":"The system used by most states to divide marital property at divorce: a court divides what was acquired during the marriage in a way it finds fair, which is not always 50/50.","u":"Divorce settlements outside the community property states.","m":"Some states, such as North Carolina, start from an equal division; others weigh many factors. Separate property can stay separate if it is not mixed with marital property.","a":[]},
{"t":"Equity compensation","c":"Taxes","l":2,"d":"Pay in the form of company shares or rights to them: RSUs, stock options and employee stock purchase plans.","u":"Aligning employees with shareholders.","m":"Tax timing differs by type; concentration risk is the common danger."},
{"t":"Equity multiple","c":"Real estate","l":3,"mod":"INV-065","d":"Total cash an investment returns (cash flows plus sale proceeds) divided by the cash invested. A 2.0× multiple doubles your money, but says nothing about how long it took.","u":"Summarizing real estate deals, often alongside IRR.","m":"Always read it with the holding period and the IRR; a 2.0× over 20 years is weak.","a":[]},
{"t":"Equity risk premium","a":["ERP"],"c":"Foundations","l":2,"mod":"INV-001","d":"The expected return of stocks above the return on Treasury bills or bonds.","u":"Long-term planning assumptions; valuation.","m":"It is expected, not guaranteed; over some decades stocks have trailed bonds."},
{"t":"ERISA","a":["Employee Retirement Income Security Act"],"c":"Advice & regulation","l":2,"mod":"INV-027","d":"The Employee Retirement Income Security Act of 1974, the federal law governing most private-sector employer retirement and benefit plans.","u":"Setting rules for plan administration, fiduciary duties and spousal rights, and pre-empting many state laws that relate to those plans.","m":"For an employer plan, the plan documents and your beneficiary form usually control, even over a divorce decree or state law."},
{"t":"Escrow account","a":["impound account"],"c":"Real estate","l":1,"mod":"INV-064","d":"An account a mortgage servicer uses to collect part of each monthly payment and pay property taxes and insurance on the owner's behalf.","u":"Making sure taxes and insurance are paid on a mortgaged home.","m":"Your monthly payment can change even on a fixed-rate loan when taxes or insurance premiums change."},
{"t":"ESG integration","c":"Strategies","l":2,"mod":"INV-053","d":"Using environmental, social and governance information as one input, alongside financial analysis, when judging an investment's risk and return.","u":"Seeking better risk-adjusted returns rather than expressing values.","m":"Judge it like any active strategy: is there evidence it helps after fees?","a":[]},
{"t":"ESG investing","a":["sustainable investing","values-based investing"],"c":"Strategies","l":2,"d":"Considering environmental, social and governance factors in investment choices.","u":"Aligning investments with values; managing some risks.","m":"Definitions vary widely by fund; check holdings and costs."},
{"t":"ESG rating","a":["ESG score"],"c":"Strategies","l":2,"mod":"INV-053","d":"A score or grade assigned to a company by a data provider summarizing its environmental, social and governance performance or risk.","u":"Building ESG indexes and funds and screening holdings.","m":"Ratings from different providers correlated only 0.38 to 0.71 in a 2022 study, so a fund inherits its provider's particular judgments."},
{"t":"Essential expenses","a":["essential spending"],"c":"Planning","l":1,"mod":"INV-019","d":"What a household must pay even in a lean month: housing, utilities, food, insurance, basic transportation, minimum debt payments and care costs.","u":"Sizing an emergency fund in months of cover.","m":"Size the emergency fund on essentials, not on income or your full budget."},
{"t":"Estate plan","c":"Estate","l":1,"d":"The set of documents and arrangements that direct who receives your assets and who makes decisions if you cannot.","u":"Protecting family and wishes.","m":"Everyone with dependents or assets needs at least a will, beneficiary designations and powers of attorney."},
{"t":"Estate tax","c":"Estate","l":2,"d":"A federal tax on the transfer of a large estate at death, above a lifetime exemption set by law and indexed for inflation; some states levy their own.","u":"Planning for large estates.","m":"Most estates owe no federal estate tax, but state thresholds can be much lower."},
{"t":"Estate tax cliff","a":["New York estate tax cliff"],"c":"Estate","l":3,"mod":"INV-089","d":"New York's rule that its estate tax credit phases out between 100% and 105% of the basic exclusion amount and disappears above 105%, so the entire estate becomes taxable. For 2026 deaths the exclusion is $7,350,000 and the cliff is at $7,717,500.","u":"Planning New York estates near the exclusion, often with charitable bequests.","m":"A small increase in the estate near the cliff can cause a large increase in tax."},
{"t":"Estimated tax","a":["quarterly estimated tax","estimated tax payments","Form 1040-ES"],"c":"Taxes","l":1,"mod":"INV-101","d":"Tax paid during the year on income without withholding, such as self-employment profit, usually in four installments; for 2026 income they are due April 15, June 15 and September 15, 2026, and January 15, 2027 (Form 1040-ES).","u":"Keeping up with the pay-as-you-go tax system when no employer withholds.","m":"Missing installments can bring an underpayment penalty even if you pay in full by April."},
{"t":"Estimated tax safe harbor","a":["safe harbor (estimated tax)","110% rule"],"c":"Taxes","l":2,"mod":"INV-101","d":"Payment levels that avoid the underpayment penalty: withholding plus timely estimates of at least the smaller of 90% of this year's tax or 100% of last year's (110% if last year's AGI exceeded $150,000, or $75,000 if married filing separately), or owing less than $1,000.","u":"Setting quarterly payments when this year's income is uncertain.","m":"Last year's tax is a known number; paying 100% or 110% of it in four parts removes the penalty risk."},
{"t":"Event study","a":[],"c":"Strategies","l":3,"mod":"INV-043","d":"A research method that lines up many examples of one kind of announcement and measures how prices moved before and after it.","u":"Testing how quickly and accurately markets absorb news.","m":"Most event studies find prices jump at the news and then stop, which is why trading after the headline rarely pays."},
{"t":"Eviction","c":"Real estate","l":1,"mod":"INV-067","d":"The court process a landlord must use to remove a tenant, usually for unpaid rent or a serious lease violation. Changing locks or removing belongings without a court order is prohibited under many states' laws.","u":"The landlord's legal remedy when a tenancy fails.","m":"It takes weeks to months, costs legal fees and lost rent, and state and local rules vary widely. Screening and clear leases are cheaper.","a":[]},
{"t":"Ex-dividend date","a":["ex-date"],"c":"Asset classes","l":1,"mod":"INV-047","d":"The first date on which a buyer of a stock is not entitled to the next dividend payment (IRS Publication 550). The price typically opens lower by roughly the dividend.","u":"Determining who receives a dividend; it also starts the qualified-dividend holding-period test.","m":"Buying just before the ex-date to 'capture' a dividend does not create free money."},
{"t":"Exchange","a":["stock exchange"],"c":"Markets","l":1,"mod":"INV-005","d":"A regulated marketplace where securities are bought and sold, such as the New York Stock Exchange or Nasdaq.","u":"Price discovery and trading.","m":"Many retail orders are filled by market makers off-exchange, at prices tied to exchange quotes."},
{"t":"Exchange rate","a":["currency exchange rate","FX rate"],"c":"Markets","l":1,"mod":"INV-054","d":"The price of one currency in terms of another, such as dollars per euro or yen per dollar.","u":"Converting prices, incomes and investment values between countries.","m":"Owning a foreign stock means owning the currency it is priced in; dollar return = (1 + local return) x (1 + currency change) - 1."},
{"t":"Exchange-traded fund","a":["ETF"],"c":"Vehicles","l":1,"d":"A pooled investment that trades on an exchange throughout the day like a stock.","u":"Low-cost, often tax-efficient diversified investing.","m":"Check the expense ratio, spread and what the fund actually holds."},
{"t":"Exclusionary screening","a":["negative screening","exclusions"],"c":"Strategies","l":1,"mod":"INV-053","d":"Removing companies from a portfolio because of what they do, such as producing tobacco or weapons or extracting fossil fuels, often above a revenue threshold.","u":"Avoiding ownership of businesses an investor objects to.","m":"The easiest values approach to verify: the fund's prospectus lists what it excludes."},
{"t":"Executor","a":["personal representative"],"c":"Estate","l":1,"d":"The person named in a will to administer the estate.","u":"Settling an estate.","m":"Choose someone organized and trustworthy, and tell them."},
{"t":"Expense ratio","c":"Costs","l":1,"mod":"INV-007","d":"The percentage of a fund's assets deducted each year for its operating costs.","u":"Comparing fund costs.","m":"A 1% fee over 30 years consumes about a quarter of ending wealth."},
{"t":"Extended-hours trading","c":"Markets","l":2,"mod":"INV-005","d":"Trading before the 9:30 a.m. open or after the 4:00 p.m. close (Eastern), with fewer participants.","u":"Reacting to news outside regular hours.","m":"Wider spreads and sharper moves; use limit orders."},
{"t":"Factor investing","a":["smart beta"],"c":"Strategies","l":3,"d":"Tilting a portfolio toward characteristics, such as value, size, momentum, profitability or low volatility, that research has linked to returns.","u":"Systematic strategies between pure indexing and stock picking.","m":"Factors can underperform for many years; costs and discipline matter."},
{"t":"Factor loading","a":["loading","factor exposure"],"c":"Portfolio","l":3,"mod":"INV-048","d":"How strongly a portfolio's returns move with a given factor, estimated by regression. A loading of 0.5 on value means about half the value factor's return shows up in the fund.","u":"Comparing factor funds and estimating what share of a premium a fund captures.","m":"Expected gain from a tilt is roughly loading × premium minus the extra cost."},
{"t":"FAFSA","a":["Free Application for Federal Student Aid"],"c":"Planning","l":1,"mod":"INV-096","d":"The federal form used to apply for Pell Grants, federal work-study and federal student loans; most colleges and many states also use it for their own aid. By law it must be available by October 1 before the award year.","u":"Calculating the Student Aid Index that decides need-based aid.","m":"File every year, as early as you can. It uses income from the tax year two years before the award year."},
{"t":"Fair Fund","c":"Advice & regulation","l":3,"mod":"INV-103","d":"A fund established under Section 308(a) of the Sarbanes-Oxley Act of 2002 so that money paid by defendants in an SEC case can be distributed to harmed investors.","u":"Returning disgorgement and penalties to victims of securities violations.","m":"If you were harmed in an SEC case, check the SEC's list of distributions to harmed investors.","a":[]},
{"t":"Fair Housing Act","c":"Real estate","l":1,"mod":"INV-067","d":"The federal law, enacted in 1968 and amended in 1988, that bans discrimination in renting, selling and financing housing because of race, color, religion, sex, national origin, familial status or disability.","u":"Governing how landlords advertise, screen, rent and treat tenants.","m":"It applies to small landlords too, with narrow exceptions, and discriminatory advertising is banned even where an exception applies. State and local laws often add protected classes.","a":[]},
{"t":"Fair market value","a":["FMV"],"c":"Valuation","l":1,"mod":"INV-094","d":"The price at which property would change hands between a willing buyer and a willing seller, neither under any compulsion and both reasonably informed (26 CFR 20.2031-1(b)).","u":"The standard for estate and gift tax values and for heirs' stepped-up basis.","m":"For a private business or real estate, fair market value must be estimated by a qualified appraiser; it is not the price you hope for."},
{"t":"Fama–French model","c":"Strategies","l":3,"d":"A model explaining stock returns with the market plus size and value factors (1993), later extended with profitability and investment.","u":"Academic and practical factor research.","m":"The basis for many factor-tilted funds."},
{"t":"Family exemption","c":"Estate","l":3,"mod":"INV-089","d":"In Pennsylvania, a $3,500 allowance from a decedent's estate that a surviving spouse, or if none a child or parent living in the household, may claim (20 Pa.C.S. 3121); it is also deductible for inheritance tax.","u":"Letting close family keep some property promptly.","m":"Small, but one of several deductions on the Pennsylvania inheritance tax return (REV-1500).","a":[]},
{"t":"Family maximum","c":"Retirement","l":3,"d":"The cap on total Social Security benefits payable to a family on one worker's record.","u":"Households with a spouse and children claiming together.","m":"Can limit the value of child benefits."},
{"t":"Fat FIRE","c":"Independence","l":2,"mod":"INV-073","d":"Financial independence at a generous spending level, well above essential costs.","u":"Retiring early without lowering one's standard of living.","m":"The target is large, but a big share of spending is optional, which is a strong buffer against a bad sequence of returns.","a":[]},
{"t":"Fat tails","c":"Foundations","l":3,"mod":"INV-003","d":"A pattern in which extreme outcomes occur more often than a bell-shaped (normal) distribution predicts.","u":"Stress testing; understanding crashes.","m":"Plans should allow for rare, very bad years, not just typical ones."},
{"t":"FDIC insurance","a":["FDIC"],"c":"Markets","l":1,"mod":"INV-005","d":"Federal deposit insurance covering up to $250,000 per depositor, per insured bank, per ownership category.","u":"Protecting bank deposits.","m":"Does not cover stocks, bonds, mutual funds, annuities or Treasuries, even if bought at a bank."},
{"t":"Federal poverty line","a":["federal poverty level","FPL","poverty guidelines"],"c":"Insurance","l":2,"mod":"INV-074","d":"Income thresholds published each year by the Department of Health and Human Services, by household size.","u":"Setting eligibility for Medicaid and marketplace premium credits.","m":"2026 marketplace coverage uses the 2025 guidelines: $15,650 for one person and $21,150 for two, so the 400% credit cutoff is $62,600 or $84,600."},
{"t":"Fee-based advisor","a":["fee-based"],"c":"Advice & regulation","l":2,"mod":"INV-103","d":"Industry label for an advisor paid through client fees and also able to earn commissions, often because the person or firm is dually registered. Not a term defined by federal securities law.","u":"Describing a mixed compensation model.","m":"Different from fee-only. Ask for every way the advisor and firm are paid for your accounts, in dollars."},
{"t":"Fee-only advisor","c":"Advice & regulation","l":2,"d":"An advisor paid only by clients, not by commissions from products.","u":"Reducing conflicts of interest.","m":"'Fee-based' is different: it can include commissions."},
{"t":"FHA loan","c":"Real estate","l":1,"mod":"INV-070","d":"A mortgage insured by the Federal Housing Administration for owner-occupants of one- to four-unit homes, with as little as 3.5% down for credit scores of 580 or higher.","u":"Buying a home, including a two- to four-unit building you live in, with a small down payment.","m":"You pay an upfront premium of 1.75% and an annual premium, and must move in within 60 days and intend to stay at least a year.","a":[]},
{"t":"FHA mortgage insurance premium","a":["MIP","FHA MIP"],"c":"Real estate","l":2,"mod":"INV-064","d":"Insurance charged on loans insured by the Federal Housing Administration: an upfront premium plus an annual premium paid monthly. It follows FHA rules, not the Homeowners Protection Act.","u":"Enabling low-down-payment FHA loans.","m":"On many FHA loans with less than 10% down, the annual premium lasts for the life of the loan; refinancing into a conventional loan is often the only way to end it."},
{"t":"FI number","c":"Independence","l":2,"d":"The portfolio size estimated to support your spending, often calculated as annual spending × 25 (the inverse of a 4% withdrawal rate).","u":"Setting a savings target.","m":"A starting estimate; lower expected returns or long retirements argue for more."},
{"t":"Fiduciary","c":"Advice & regulation","l":1,"mod":"INV-007","d":"Someone legally required to act in your best interest. Registered investment advisers owe a fiduciary duty to their clients.","u":"Choosing an advisor.","m":"Ask in writing whether the advisor acts as a fiduciary at all times and for all accounts."},
{"t":"Filing status","c":"Taxes","l":1,"mod":"INV-095","d":"The category a federal tax return is filed under: single, head of household, married filing jointly, married filing separately, or qualifying surviving spouse. It is set by your marital status on the last day of the tax year.","u":"Choosing the brackets and standard deduction that apply to your income.","m":"A wedding, a final divorce decree or a spouse's death can change a whole year's tax. Married couples usually compare joint and separate returns.","a":[]},
{"t":"Financial independence","a":["FI"],"c":"Independence","l":1,"d":"Having enough assets that investment income can cover your living costs without needing to work.","u":"A planning goal regardless of whether you stop working.","m":"The math depends mostly on your savings rate and spending."},
{"t":"Financial order of operations","c":"Planning","l":1,"mod":"INV-020","d":"A suggested sequence for where each extra dollar goes: essentials and minimum payments, a starter emergency fund, the full employer match, high-interest debt, a full emergency fund, tax-advantaged saving, then moderate- and low-rate debt and other goals.","u":"Prioritizing competing goals with limited money.","m":"A heuristic that captures free money and certain high returns first; steps can overlap.","a":[]},
{"t":"Financial pause","c":"Planning","l":1,"mod":"INV-099","d":"A planned waiting period after a windfall, often one to three months, during which the money sits in safe, insured, liquid accounts and no hard-to-reverse decisions are made.","u":"Separating emotion from decisions and gathering facts on taxes, debts and timing.","m":"A few months of modest interest costs little; a rushed purchase, loan or high-commission product can cost a large share of the windfall.","a":[]},
{"t":"Financial strength rating","c":"Insurance","l":2,"mod":"INV-082","d":"An independent rating agency's opinion of an insurer's ability to pay policy claims, published by firms such as AM Best, S&P Global Ratings, Moody's and Fitch, each on its own scale.","u":"Screening insurers before buying annuities or long-term care insurance that must be honored for decades.","m":"Check the rating on the agency's site and read what the grade means on that agency's scale.","a":[]},
{"t":"FINRA","a":["Financial Industry Regulatory Authority"],"c":"Advice & regulation","l":1,"mod":"INV-103","d":"A private, not-for-profit self-regulatory organization, overseen by the SEC, responsible under federal law for supervising its member broker-dealers.","u":"Writing and enforcing rules for brokers, registering representatives, and running BrokerCheck and arbitration.","m":"FINRA's BrokerCheck and professional-designations database are free checks you can run on anyone."},
{"t":"FINRA BrokerCheck","a":["BrokerCheck"],"c":"Advice & regulation","l":1,"d":"A free FINRA tool showing the registration, employment history and disciplinary records of brokers and firms.","u":"Vetting brokers and advisers.","m":"Takes two minutes; do it before trusting anyone with money."},
{"t":"FIRE","a":["financial independence, retire early"],"c":"Independence","l":1,"d":"A movement pursuing financial independence through high savings rates, often aiming to retire well before traditional ages.","u":"Planning early retirement.","m":"Variants include Lean, Fat, Barista and Coast FIRE."},
{"t":"First in, first out","a":["FIFO"],"c":"Taxes","l":2,"mod":"INV-035","d":"The rule that, unless you adequately identify which shares you sold, the shares you acquired first are treated as sold first.","u":"The default method for determining the basis of shares sold.","m":"It often sells your oldest, lowest-basis shares and realizes the largest gains."},
{"t":"First-party special needs trust","a":["(d)(4)(A) trust","self-settled special needs trust"],"c":"Estate","l":3,"mod":"INV-102","d":"A trust holding a disabled person's own assets, established before age 65 by the person, a parent, grandparent, guardian or court, for the person's sole benefit, that must reimburse Medicaid from what remains at death (SSA POMS SI 01120.203).","u":"Preserving SSI and Medicaid when the person already has money, such as a settlement or an inheritance left outright.","m":"It is a repair tool; a third-party trust avoids the age limit and the payback."},
{"t":"Fisher equation","c":"Foundations","l":3,"mod":"INV-001","d":"The relationship (1 + nominal rate) = (1 + real rate) × (1 + inflation).","u":"Converting between nominal and real returns and interest rates exactly.","m":"The shortcut real ≈ nominal − inflation is close at low rates and misleading at high ones."},
{"t":"Fixed amortization method","c":"Retirement","l":3,"mod":"INV-074","d":"A 72(t) method that sets a level annual payment paying off the balance over your life expectancy at a permitted interest rate.","u":"A higher, fixed 72(t) payment.","m":"In the IRS example, $400,000 at age 50 and 4% gives $21,102 a year, the same every year.","a":[]},
{"t":"Fixed annuitization method","c":"Retirement","l":3,"mod":"INV-074","d":"A 72(t) method that divides the balance by an annuity factor built from the IRS mortality rates and a permitted interest rate.","u":"Usually the highest fixed 72(t) payment.","m":"In the IRS example, $400,000 at age 50 and 4% gives $22,030 a year.","a":[]},
{"t":"Fixed expense","c":"Planning","l":1,"mod":"INV-018","d":"A cost that is the same every month and changes only with a decision, such as rent, a loan payment or an insurance premium.","u":"Finding the one-time decisions that change a budget for years.","m":"Lowering a fixed cost once usually saves more than trimming variable costs every week.","a":[]},
{"t":"Fixed indexed annuity","a":["indexed annuity","equity-indexed annuity"],"c":"Insurance","l":2,"mod":"INV-017","d":"An insurance contract whose credited return is linked to a market index, subject to limits such as a participation rate, cap or spread, with protection against index losses. Most are regulated by states as insurance, not by the SEC.","u":"Offering some market-linked growth with principal protection, usually with a multi-year surrender period.","m":"Dividends are usually excluded and gains are capped, so you get much less than the index in good years. Read the crediting method and surrender schedule."},
{"t":"Fixed real withdrawal","a":["constant-dollar withdrawal","inflation-adjusted withdrawal"],"c":"Retirement","l":2,"mod":"INV-076","d":"A spending rule in which you withdraw a percentage of the starting portfolio in year one, then the same dollar amount raised by inflation every later year, whatever markets do. It is the method behind the 4% rule.","u":"Testing how much steady, inflation-protected income a portfolio could have supported historically.","m":"It gives the steadiest income but is the most fragile rule, because spending never adjusts to a falling portfolio."},
{"t":"Fixed-rate mortgage","c":"Real estate","l":1,"mod":"INV-064","d":"A mortgage whose interest rate stays the same for the whole term, so principal and interest payments never change.","u":"Predictable housing costs; protection against rising rates.","m":"If rates fall you can refinance; if they rise you keep your rate. That one-way option is part of what the fixed rate costs.","a":[]},
{"t":"Flat tax","a":["flat income tax"],"c":"Taxes","l":1,"mod":"INV-041","d":"An income tax with a single rate on all taxable income, as North Carolina, Pennsylvania, Arizona and Colorado use.","u":"Understanding state tax designs.","m":"What a state taxes can matter more than its rate."},
{"t":"Flexible spending account","a":["FSA","health FSA","dependent-care FSA"],"c":"Accounts","l":1,"mod":"INV-022","d":"An employer account funded from pre-tax pay for medical expenses (health FSA) or for child and dependent care (dependent-care FSA).","u":"Paying predictable costs with untaxed money.","m":"Mostly use-it-or-lose-it: elect only what you are sure to spend. Unlike an HSA, it does not stay with you when you leave."},
{"t":"Floating rate note","a":["FRN","Treasury floating rate note"],"c":"Asset classes","l":3,"mod":"INV-010","d":"A bond whose interest rate resets periodically. Treasury FRNs mature in two years, pay interest four times a year, and reset weekly to the latest 13-week bill auction rate plus a fixed spread.","u":"Earning short-term rates with almost no price risk from rate changes.","m":"An alternative to rolling T-bills; its yield falls when short-term rates fall."},
{"t":"Foreclosure","c":"Real estate","l":1,"mod":"INV-066","d":"The legal process by which a lender takes and sells a property after the borrower stops paying the loan secured by it.","u":"The lender's remedy for default.","m":"It damages credit for years and can leave a deficiency balance where state law allows. Talk to the servicer early; options shrink as missed payments pile up.","a":[]},
{"t":"Foreign tax credit","a":["FTC","Form 1116"],"c":"Taxes","l":2,"mod":"INV-054","d":"A US tax credit for qualifying foreign income taxes on income that is also subject to US tax, such as foreign tax withheld on dividends; the tax can instead be taken as an itemized deduction.","u":"Avoiding double taxation of foreign investment income.","m":"The IRS says the credit is usually more advantageous; because it requires US-taxed income, it generally does not help inside an IRA or 401(k)."},
{"t":"Form 1099-DA","a":["1099-DA"],"c":"Taxes","l":2,"mod":"INV-015","d":"The IRS form on which brokers report digital asset sales. Brokers must report gross proceeds for transactions on or after January 1, 2025, and cost basis for certain transactions on or after January 1, 2026.","u":"Reporting crypto sales to the IRS and to taxpayers.","m":"The IRS will see your crypto sales; keep your own purchase records, because basis may be missing for assets bought earlier or moved between platforms."},
{"t":"Form 706","a":["estate tax return"],"c":"Estate","l":2,"mod":"INV-088","d":"The United States Estate (and Generation-Skipping Transfer) Tax Return, filed by the executor within nine months of death, with an automatic six-month extension available on Form 4768.","u":"Reporting and paying estate tax, electing portability and allocating GST exemption.","m":"For 2026 deaths it is required above $15,000,000 of gross estate plus adjusted taxable gifts, and needed at any size to elect portability for a surviving spouse."},
{"t":"Form 709","a":["gift tax return"],"c":"Estate","l":2,"mod":"INV-088","d":"The United States Gift (and Generation-Skipping Transfer) Tax Return, due by April 15 of the year after the gift (extended with an income tax extension or Form 8892).","u":"Reporting gifts above the annual exclusion, gifts of future interests, gift splitting and 529 five-year elections.","m":"Filing it usually means paperwork, not tax: tax is due only after lifetime taxable gifts exceed the basic exclusion amount."},
{"t":"Form ADV","c":"Advice & regulation","l":3,"d":"The SEC registration and disclosure document for investment advisers; Part 2 is a plain-language brochure for clients.","u":"Researching an adviser.","m":"Read the fees and conflicts sections before signing."},
{"t":"Form CRS","a":["Customer Relationship Summary","Client Relationship Summary","relationship summary","Form ADV Part 3"],"c":"Advice & regulation","l":1,"mod":"INV-103","d":"A short plain-English summary that SEC-registered investment advisers and broker-dealers serving retail investors must file, post on their website and deliver. It is limited to two pages (four for a dual registrant describing both services) and uses standard headings: introduction; relationships and services; fees, costs, conflicts and standard of conduct; disciplinary history; additional information.","u":"Comparing firms' services, fees, conflicts and legal duties before opening, ending or switching a relationship.","m":"Ask for it at the first meeting. Its prescribed questions, such as how much of $10,000 would go to fees, make a ready-made interview script."},
{"t":"Form W-2G","c":"Taxes","l":2,"mod":"INV-099","d":"The IRS form a payer issues to report certain gambling winnings and any federal tax withheld. For 2026, payers withhold 24% on lottery prizes of more than $5,000.","u":"Reporting lottery, sweepstakes and other gambling winnings on the tax return.","m":"The 24% withheld is often well below the tax owed on a large prize, which is taxed mostly at 37%.","a":[]},
{"t":"Fractional shares","c":"Markets","l":1,"mod":"INV-005","d":"Portions of a single share, offered by many brokers so investors can buy by dollar amount.","u":"Investing small, regular amounts in full diversification.","m":"Removes the barrier of high share prices."},
{"t":"Framing effect","a":["framing"],"c":"Behavior","l":2,"mod":"INV-060","d":"Making a different choice when the same facts are described differently, for example as a gain or as a loss.","u":"Explaining inconsistent decisions and some sales techniques.","m":"Restate any offer both ways ('90% survive' and '10% die') before deciding."},
{"t":"Fraud alert","a":["extended fraud alert"],"c":"Planning","l":2,"mod":"INV-021","d":"A notice on your credit report asking lenders to take steps to verify your identity before extending credit. An initial alert lasts one year; an extended alert for identity-theft victims lasts seven years.","u":"A lighter-touch protection than a freeze, placed by contacting one bureau.","m":"Useful if you suspect fraud but need to keep applying for credit; a freeze is stronger."},
{"t":"Free cash flow","a":["FCF"],"c":"Companies","l":2,"mod":"INV-006","d":"Operating cash flow minus capital expenditures.","u":"Valuation; judging dividend and buyback capacity.","m":"Dividends paid beyond free cash flow for long must be funded by borrowing or asset sales."},
{"t":"Full retirement age","a":["FRA"],"c":"Retirement","l":1,"d":"The age at which you receive your full Social Security benefit: 67 for people born in 1960 or later.","u":"Claiming decisions.","m":"Claiming at 62 permanently cuts the benefit; delaying past FRA raises it until 70."},
{"t":"Fund of funds","c":"Vehicles","l":2,"mod":"INV-050","d":"A fund whose holdings are other funds, such as a target-date fund that owns a handful of index funds.","u":"Building a diversified mix from a few broad building blocks.","m":"Your cost includes the underlying funds' expenses, shown in the prospectus as acquired fund fees and expenses.","a":[]},
{"t":"Fund overlap","a":["portfolio overlap"],"c":"Portfolio","l":2,"mod":"INV-055","d":"The extent to which several funds you own hold the same underlying securities.","u":"Spotting portfolios that look diversified by fund count but are concentrated in the same companies.","m":"Six large-cap US funds can behave almost like one. Count exposures, not funds."},
{"t":"Funds from operations","a":["FFO"],"c":"Real estate","l":3,"mod":"INV-069","d":"A REIT earnings measure that adds real estate depreciation back to net income and excludes gains and losses from property sales.","u":"Judging whether a REIT's dividend is paid from its operations.","m":"A distribution consistently larger than FFO is being funded by something else, such as borrowing."},
{"t":"Future value","a":["FV"],"c":"Foundations","l":1,"mod":"INV-002","d":"What a sum grows to after a number of periods at a given rate: FV = PV × (1 + r)^n.","u":"Projecting balances for goals.","m":"Every projection you see is this formula plus assumptions; question the assumptions."},
{"t":"Futures contract","c":"Asset classes","l":3,"d":"An agreement to buy or sell an asset at a set price on a future date, traded on an exchange.","u":"Hedging and commodity exposure.","m":"Highly leveraged; not covered by SIPC."},
{"t":"GAAP","a":["Generally Accepted Accounting Principles"],"c":"Companies","l":3,"mod":"INV-006","d":"The accounting rules US public companies must use in financial statements.","u":"Consistent, comparable reporting.","m":"Company-defined 'adjusted' figures must be reconciled to GAAP; compare the two."},
{"t":"General obligation bond","a":["GO bond"],"c":"Asset classes","l":2,"mod":"INV-010","d":"A municipal bond backed by the issuing government's general taxing power rather than a specific revenue source.","u":"Financing public purposes such as schools and general government projects.","m":"Usually among the safer municipal bonds, though the exact backing depends on state and local law."},
{"t":"General partner","a":["GP","sponsor"],"c":"Real estate","l":2,"mod":"INV-069","d":"The manager of a partnership or deal, who controls decisions and bears management responsibility; in real estate syndications, the sponsor.","u":"Running a syndicated property and earning fees and a share of profits.","m":"In a private deal the sponsor's skill and honesty matter as much as the building."},
{"t":"Generation-skipping transfer tax","a":["GST tax","generation-skipping tax"],"c":"Estate","l":3,"mod":"INV-088","d":"A federal tax, at the 40% maximum estate tax rate, on transfers to skip persons such as grandchildren above the GST exemption, which is $15,000,000 for 2026 (Rev. Proc. 2025-32).","u":"Preventing wealth from skipping a generation's estate tax.","m":"Annual exclusion gifts and tuition paid directly generally fall outside it. It matters mainly for very large gifts or long-lasting trusts, and the exemption is not portable."},
{"t":"Geographic arbitrage","a":["geoarbitrage"],"c":"Independence","l":2,"mod":"INV-073","d":"Moving to a lower-cost area to reduce spending, and therefore the FI number.","u":"Shortening the path to financial independence without earning more.","m":"Compare after-tax and after-premium spending: state taxes and health-insurance prices change with the move, not just rent."},
{"t":"Geometric average return","a":["compound annual growth rate","CAGR"],"c":"Foundations","l":2,"mod":"INV-003","d":"The constant yearly rate that produces the same ending wealth as the actual sequence of returns.","u":"Describing actual investor experience over multi-year periods.","m":"Use this figure to describe history. For US stocks, 1928–2025: about 10.0% versus an arithmetic 11.9%."},
{"t":"GICS","a":["Global Industry Classification Standard"],"c":"Markets","l":2,"mod":"INV-011","d":"A classification of companies developed in 1999 by S&P Dow Jones Indices and MSCI, with 11 sectors, 25 industry groups, 74 industries and 163 sub-industries.","u":"Sorting companies for indexes, sector funds and portfolio analysis.","m":"Check your portfolio's sector mix against the market's. Information technology was 31.2% of the MSCI ACWI world index in August 2026."},
{"t":"Gift splitting","c":"Estate","l":2,"mod":"INV-092","d":"An election by a married couple to treat every gift either makes to a third party during the year as made half by each, reported on Form 709.","u":"Letting one spouse give up to twice the annual exclusion to a person without a taxable gift.","m":"A couple can give $38,000 to each person in 2026, even from one spouse's account, by electing to split.","a":[]},
{"t":"Gift tax","c":"Estate","l":2,"d":"A federal tax on large lifetime gifts, unified with the estate tax; gifts above the annual exclusion reduce the lifetime exemption and are reported on Form 709.","u":"Planning lifetime transfers.","m":"Few people ever owe gift tax; filing a return is not the same as owing tax."},
{"t":"Glide path","c":"Portfolio","l":2,"d":"The schedule by which a target-date fund's mix shifts from stocks toward bonds over time.","u":"Reducing risk as a goal approaches.","m":"Glide paths differ between fund families; some keep more stocks after the target date."},
{"t":"Goal-based planning","c":"Planning","l":1,"d":"Organizing money around specific goals, each with its own amount, date and investment approach.","u":"Deciding how to invest each pot of money.","m":"Different goals deserve different risk levels."},
{"t":"Gold","c":"Asset classes","l":1,"mod":"INV-003","d":"A precious metal held as a store of value and crisis hedge.","u":"Diversification; some inflation and crisis protection.","m":"About as volatile as stocks over 1928–2025 with roughly half the return, because it pays nothing."},
{"t":"Gold standard","a":["gold convertibility"],"c":"Asset classes","l":2,"mod":"INV-013","d":"A monetary system in which the currency can be exchanged for a fixed weight of gold. The US dollar was fixed at $20.67 an ounce from 1900 and $35 from 1934; convertibility for foreign governments ended on August 15, 1971.","u":"Understanding gold's price history and why early gold data mostly reflect policy.","m":"Before 1971 gold's dollar price was largely set by law, so long-run gold statistics that begin earlier mix policy with market behavior."},
{"t":"Golden Butterfly portfolio","a":["Golden Butterfly"],"c":"Strategies","l":3,"mod":"INV-049","d":"An allocation of 20% each in US large-cap stocks, US small-cap value stocks, long-term Treasuries, short-term Treasuries and gold, created by the author of the Portfolio Charts website as a variation on the Permanent Portfolio.","u":"Seeking the Permanent Portfolio's resilience with more growth.","m":"It was designed with the historical record in view, so its backtests partly reflect the data it was built from."},
{"t":"Gordon growth model","a":["dividend discount model"],"c":"Valuation","l":3,"mod":"INV-006","d":"A valuation formula for a dividend growing forever at a constant rate: price = next year's dividend ÷ (required return − growth).","u":"Estimating value; reverse-engineering the growth a price implies.","m":"Expected return ≈ dividend yield + growth."},
{"t":"Government money market fund","c":"Vehicles","l":2,"mod":"INV-008","d":"A money market fund that invests at least 99.5% of its total assets in cash, government securities and repurchase agreements fully collateralized by them (SEC Rule 2a-7).","u":"Holding cash in brokerage accounts with very low credit risk.","m":"The usual best choice for cash in a brokerage account. Not FDIC-insured, but its holdings are mostly the same Treasury bills you could buy directly.","a":[]},
{"t":"Government Pension Offset","a":["GPO"],"c":"Retirement","l":3,"mod":"INV-078","d":"A rule, repealed by the Social Security Fairness Act, that reduced or eliminated spousal and survivor benefits for people with a pension from work not covered by Social Security.","u":"It no longer applies to benefits payable from January 2024.","m":"Spouses and widows with government pensions may now be entitled to benefits they were previously denied."},
{"t":"Grantor","a":["settlor","trustor"],"c":"Estate","l":1,"mod":"INV-087","d":"The person who creates a trust, writes its terms and transfers assets into it.","u":"Identifying whose trust it is, whose creditors can reach it, and who is taxed on its income in some cases.","m":"In a revocable living trust you are usually the grantor, the trustee and the beneficiary all at once while you live."},
{"t":"Grantor trust","c":"Estate","l":3,"mod":"INV-087","d":"A trust whose income is taxed to the grantor, not to the trust, because the grantor keeps certain powers. All revocable trusts are grantor trusts; some irrevocable trusts are drafted as grantor trusts on purpose.","u":"Letting the grantor pay the trust's income tax, which in effect adds to the gift, while the assets may stay outside the estate.","m":"Under Revenue Ruling 2023-2, assets of a grantor trust that are not included in the gross estate get no step-up in basis at the grantor's death.","a":[]},
{"t":"Greenwashing","c":"Advice & regulation","l":1,"mod":"INV-053","d":"Marketing that makes an investment or company sound more environmentally or socially responsible than its practices justify.","u":"Describing misleading ESG claims; the SEC has brought enforcement actions over them.","m":"Check holdings and methods, not fund names.","a":[]},
{"t":"Gross estate","c":"Estate","l":2,"mod":"INV-088","d":"Everything a person owned or controlled at death for federal estate tax purposes, including retirement accounts, life insurance they owned, revocable trusts and their share of joint property.","u":"The starting point of the estate tax calculation and the Form 706 filing test.","m":"It is usually larger than the probate estate, because it includes assets that pass by beneficiary form or title.","a":[]},
{"t":"Gross income","c":"Taxes","l":1,"mod":"INV-029","d":"All income the tax law counts before any subtractions: wages, self-employment income, interest, dividends, capital gains, rents, traditional retirement-account withdrawals and part of Social Security benefits. Some income, such as municipal bond interest and qualified Roth withdrawals, is excluded.","u":"The starting point of a tax return and the test for whether you must file.","m":"Money growing inside an IRA, 401(k) or HSA is not gross income until it comes out, and often not even then.","a":[]},
{"t":"Gross margin","c":"Companies","l":2,"mod":"INV-006","d":"Gross profit (revenue minus the direct cost of goods sold) as a percentage of revenue.","u":"Judging pricing power.","m":"Stable or rising gross margins suggest a durable competitive position."},
{"t":"Gross potential rent","a":["GPR"],"c":"Real estate","l":2,"mod":"INV-065","d":"The rent a property would collect in a year if every unit were leased all year at market rent and every tenant paid.","u":"The starting line of a rental income statement.","m":"Nobody collects it. Subtract vacancy and unpaid rent before judging any property."},
{"t":"Gross profit ratio","c":"Taxes","l":3,"mod":"INV-094","d":"In an installment sale, the gain divided by the contract price: the share of each principal payment that is taxable gain.","u":"Calculating how much gain to report each year under the installment method.","m":"Selling for $1.2 million with a $200,000 basis gives a ratio of 83.3%.","a":[]},
{"t":"Gross return","a":["gross performance"],"c":"Costs","l":2,"mod":"INV-057","d":"Investment performance before some or all fees are deducted.","u":"Showing what the investments themselves earned before the cost of management.","m":"Treat a gross figure as the starting point, never the answer; you keep only the net."},
{"t":"Group term life insurance","a":["group life insurance","group life"],"c":"Insurance","l":1,"mod":"INV-022","d":"Term life insurance provided through an employer, often one or two times salary.","u":"A base layer of protection for dependents at little or no cost.","m":"It usually ends with the job and is rarely enough for a family; the cost of employer-paid coverage above $50,000 is taxable imputed income."},
{"t":"Growth investing","c":"Strategies","l":2,"d":"Buying companies expected to grow revenue and earnings faster than average, often at higher valuations.","u":"Seeking companies with strong future prospects.","m":"High expectations leave little room for disappointment."},
{"t":"Guardianship","a":["conservatorship","guardian","conservator"],"c":"Estate","l":2,"mod":"INV-097","d":"A court process that gives someone legal authority over another person's finances, personal decisions or both, after the person is found unable to manage them.","u":"Acting for a person who lost capacity without having signed a power of attorney.","m":"It is public, slower and more expensive than a durable power of attorney signed in advance."},
{"t":"Guardrails","a":["Guyton-Klinger guardrails"],"c":"Retirement","l":3,"d":"A withdrawal strategy that cuts or raises spending when the withdrawal rate drifts outside set bounds.","u":"Balancing higher spending with protection.","m":"Accepting modest cuts in bad years allows a higher starting withdrawal."},
{"t":"Hard inquiry","a":["hard pull","hard credit inquiry"],"c":"Planning","l":2,"mod":"INV-021","d":"A lender's check of your credit report when you apply for credit.","u":"Showing lenders how recently and often you have sought new credit.","m":"FICO says one inquiry takes fewer than five points off most scores and counts for a year; loan rate-shopping inquiries within a short window count as one."},
{"t":"Head of household","a":["HOH"],"c":"Taxes","l":1,"mod":"INV-095","d":"A filing status for an unmarried person who pays more than half the cost of keeping up a home for a qualifying person, such as a child. For a dependent parent, the parent does not need to live with you.","u":"Giving single parents and other unmarried caregivers wider brackets and a larger standard deduction than single filers.","m":"For 2026 the standard deduction is $24,150 versus $16,100 for a single filer. Marrying ends it, which can create a marriage penalty."},
{"t":"Health care directive","a":["advance directive","health care proxy"],"c":"Estate","l":1,"d":"Documents stating medical wishes and naming someone to make health decisions if you cannot.","u":"End-of-life and incapacity planning.","m":"Spares family from guessing."},
{"t":"Health insurance marketplace","a":["ACA marketplace","Affordable Care Act marketplace"],"c":"Insurance","l":1,"mod":"INV-074","d":"The government-run shopping service, HealthCare.gov or a state site, for individual health insurance under the Affordable Care Act.","u":"Buying coverage when you have no job-based plan, including before Medicare.","m":"Losing job-based coverage or COBRA usually opens a 60-day special enrollment period; voluntarily dropping COBRA does not."},
{"t":"Health savings account","a":["HSA"],"c":"Accounts","l":2,"d":"A tax-advantaged account for people with an eligible high-deductible health plan: contributions are deductible, growth is untaxed, and qualified medical withdrawals are tax-free.","u":"Medical costs now or in retirement; a supplemental retirement account.","m":"After 65, non-medical withdrawals are taxed as income without penalty."},
{"t":"Hedge fund","c":"Asset classes","l":3,"d":"A lightly regulated pooled fund using flexible strategies, generally open only to accredited investors.","u":"Seeking returns uncorrelated with markets.","m":"High fees; results vary widely."},
{"t":"HELOC","a":["home equity line of credit"],"c":"Real estate","l":2,"d":"A revolving line of credit secured by home equity.","u":"Flexible borrowing for renovations or emergencies.","m":"Variable rates; your home is the collateral."},
{"t":"Herding","c":"Behavior","l":2,"d":"Following what others are doing rather than your own analysis.","u":"Explaining bubbles and crashes.","m":"If everyone you know is buying something, ask what price already assumes."},
{"t":"High-deductible health plan","a":["HDHP"],"c":"Insurance","l":2,"d":"A health plan meeting IRS minimum-deductible and maximum out-of-pocket rules, required for HSA eligibility.","u":"Qualifying for an HSA.","m":"Compare total expected costs, not just premiums."},
{"t":"High-water mark","c":"Costs","l":3,"mod":"INV-014","d":"A rule that a fund manager earns a performance fee only on gains that take the fund above its previous highest value.","u":"Preventing managers from charging performance fees twice on the same gains after a loss.","m":"Check that a fund has one; without it, you can pay performance fees for merely recovering earlier losses.","a":[]},
{"t":"High-yield bond","a":["junk bond"],"c":"Asset classes","l":2,"d":"A bond rated below investment grade, paying higher interest for higher default risk.","u":"Income-seeking portfolios.","m":"Tends to fall with stocks in crises, so it cushions less than Treasuries."},
{"t":"High-yield savings account","c":"Asset classes","l":1,"d":"A bank savings account paying a higher interest rate than a traditional savings account, often at online banks.","u":"Emergency funds and short-term goals.","m":"FDIC-insured within limits; rates change with the market."},
{"t":"Hindsight bias","c":"Behavior","l":2,"mod":"INV-060","d":"The feeling, after the fact, that an outcome was predictable all along.","u":"Explaining why past crashes look obvious and future ones do not.","m":"Keep a short written record of why you made each decision; it corrects the memory.","a":[]},
{"t":"HIPAA authorization","a":["HIPAA release"],"c":"Estate","l":1,"mod":"INV-084","d":"A signed form allowing health care providers to share your protected health information with the people you name. Federal privacy rules generally require a valid authorization before disclosure (45 CFR 164.508).","u":"Letting family, or a financial agent who needs proof of incapacity, get medical information.","m":"Once a child turns 18, parents have no automatic right to their records. A young adult should sign one along with a health care power of attorney."},
{"t":"Historical worst-case withdrawal rate","a":["SAFEMAX"],"c":"Retirement","l":3,"mod":"INV-073","d":"The highest first-year withdrawal rate that would have lasted a given number of years in every historical start year tested.","u":"Stress-testing withdrawal rates against the worst periods on record.","m":"In US data for 1928–2025 with a 75/25 mix, it falls from about 4.15% over 30 years to about 3.63% over 60 (year-end withdrawals)."},
{"t":"Holding period","c":"Foundations","l":1,"mod":"INV-003","d":"The length of time an investment is held.","u":"Judging risk: longer holding periods have historically reduced the chance of loss for diversified stock portfolios.","m":"Match investments to the time until you need the money."},
{"t":"Home bias","c":"Behavior","l":2,"d":"The tendency to over-invest in one's own country's markets.","u":"Explaining concentrated national portfolios.","m":"No country leads forever; Japan's market took 34 years to regain its 1989 peak."},
{"t":"Home equity","c":"Real estate","l":1,"d":"The market value of a home minus what is owed on it.","u":"Net worth; borrowing against a home.","m":"Illiquid unless you sell or borrow."},
{"t":"Home sale exclusion","a":["Section 121 exclusion"],"c":"Real estate","l":2,"d":"A rule excluding up to $250,000 of gain ($500,000 for married couples filing jointly) on the sale of a main home owned and lived in for at least two of the last five years.","u":"Tax-free gains on a primary residence.","m":"The limits are fixed in law and not indexed for inflation."},
{"t":"Homemade dividend","a":["homemade dividends"],"c":"Strategies","l":2,"mod":"INV-047","d":"Creating your own cash flow by selling a small part of your holdings instead of relying on the dividends companies pay.","u":"Drawing exactly the income you need from a diversified portfolio whatever its yield.","m":"Before taxes, selling 2% and receiving a 2% dividend are equivalent; in taxable accounts selling is often taxed less."},
{"t":"Homeowners insurance","c":"Insurance","l":1,"mod":"INV-063","d":"Insurance covering damage to a home you live in, its contents and your personal liability. Lenders require it on mortgaged homes.","u":"Protecting the largest asset most households own.","m":"Premiums have risen fast in some regions; get a quote before you buy, not after.","a":[]},
{"t":"Homeowners Protection Act","a":["HPA","PMI Cancellation Act"],"c":"Real estate","l":2,"mod":"INV-064","d":"A 1998 federal law giving borrowers the right to cancel private mortgage insurance on most conventional loans when the balance is scheduled to reach 80% of the home's original value, and requiring automatic termination at 78% or at the loan's midpoint.","u":"Removing PMI from a conventional mortgage.","m":"Mark the 80% date on your calendar and ask in writing; you do not have to wait for the automatic date."},
{"t":"House hacking","c":"Real estate","l":2,"d":"Living in one part of a property and renting out the rest.","u":"Reducing housing costs and starting in real estate.","m":"Owner-occupied financing rules can make it accessible; you become a landlord at home."},
{"t":"Human capital","c":"Foundations","l":3,"mod":"INV-004","d":"The present value of your future earnings.","u":"Seeing your job as part of your total portfolio.","m":"If your income depends on one company or industry, avoid concentrating your savings there too."},
{"t":"Hurdle rate","a":["preferred return"],"c":"Costs","l":3,"mod":"INV-014","d":"A minimum return a fund must earn before its manager receives a performance fee.","u":"Tying incentive fees to returns above a benchmark or fixed rate.","m":"A hurdle of 0% means the manager is paid for any gain, including gains you could have earned in Treasury bills."},
{"t":"Hybrid long-term care policy","a":["linked-benefit policy","hybrid LTC"],"c":"Insurance","l":2,"mod":"INV-083","d":"A life insurance policy or annuity with a long-term care benefit attached: it pays for care if needed, and a death benefit or other value if not.","u":"Covering long-term care without the use-it-or-lose-it feel of traditional insurance. Existing life or annuity contracts can be exchanged tax-free for qualified LTC contracts (26 U.S.C. §1035).","m":"Flexibility costs money: per dollar of care benefit, hybrids usually cost more than traditional coverage."},
{"t":"I bond","a":["Series I savings bond"],"c":"Asset classes","l":2,"d":"A US savings bond whose rate combines a fixed rate and an inflation rate tied to the CPI-U, bought through TreasuryDirect.","u":"Inflation-protected savings.","m":"Annual purchase limits apply; cannot be redeemed in the first year, and there is an interest penalty within five years."},
{"t":"Impact investing","c":"Strategies","l":2,"mod":"INV-053","d":"Investing with the intention of producing measurable social or environmental results alongside a financial return, often in private companies, projects or community lending.","u":"Directing capital toward specific outcomes.","m":"The most direct route to impact, usually with less liquidity and higher costs, and rarely in a 401(k).","a":[]},
{"t":"Implied volatility","c":"Asset classes","l":3,"mod":"INV-016","d":"The future volatility of the underlying asset that is built into an option's market price, found by running a pricing model such as Black–Scholes backward.","u":"Comparing how expensive options are; pricing and risk management.","m":"Options often cost the most just before events like earnings. Research on retail traders finds they tend to overpay for volatility at those times.","a":[]},
{"t":"Imputed income","c":"Taxes","l":2,"mod":"INV-022","d":"The value of a non-cash benefit that the tax law treats as wages, such as employer-paid group term life insurance above $50,000, figured with an IRS table by age.","u":"Taxing fringe benefits fairly.","m":"It appears on your pay stub and W-2 but usually adds only a small amount of tax.","a":[]},
{"t":"Imputed rent","c":"Real estate","l":3,"mod":"INV-063","d":"The rent an owner-occupier would have to pay to live in their own home; the 'dividend' a house pays its owner in housing rather than cash.","u":"Measuring the full return on owning a home; home price indexes leave it out.","m":"A home's price gain understates what owning returns, and a stock index's total return is not comparable to a price-only home index.","a":[]},
{"t":"In the money","a":["out of the money","at the money","moneyness"],"c":"Asset classes","l":2,"mod":"INV-016","d":"An option is in the money when exercising it now would be worth something: a call with a strike below the stock price, or a put with a strike above it. Out of the money is the reverse; at the money means the strike is near the current price.","u":"Describing an option's intrinsic value and its likelihood of exercise.","m":"An out-of-the-money option is all time value, which drains away as expiration approaches."},
{"t":"In-kind support and maintenance","a":["ISM"],"c":"Planning","l":3,"mod":"INV-102","d":"Shelter provided by someone else, counted by SSA as unearned income that can reduce SSI. Since September 30, 2024, food is no longer counted.","u":"Measuring non-cash help in the SSI income test.","m":"When a trust pays an SSI recipient's rent, SSI falls by no more than $351.33 a month in 2026."},
{"t":"In-kind transfer","a":["transfer in kind"],"c":"Markets","l":2,"mod":"INV-104","d":"Moving the securities themselves from one account or firm to another, rather than selling them and moving cash.","u":"Changing brokers or consolidating accounts while staying invested.","m":"In a taxable account, moving in kind avoids selling, so you can decide separately when to realize gains."},
{"t":"In-plan Roth conversion","a":["in-plan Roth rollover"],"c":"Accounts","l":3,"mod":"INV-031","d":"Moving money from the traditional or after-tax part of a workplace plan to its Roth part, paying tax on any pre-tax amount converted.","u":"Converting within the plan, including as the second step of a mega backdoor Roth.","m":"Only available if your plan offers it."},
{"t":"Incentive stock option","a":["ISO","ISOs"],"c":"Taxes","l":3,"d":"A stock option that can receive capital-gains treatment if holding rules are met, but whose exercise can trigger the alternative minimum tax.","u":"Equity pay, often at private or younger companies.","m":"Model AMT before exercising."},
{"t":"Income buffer","a":["smoothing account"],"c":"Planning","l":1,"mod":"INV-101","d":"A separate account that receives irregular business income after the tax set-aside and pays the household a fixed monthly salary.","u":"Turning lumpy income into predictable pay.","m":"Start with two to three months of salary in it and set the salary at or below average net income."},
{"t":"Income floor","a":["floor-and-upside","flooring"],"c":"Retirement","l":2,"mod":"INV-082","d":"A retirement plan that covers essential spending with guaranteed lifetime income (Social Security, pensions, annuities, bond or TIPS ladders) and funds discretionary spending from investments.","u":"Making market falls and long lives less threatening to basic needs.","m":"List essential spending, subtract guaranteed income, and only the gap is a candidate for an annuity or ladder."},
{"t":"Income in respect of a decedent","a":["IRD"],"c":"Taxes","l":3,"mod":"INV-090","d":"Income the decedent had a right to but had not been taxed on at death, such as traditional IRA and 401(k) balances, unpaid wages and accrued savings-bond interest. It gets no step-up in basis (IRC 1014(c)).","u":"Taxing that income to whoever receives it; heirs may deduct estate tax attributable to it if the estate paid any.","m":"Inheriting $100,000 of a traditional IRA is worth less after tax than inheriting $100,000 of stock."},
{"t":"Income statement","c":"Companies","l":1,"mod":"INV-006","d":"A financial statement showing revenue, expenses and profit over a period.","u":"Judging how much a company sells and earns.","m":"Read it with the cash flow statement; profit is not the same as cash."},
{"t":"Income-driven repayment","a":["IDR","income-driven repayment plan"],"c":"Planning","l":2,"mod":"INV-020","d":"A federal student-loan repayment plan that sets payments by income and family size rather than by the balance, with any remaining balance forgiven after a long period.","u":"Keeping federal loan payments affordable when income is low relative to debt.","m":"Lower payments often mean more interest over a longer time. The plans available changed with the 2025 law; check StudentAid.gov."},
{"t":"Index","a":["market index"],"c":"Markets","l":1,"d":"A defined basket of securities used to measure a market, such as the S&P 500.","u":"Benchmarks; the basis of index funds.","m":"You cannot invest in an index directly, only in a fund that tracks it."},
{"t":"Index fund","c":"Vehicles","l":1,"d":"A mutual fund or ETF that aims to match the return of a market index rather than beat it.","u":"Low-cost, broadly diversified core holdings.","m":"Asset-weighted, index equity mutual funds cost about 0.05% a year in 2025 (ICI)."},
{"t":"Indirect rollover","a":["60-day rollover"],"c":"Accounts","l":1,"mod":"INV-059","d":"A distribution paid to you that you redeposit in a plan or IRA yourself, which the IRS requires within 60 days of receiving it.","u":"Occasionally unavoidable when a check was made out to the owner.","m":"From a workplace plan 20% is withheld, and you must replace it from other money to roll over the full amount. Miss 60 days and the money is taxable."},
{"t":"Individual retirement account","a":["IRA","traditional IRA"],"c":"Accounts","l":1,"d":"A personal retirement account with tax advantages; traditional IRA contributions may be deductible depending on income and workplace plan coverage.","u":"Retirement saving outside or alongside workplace plans.","m":"Rollover IRAs let you consolidate old workplace plans."},
{"t":"Inflation","c":"Foundations","l":1,"mod":"INV-001","d":"The general rise in prices over time, usually measured as a yearly percentage change in a price index such as the Consumer Price Index.","u":"Adjusting wages, benefits, tax brackets and contracts; converting nominal returns into real returns.","m":"At 3% a year, prices double in about 24 years. Long-term money must grow at least that fast just to keep its buying power."},
{"t":"Information ratio","a":["IR"],"c":"Portfolio","l":3,"mod":"INV-045","d":"A manager's average return above the benchmark divided by tracking error: edge per unit of noise.","u":"Comparing managers and estimating how long skill takes to show: roughly (2 ÷ information ratio)² years.","m":"An information ratio of 0.5 after fees is exceptional; at 0.1, even 20 years of results cannot separate skill from luck."},
{"t":"Inheritance tax","c":"Estate","l":3,"d":"A state tax paid by heirs on what they receive; only a few states levy it.","u":"State estate planning.","m":"Rates often depend on the heir's relationship to the deceased."},
{"t":"Inherited IRA","a":["10-year rule"],"c":"Estate","l":2,"d":"An IRA received from a deceased owner. Since 2020, most non-spouse beneficiaries must empty it within 10 years; certain eligible beneficiaries, such as spouses, have more flexible options.","u":"Planning withdrawals and taxes for heirs.","m":"Spreading withdrawals across the 10 years can avoid a large tax spike."},
{"t":"Initial Enrollment Period","a":["IEP"],"c":"Retirement","l":2,"mod":"INV-079","d":"Your first chance to sign up for Medicare: seven months, from three months before the month you turn 65 to three months after it.","u":"Enrolling in Parts A, B and D without penalties.","m":"If you are not already receiving Social Security you must sign up yourself; signing up before your birthday month avoids a gap."},
{"t":"Initial public offering","a":["IPO"],"c":"Markets","l":2,"mod":"INV-005","d":"A company's first sale of shares to the public.","u":"Companies raising capital and early owners selling.","m":"Individuals usually buy after the first-day jump; research has found average long-run underperformance."},
{"t":"Installment sale","a":["installment method"],"c":"Taxes","l":2,"mod":"INV-094","d":"A sale with at least one payment after the year of sale; under IRC 453 the seller recognizes gain as payments of principal arrive, in proportion to the gross profit ratio.","u":"Spreading the tax on selling a business or property to family, managers or other buyers who pay over time.","m":"The seller becomes the buyer's lender; interest is ordinary income and should be at least the applicable federal rate."},
{"t":"Interest","c":"Foundations","l":1,"d":"The payment a borrower makes to a lender for the use of money.","u":"Savings, bonds, loans.","m":"Interest you earn is usually taxed as ordinary income in taxable accounts."},
{"t":"Interest coverage","c":"Companies","l":3,"mod":"INV-006","d":"Operating income divided by interest expense.","u":"Judging ability to service debt.","m":"Coverage below about 2–3 times leaves little room if profits fall."},
{"t":"Interest-rate risk","c":"Asset classes","l":2,"mod":"INV-003","d":"The risk that bond prices fall when interest rates rise.","u":"Understanding bond volatility.","m":"In 2022, 10-year Treasuries fell 17.8% as rates rose."},
{"t":"Internet Crime Complaint Center","a":["IC3"],"c":"Advice & regulation","l":1,"mod":"INV-062","d":"The FBI's central site (ic3.gov) for reporting internet-enabled crime, including investment and cryptocurrency fraud, and the source of its annual Internet Crime Report.","u":"Reporting fraud so law enforcement can act and, sometimes, freeze funds.","m":"Report quickly: the FBI says its fund-recovery process works best when complaints are filed as quickly as possible."},
{"t":"Interval fund","c":"Vehicles","l":2,"mod":"INV-014","d":"A registered closed-end fund that, under SEC Rule 23c-3, offers to buy back 5% to 25% of its shares at net asset value at set intervals of three, six or twelve months.","u":"Giving ordinary investors access to less liquid assets such as private credit or real estate.","m":"You can get money out only at the scheduled windows, and if many investors ask at once, each may get only part of the request.","a":[]},
{"t":"Intestacy","c":"Estate","l":2,"d":"Dying without a valid will; state law then determines who inherits.","u":"Default inheritance rules.","m":"The result may not match your wishes, especially for unmarried partners and blended families."},
{"t":"Intrinsic value","c":"Valuation","l":2,"d":"An estimate of what an asset is worth based on the cash it will produce, independent of its current price.","u":"Value investing; comparing price with value.","m":"Estimates differ widely between analysts; margin of safety guards against error."},
{"t":"Inverted yield curve","c":"Asset classes","l":2,"mod":"INV-009","d":"A yield curve on which short-term yields are higher than long-term yields.","u":"Describing unusual rate conditions, often when investors expect short-term rates to fall.","m":"On July 3, 2023, a 6-month Treasury bill yielded 5.53% and a 10-year note 3.86%. Economists debate what inversions predict.","a":[]},
{"t":"Investing","c":"Foundations","l":1,"mod":"INV-001","d":"Committing money to assets expected to produce income or grow in value over time, accepting that prices will fluctuate.","u":"Long-term goals such as retirement or a child's education a decade away.","m":"Suits money you will not need for at least five years."},
{"t":"Investment Adviser Public Disclosure","a":["IAPD"],"c":"Advice & regulation","l":1,"mod":"INV-062","d":"The SEC's free public database of registered investment advisers and their representatives, including Form ADV filings and disciplinary history.","u":"Checking an adviser before you hire one; it links to FINRA BrokerCheck for brokers.","m":"Search the person and the firm, and read the disclosures, before sending money."},
{"t":"Investment adviser representative","a":["IAR"],"c":"Advice & regulation","l":2,"mod":"INV-103","d":"An individual who gives investment advice on behalf of a registered investment adviser firm.","u":"Identifying who, within an advisory firm, is responsible for your advice.","m":"Look the person up on the SEC's IAPD site; Form ADV Part 2B, the brochure supplement, describes their background and any disciplinary history."},
{"t":"Investment factor","a":["CMA","conservative minus aggressive"],"c":"Strategies","l":3,"mod":"INV-048","d":"The return of companies that invest conservatively minus those that invest aggressively; part of the Fama–French five-factor model.","u":"Completing the five-factor description of stock returns.","m":"Companies growing their assets fastest have tended to earn less. Many value and quality funds already tilt this way."},
{"t":"Investment grade","c":"Asset classes","l":2,"d":"Bonds rated BBB-/Baa3 or higher by the major agencies.","u":"Classifying lower-default-risk bonds.","m":"Most core bond funds hold mainly investment-grade debt."},
{"t":"Investment policy statement","a":["IPS"],"c":"Planning","l":2,"d":"A written document stating your goals, target allocation, rebalancing rules and what you will do in a crash.","u":"Keeping decisions consistent and calm.","m":"Writing the rules before a crisis is the best defense against panic."},
{"t":"Investment profile","c":"Advice & regulation","l":2,"mod":"INV-025","d":"The facts a broker must learn about a customer under FINRA's suitability rule: age, other investments, financial situation and needs, tax status, objectives, experience, time horizon, liquidity needs and risk tolerance.","u":"Matching recommendations to the customer.","m":"Keep it current with your broker, especially after retirement, a windfall or a change in health.","a":[]},
{"t":"Investor return","a":["dollar-weighted return"],"c":"Behavior","l":2,"mod":"INV-061","d":"The return earned by the average dollar invested in a fund, taking account of when money flowed in and out; a money-weighted return for all of a fund's investors together.","u":"Comparing what investors actually earned with the fund's reported total return.","m":"The difference between the two is the behavior gap."},
{"t":"Involuntary cash-out","a":["force-out","involuntary cashout"],"c":"Accounts","l":3,"mod":"INV-100","d":"A plan's distribution of a former employee's small balance without consent. SECURE 2.0 section 304 permits plans to set the limit at up to $7,000 (IRS Notice 2024-03).","u":"Clearing small accounts from a plan after employees leave.","m":"Balances above $1,000 generally go to an IRA opened in your name; choose where the money goes yourself."},
{"t":"IRMAA","a":["income-related monthly adjustment amount"],"c":"Retirement","l":3,"d":"Surcharges on Medicare Part B and Part D premiums for higher-income beneficiaries, based on income from two years earlier.","u":"Retirement tax and income planning.","m":"Large Roth conversions or asset sales at 63 can raise premiums at 65."},
{"t":"Irrevocable life insurance trust","a":["ILIT"],"c":"Estate","l":3,"mod":"INV-087","d":"An irrevocable trust that owns a life insurance policy and receives its proceeds, keeping them out of the insured person's gross estate.","u":"Keeping a large death benefit from being taxed in an estate above the exclusion, and controlling how the payout is used.","m":"If you transfer an existing policy and die within three years, the proceeds come back into your estate (26 U.S.C. 2035). For estates far below the exclusion, it rarely saves federal tax."},
{"t":"Irrevocable trust","c":"Estate","l":3,"d":"A trust that generally cannot be changed once created, removing assets from your control and often from your taxable estate.","u":"Estate tax and asset protection planning.","m":"A permanent decision; requires expert help."},
{"t":"Itemized deductions","c":"Taxes","l":2,"d":"Specific deductible expenses, such as mortgage interest, state and local taxes (subject to a cap) and charitable gifts, used instead of the standard deduction.","u":"Reducing taxable income when they exceed the standard deduction.","m":"Charitable strategies such as donor-advised funds interact with this choice."},
{"t":"J-curve","c":"Vehicles","l":3,"mod":"INV-014","d":"The typical pattern of a private equity fund's cumulative cash flows or returns: negative in the early years, as fees are paid and capital is invested, turning positive only later as investments are sold.","u":"Setting expectations for a new private fund's reported performance.","m":"Early returns of a private fund say little about its final result, and the money is committed for a decade or more.","a":[]},
{"t":"Joint account","c":"Accounts","l":1,"mod":"INV-027","d":"A bank or brokerage account owned by two or more people, each of whom can usually deposit and withdraw.","u":"Paying shared costs and saving for shared goals.","m":"Either owner can typically withdraw everything, and the title decides who owns it at a death.","a":[]},
{"t":"Joint tenancy with right of survivorship","a":["JTWROS"],"c":"Estate","l":2,"d":"A form of co-ownership in which the surviving owner automatically receives the property.","u":"Passing property between spouses outside probate.","m":"Adding a child as joint owner can create tax and control problems."},
{"t":"Key-person insurance","c":"Insurance","l":2,"mod":"INV-094","d":"Life or disability insurance a business owns on an owner or employee whose loss would hurt it, with the business as beneficiary.","u":"Covering lost profits, hiring a replacement or funding a buyout.","m":"For employer-owned policies, get written notice and consent before the policy is issued, or the tax-free treatment of proceeds is limited (IRC 101(j)).","a":[]},
{"t":"Kiddie tax","c":"Taxes","l":3,"d":"Rules taxing a child's unearned income above a threshold at the parents' marginal rate.","u":"Limiting income shifting to children.","m":"Affects custodial accounts with large investment income."},
{"t":"Landing point","a":["final allocation"],"c":"Retirement","l":2,"mod":"INV-050","d":"The final, most conservative stock-bond mix a target-date glide path reaches, and the point at which it stops changing.","u":"Comparing how conservative different target-date families become in retirement.","m":"In 2026 fund documents, Vanguard's and Fidelity's glide paths landed near 30% stocks and BlackRock's at 40%, reached at very different ages."},
{"t":"Landlord insurance","a":["dwelling policy","dwelling fire policy","rental property insurance"],"c":"Insurance","l":2,"mod":"INV-067","d":"Insurance for a property you rent to others, typically covering the building, your liability as owner and lost rent after a covered loss. A homeowners policy is written for a home you live in.","u":"Protecting a rental property and its owner.","m":"Tell your insurer before you rent out a home; a homeowners policy may not cover a rental, and tenants need their own renters insurance for their belongings."},
{"t":"Last-month rule","c":"Accounts","l":3,"mod":"INV-033","d":"An HSA rule that treats you as eligible for the whole year if you are eligible on December 1, allowing a full year's contribution, provided you stay eligible through the following year's testing period.","u":"Contributing the full limit after becoming eligible late in the year.","m":"Losing eligibility during the testing period makes the extra contribution taxable plus a 10% additional tax.","a":[]},
{"t":"Late enrollment penalty","c":"Retirement","l":2,"mod":"INV-079","d":"A permanent surcharge on Medicare premiums for enrolling late without qualifying coverage: 10% of the Part B standard premium per full 12 months, or 1% of the Part D national base premium ($38.99 in 2026) per month.","u":"Discouraging people from joining only when they get sick.","m":"For most people it lasts as long as they have the coverage; it is one of the most avoidable costs in retirement.","a":[]},
{"t":"Lean FIRE","c":"Independence","l":2,"mod":"INV-073","d":"Financial independence on a deliberately modest budget, which makes the FI number small and reachable quickly.","u":"Leaving full-time work as early as possible.","m":"A lean budget has little room to cut in a bad market, so it calls for a lower withdrawal rate or some part-time income.","a":[]},
{"t":"Legacy contact","a":["Inactive Account Manager"],"c":"Estate","l":1,"mod":"INV-059","d":"An online setting that names someone to access or receive some of your account data after death or long inactivity, such as Apple's Legacy Contact or Google's Inactive Account Manager.","u":"Giving a trusted person lawful access to digital accounts without sharing passwords.","m":"Because online tools rank first under the uniform digital-assets act, ten minutes setting these up can save your family months."},
{"t":"Letter of instruction","c":"Estate","l":1,"mod":"INV-059","d":"An informal, plain-language letter to your family or executor listing accounts, contacts, where documents and passwords are kept, and personal wishes. It is not a legal document and does not replace a will.","u":"Making your estate findable and your wishes clear.","m":"It is the cover page of your family financial file. Update it at each annual review.","a":[]},
{"t":"Letter of intent","c":"Estate","l":1,"mod":"INV-102","d":"A non-binding written guide from parents or caregivers describing a dependent's routines, health, people, preferences, benefits and wishes for future caregivers and trustees.","u":"Passing on knowledge that legal documents cannot capture.","m":"It costs nothing to write; review it every year.","a":[]},
{"t":"Letters testamentary","a":["letters of administration"],"c":"Estate","l":2,"mod":"INV-086","d":"The document issued by the probate court or register that appoints the personal representative and proves their authority. Letters of administration are issued when there is no will.","u":"Opening an estate account, closing the decedent's accounts, selling property and dealing with the IRS.","m":"An executor named in a will cannot act on the estate's assets until letters are granted."},
{"t":"Leverage","c":"Foundations","l":2,"mod":"INV-005","d":"Using borrowed money to increase the size of an investment.","u":"Mortgages, margin, some funds and businesses.","m":"Doubles gains and losses alike; turns temporary falls into permanent ones when it forces selling."},
{"t":"Liability","c":"Foundations","l":1,"d":"Money owed to others: mortgages, loans, credit card balances, unpaid bills.","u":"Measuring net worth and financial risk.","m":"Every liability has a cost (its interest rate) that competes with what your investments earn."},
{"t":"Liability coverage","a":["liability insurance"],"c":"Insurance","l":1,"mod":"INV-023","d":"Insurance that pays others for injury or damage you are legally responsible for, as part of auto, home, renter's or umbrella policies. Auto limits are written like 100/300/100 (per person, per accident, property damage, in thousands).","u":"Protecting savings and future earnings from lawsuits.","m":"State minimum limits are often far below what a serious accident costs; the more you own, the more you need."},
{"t":"Life expectancy","c":"Retirement","l":1,"mod":"INV-075","d":"The average number of years remaining for people of a given age, from a life table. In SSA's 2023 period table, 18.12 years for a man and 20.66 years for a woman at 65.","u":"A starting point for how long retirement may last.","m":"About half of people outlive it, so a plan that ends at life expectancy fails about half the time.","a":[]},
{"t":"Life-stage planning","c":"Planning","l":1,"d":"Adapting financial priorities to your age and circumstances: early career, family building, peak earning, pre-retirement and retirement.","u":"Prioritizing among competing goals.","m":"Priorities shift from building to protecting to spending."},
{"t":"Lifestyle inflation","a":["lifestyle creep"],"c":"Behavior","l":1,"mod":"INV-072","d":"The tendency for spending to rise as income rises, so raises are absorbed rather than saved.","u":"Explaining why higher income does not automatically shorten the path to financial independence.","m":"A raise that is fully spent leaves your savings rate, and so your FI timeline, unchanged. Decide in advance how much of each raise to save."},
{"t":"Lifetime learning credit","c":"Taxes","l":2,"mod":"INV-034","d":"A nonrefundable credit of 20% of up to $10,000 of qualified education expenses per return (at most $2,000), with no limit on the number of years, phased out between MAGI of $80,000 and $90,000 ($160,000–$180,000 joint).","u":"Graduate study, part-time courses and job skills.","m":"You cannot claim it and the American opportunity credit for the same student in the same year.","a":[]},
{"t":"Limit order","c":"Markets","l":1,"mod":"INV-005","d":"An order to buy at or below, or sell at or above, a specified price.","u":"Controlling price, especially in thin markets or large orders.","m":"Guarantees your price or better, but may never fill."},
{"t":"Limited partner","a":["LP"],"c":"Real estate","l":2,"mod":"INV-069","d":"A passive investor in a partnership with limited liability and no management control.","u":"Supplying most of the equity in a syndication.","m":"Limited partners generally cannot use the $25,000 rental loss allowance; losses are passive."},
{"t":"Limits to arbitrage","a":["arbitrage limits"],"c":"Markets","l":3,"mod":"INV-043","d":"The costs and risks, such as short-sale restrictions, borrowing fees and the chance a mispricing widens, that stop professionals from correcting every wrong price.","u":"Explaining how prices can be wrong without offering an easy profit.","m":"'The market is wrong' and 'I can profit from it' are different claims; the second is far harder."},
{"t":"Liquidity","c":"Markets","l":1,"mod":"INV-005","d":"How easily an asset can be sold quickly, in size, without moving its price.","u":"Judging trading cost and access to cash.","m":"Real estate and private investments can take weeks or months to sell."},
{"t":"Living will","c":"Estate","l":1,"mod":"INV-084","d":"A written advance directive stating which medical treatments you would want or refuse, and under what conditions, if you cannot make decisions yourself.","u":"Guiding your health care agent and doctors, especially about life-sustaining treatment near the end of life.","m":"It spares your family from guessing. It is not a medical order; a DNR or POLST form, signed by a clinician, is.","a":[]},
{"t":"Loan-level price adjustment","a":["LLPA"],"c":"Real estate","l":3,"mod":"INV-066","d":"A risk-based fee Fannie Mae and Freddie Mac charge lenders on loans with features such as investment-property occupancy, high LTV or lower credit scores. Lenders usually pass it on as a higher rate or upfront cost.","u":"Pricing conventional loans by risk.","m":"It is one reason an investment-property loan costs more than a loan on your own home."},
{"t":"Loan-to-value ratio","a":["LTV","LTV ratio"],"c":"Real estate","l":1,"mod":"INV-064","d":"The loan balance divided by the property's value or price. A $240,000 loan on a $300,000 home is an 80% LTV.","u":"Pricing loans, setting down-payment requirements, and deciding when mortgage insurance can end.","m":"Lower LTV means more equity, lower cost of borrowing and more cushion if prices fall."},
{"t":"Long-short portfolio","a":["long-short"],"c":"Strategies","l":3,"mod":"INV-048","d":"A portfolio that buys one group of securities and sells short another, so its return is the difference between them. Academic factors are built this way.","u":"Isolating a factor's premium from the market's movement.","m":"You cannot buy an academic factor directly; long-only funds capture part of it, at a cost."},
{"t":"Long-term capital gain","c":"Taxes","l":1,"d":"A gain on an asset held more than one year, taxed at federal rates of 0%, 15% or 20% depending on income.","u":"Tax-efficient investing.","m":"Some households in low-income years can realize gains at the 0% rate."},
{"t":"Long-term care insurance","a":["LTC insurance"],"c":"Insurance","l":2,"d":"Insurance covering extended care in a nursing home, assisted living or at home.","u":"Funding care costs that Medicare generally does not cover.","m":"Premiums rise with age; decisions are best made in your 50s or early 60s."},
{"t":"Long-term services and supports","a":["LTSS","long-term care"],"c":"Insurance","l":1,"mod":"INV-083","d":"Help over an extended period with daily personal tasks or supervision, provided at home, in adult day programs, in assisted living or in nursing homes; mostly not medical care.","u":"The care long-term care insurance and Medicaid pay for. ASPE projects that 56% of Americans turning 65 will have a significant need.","m":"Plan for the long tail: about one in five people will need care for more than five years."},
{"t":"Longevity risk","c":"Retirement","l":2,"mod":"INV-003","d":"The risk of living longer than your money lasts.","u":"Retirement planning.","m":"Plan for a long life, especially for the younger spouse; Social Security and income annuities hedge it."},
{"t":"Look-ahead bias","a":["hindsight bias (backtesting)"],"c":"Strategies","l":3,"mod":"INV-049","d":"The error of building or judging a strategy with information that would not have been available at the time decisions were made.","u":"Spotting backtests that look better than any real investor could have done.","m":"Ask whether the rule, its settings and its ingredients could have been chosen before the period it is tested on."},
{"t":"Lookback provision","a":["ESPP lookback","lookback"],"c":"Accounts","l":2,"mod":"INV-022","d":"An employee stock purchase plan feature that applies the discount to the lower of the share price at the start of the offering period or on the purchase date.","u":"Increasing the value of an ESPP when the share price rises during the period.","m":"With a 15% discount and a rising price, the gain on your money can be well above 17.6% for a six-month period."},
{"t":"Loss aversion","c":"Behavior","l":2,"d":"The tendency to feel losses more strongly than equal gains, documented in Kahneman and Tversky's prospect theory (1979).","u":"Explaining panic selling and excessive caution.","m":"Checking your portfolio less often reduces the pain and the urge to act."},
{"t":"Lottery cash option","a":["cash option"],"c":"Planning","l":2,"mod":"INV-099","d":"A lump sum paid now in place of an advertised jackpot's stream of yearly annuity payments; it is smaller than the advertised total.","u":"Choosing between money today and payments over decades, using present value.","m":"Compare the cash with the present value of the payments at a realistic discount rate, not with the advertised total."},
{"t":"Low-volatility anomaly","a":["low volatility","minimum volatility","low-beta anomaly"],"c":"Strategies","l":2,"mod":"INV-048","d":"The finding that stocks with low past volatility or beta have earned about as much as, or more than, high-volatility stocks, with less risk.","u":"Minimum-volatility and low-beta funds.","m":"These are still stock funds: they fall in crashes, usually less, and can lag badly in euphoric rallies such as 1999."},
{"t":"Lump-sum death payment","c":"Retirement","l":1,"mod":"INV-098","d":"A one-time $255 Social Security payment to a surviving spouse, or if there is none, to certain children, of a worker who died.","u":"Helping with immediate costs after a death.","m":"You must apply for it; it is separate from monthly survivor benefits.","a":[]},
{"t":"Lump-sum investing","c":"Strategies","l":2,"d":"Investing an available sum all at once rather than in stages.","u":"Deploying windfalls and inheritances.","m":"Because markets rise more often than they fall, lump sums usually end ahead of staged investing."},
{"t":"Lump-sum option","a":["pension lump sum"],"c":"Retirement","l":1,"mod":"INV-080","d":"A choice some defined benefit pension plans offer to take the whole value of your pension as one payment instead of monthly income.","u":"Deciding between guaranteed lifetime income and a pot of money you control; the plan must compute the minimum lump sum under IRC section 417(e).","m":"Compare the offer with the pension's value at safe interest rates. If you take it, use a direct rollover to an IRA to avoid immediate tax."},
{"t":"Macaulay duration","c":"Asset classes","l":3,"mod":"INV-009","d":"The present-value-weighted average time, in years, until a bond's cash flows are received.","u":"Measuring when, on average, a bond pays you back; matching bonds to a spending date.","m":"A zero-coupon bond's Macaulay duration equals its maturity; a five-year 4% bond at a 5% yield has one of 4.62 years.","a":[]},
{"t":"Management fee","a":["asset management fee"],"c":"Costs","l":2,"mod":"INV-014","d":"A yearly fee charged as a percentage of the assets (or commitments) in a fund, paid whether the fund gains or loses. The SEC notes hedge fund investors typically pay 1–2% of net asset value.","u":"Paying a fund manager's ongoing costs and salaries.","m":"A 2% fee on assets takes a fifth of a 10% gross return every year before any performance fee."},
{"t":"Mandatory 20% withholding","a":["20% withholding"],"c":"Taxes","l":2,"mod":"INV-059","d":"The federal income tax a workplace plan must withhold from an eligible rollover distribution paid to you rather than rolled over directly, even if you intend to roll it over.","u":"Collecting tax up front on plan payouts.","m":"A $10,000 payout arrives as $8,000. To roll over all of it you must add $2,000 from your own savings within 60 days."},
{"t":"Margin","a":["margin account","margin loan"],"c":"Markets","l":2,"mod":"INV-005","d":"Borrowing from a broker against the securities in your account. Regulation T generally limits borrowing to 50% of the purchase; FINRA requires equity of at least 25% of the account's value.","u":"Leveraged investing, short selling.","m":"Leverage magnifies losses and can force sales at the worst time."},
{"t":"Margin call","c":"Markets","l":2,"mod":"INV-005","d":"A demand from a broker to add cash or securities when equity in a margin account falls below the maintenance requirement.","u":"Enforcing margin rules.","m":"If you do not meet it, the broker may sell your positions without asking."},
{"t":"Margin of safety","a":[],"c":"Valuation","l":1,"mod":"INV-046","d":"Benjamin Graham's principle of paying well below your estimate of a business's value, so that errors or bad luck do not turn into losses.","u":"Protecting against mistakes in valuation.","m":"Useful beyond stocks: build room for being wrong into any plan, including retirement return assumptions."},
{"t":"Marginal tax rate","c":"Taxes","l":1,"d":"The tax rate applied to your next dollar of income.","u":"Evaluating deductions, Roth versus traditional, and extra income.","m":"Moving into a higher bracket taxes only the income above the threshold at the higher rate."},
{"t":"Marital deduction","a":["unlimited marital deduction"],"c":"Estate","l":2,"mod":"INV-088","d":"A deduction for the value of property passing from a decedent to a surviving spouse who is a US citizen, with no dollar limit (26 U.S.C. 2056). Gifts to a US-citizen spouse are similarly untaxed.","u":"Letting married couples defer all federal estate tax until the second death.","m":"It defers tax rather than eliminating it. For a spouse who is not a US citizen, a qualified domestic trust is generally needed."},
{"t":"Market anomaly","a":["anomaly","anomalies"],"c":"Strategies","l":2,"mod":"INV-043","d":"A pattern in returns that the standard model of risk and return does not predict, such as value stocks or recent winners earning more than their measured risk implies.","u":"Challenging market efficiency and building factor strategies.","m":"Anomalies may reflect hidden risks, often shrink after they are published, and can vanish for a decade."},
{"t":"Market capitalization","a":["market cap"],"c":"Markets","l":1,"mod":"INV-006","d":"The total market value of a company's shares: share price × shares outstanding.","u":"Measuring company size; weighting index funds.","m":"Compare companies by market cap, not share price."},
{"t":"Market maker","a":["wholesaler"],"c":"Markets","l":3,"mod":"INV-005","d":"A firm that continuously quotes prices to buy and sell a security, profiting from the spread.","u":"Providing liquidity; filling many retail orders.","m":"Often provides small price improvement on retail orders."},
{"t":"Market order","c":"Markets","l":1,"mod":"INV-005","d":"An order to buy or sell immediately at the best available price.","u":"Fast execution in liquid securities.","m":"Guarantees a fill, not a price."},
{"t":"Market timing","c":"Strategies","l":1,"d":"Moving money in and out of markets based on predictions of short-term moves.","u":"Attempting to avoid declines.","m":"Requires being right twice, about when to leave and when to return; rarely done well."},
{"t":"Marriage penalty","a":["marriage bonus","marriage tax penalty"],"c":"Taxes","l":1,"mod":"INV-095","d":"Extra tax a couple pays because they are married, compared with what the same two people would owe filing as unmarried individuals. A marriage bonus is the reverse.","u":"Understanding how a wedding, divorce or remarriage changes a household's tax without any change in income.","m":"For 2026, one-earner couples usually get a bonus and equal earners break even; penalties appear at very high incomes, for single parents who lose head-of-household status, and for many retirees."},
{"t":"Married filing jointly","a":["MFJ","joint return"],"c":"Taxes","l":1,"mod":"INV-095","d":"The filing status in which a married couple reports their combined income and deductions on one return. Both spouses are liable for the full tax.","u":"The status most married couples use; also available to a surviving spouse for the year the other spouse died.","m":"For 2026, the joint brackets are twice the single brackets up to the 35% bracket, and the joint standard deduction is $32,200."},
{"t":"Married filing separately","a":["MFS"],"c":"Taxes","l":2,"mod":"INV-095","d":"The filing status in which each spouse reports their own income and deductions. In community property states, each spouse generally reports half of community income.","u":"Keeping tax liability separate, or in special cases such as large income-based deductions.","m":"It usually costs more than a joint return, and several credits and deductions are reduced or unavailable."},
{"t":"Material participation","c":"Taxes","l":3,"mod":"INV-068","d":"Involvement in an activity on a regular, continuous and substantial basis, shown by meeting one of seven IRS tests, such as more than 500 hours a year, or more than 100 hours and at least as much as anyone else.","u":"Deciding whether a business activity, including a short-term rental with an average stay of 7 days or less, is passive.","m":"Keep a dated log of hours and tasks; claims without records are hard to defend.","a":[]},
{"t":"Maturity","c":"Asset classes","l":1,"d":"The date on which a bond's principal is repaid.","u":"Matching bonds to future spending dates.","m":"Longer maturities carry more interest-rate risk."},
{"t":"Maximum sustainable withdrawal rate","a":["maximum sustainable rate"],"c":"Retirement","l":3,"mod":"INV-076","d":"For a given starting year and horizon, the highest first-year fixed real withdrawal rate that would have lasted the whole period. Across 1928–1996 starts, a 60/40 portfolio's 30-year value ranged from about 3.7% (1966) to over 10% (1982) in this course's data.","u":"Showing how much the safe rate depended on the year of retirement.","m":"The famous 4% is roughly the worst historical case, which is why most historical retirees who used it ended with money to spare."},
{"t":"Mean","a":["average"],"c":"Foundations","l":1,"mod":"INV-026","d":"The ordinary average: the total divided by the number of values.","u":"Summarizing totals, such as total family wealth divided by the number of families.","m":"In 2022 mean family net worth was about 5.5 times the median, because the wealthiest families pull the mean up."},
{"t":"Median","c":"Foundations","l":1,"mod":"INV-026","d":"The middle value of a set: half the values are above it and half below.","u":"Describing a typical value when a few very large values would distort the average.","m":"For net worth, income and home prices, the median describes a typical household far better than the mean.","a":[]},
{"t":"Medicaid","c":"Retirement","l":1,"mod":"INV-097","d":"A joint federal-state program that pays for health care for people with limited income and assets, including long-term nursing home care, which Medicare does not cover.","u":"Paying for long-term care after a person's own resources are largely spent.","m":"Rules vary by state. Gifts in the five years before applying can delay coverage, and states seek repayment from estates of recipients who were 55 or older.","a":[]},
{"t":"Medicaid estate recovery","a":["estate recovery"],"c":"Estate","l":3,"mod":"INV-083","d":"The requirement that states seek repayment from the estates of people who received Medicaid long-term care services at 55 or older (Social Security Act §1917(b)).","u":"Recovering public costs, often from the value of a home, after the recipient's death.","m":"Recovery waits until a surviving spouse has died and there is no surviving child under 21 or blind or disabled child. Plan with an elder-law attorney."},
{"t":"Medicaid expansion","c":"Insurance","l":2,"mod":"INV-074","d":"The option for states to extend Medicaid to most adults with income up to 138% of the federal poverty line.","u":"Coverage for people with very low income, including some early retirees who live mainly on assets.","m":"In expansion states, adults below about 138% generally qualify for Medicaid rather than marketplace credits; in non-expansion states, people below 100% can fall into a coverage gap.","a":[]},
{"t":"Medicaid look-back period","a":["look-back period","five-year look-back"],"c":"Estate","l":2,"mod":"INV-083","d":"The 60 months before a Medicaid long-term care application during which transfers of assets for less than fair value trigger a penalty period (Social Security Act §1917(c)).","u":"Preventing people from giving assets away just before applying. The penalty equals the value transferred divided by the state's average monthly private nursing-home cost.","m":"Gifts meant to protect assets must be made more than five years before any application, and they have tax and control consequences."},
{"t":"Medicaid payback","a":["Medicaid reimbursement provision"],"c":"Estate","l":3,"mod":"INV-102","d":"The requirement that a first-party or pooled special needs trust, and an ABLE account after its owner's death, repay the state for Medicaid benefits provided, from what remains.","u":"The price of the benefit exclusions for the person's own assets.","m":"A third-party trust funded by family avoids it; that is why planning ahead matters."},
{"t":"Medicare","c":"Retirement","l":1,"d":"Federal health insurance for people 65 and older and some younger people with disabilities: Part A (hospital), Part B (medical), Part D (drugs), and Part C (Medicare Advantage).","u":"Retiree health coverage.","m":"Missing your enrollment window can mean lifelong late-enrollment penalties."},
{"t":"Medicare Advantage","a":["Part C"],"c":"Retirement","l":2,"d":"Private plans that replace Original Medicare, often with networks and extra benefits.","u":"An alternative to Original Medicare plus Medigap.","m":"Compare networks, out-of-pocket maximums and drug coverage each year."},
{"t":"Medicare Part A","a":["Part A","hospital insurance"],"c":"Retirement","l":1,"mod":"INV-079","d":"Medicare's hospital insurance: inpatient hospital, skilled nursing facility, hospice and some home health care. Premium-free for about 99% of beneficiaries; the 2026 inpatient deductible is $1,736 per benefit period.","u":"Paying hospital bills after 65.","m":"Premium-free is not cost-free; the deductible can apply more than once a year."},
{"t":"Medicare Part B","a":["Part B","medical insurance"],"c":"Retirement","l":1,"mod":"INV-079","d":"Medicare's medical insurance for doctors, outpatient care, equipment and preventive services. In 2026 the standard premium is $202.90 a month and the deductible $283, then usually 20% coinsurance.","u":"Most day-to-day medical care in retirement.","m":"Enroll on time: a late penalty adds 10% of the standard premium for each full year you delayed, usually for life."},
{"t":"Medicare Part D","a":["Part D","Medicare drug coverage"],"c":"Retirement","l":1,"mod":"INV-079","d":"Prescription drug coverage from private plans under Medicare rules. In 2026 the maximum deductible is $615 and out-of-pocket costs for covered drugs are capped at $2,100 a year.","u":"Outpatient prescription drugs, alongside Original Medicare or inside most Medicare Advantage plans.","m":"Join when first eligible unless you have creditable coverage; the late penalty is 1% of the national base premium for each month without it."},
{"t":"Medicare Special Enrollment Period","a":["Part B Special Enrollment Period"],"c":"Retirement","l":2,"mod":"INV-079","d":"A window outside the usual periods to join Medicare or change plans. For Part B, people covered by a group plan through their own or a spouse's current job can sign up any time while covered or within 8 months after the job or coverage ends.","u":"Delaying Part B without penalty while still working.","m":"COBRA and retiree coverage do not count as current job-based coverage."},
{"t":"Medigap","a":["Medicare Supplement"],"c":"Retirement","l":2,"d":"Private insurance that helps pay costs Original Medicare does not, such as coinsurance and deductibles.","u":"Predictable out-of-pocket costs with Original Medicare.","m":"Guaranteed-issue rights are strongest when you first enroll."},
{"t":"Medigap Open Enrollment Period","c":"Retirement","l":2,"mod":"INV-079","d":"A one-time six-month period, starting the first month you have Medicare Part B and are 65 or older, when insurers must sell you any Medigap policy they offer without medical underwriting.","u":"Buying a Medigap policy at standard rates regardless of health.","m":"It does not repeat; switching from Medicare Advantage back to Medigap later may be refused or cost more in most states.","a":[]},
{"t":"Mega backdoor Roth","c":"Taxes","l":3,"d":"Making after-tax (non-Roth) contributions to a 401(k), where the plan allows, and converting them to Roth.","u":"Large Roth contributions for high savers.","m":"Only possible if your plan permits after-tax contributions and in-plan conversions or withdrawals."},
{"t":"Mental accounting","c":"Behavior","l":3,"d":"Treating money differently depending on its source or label, a concept developed by Richard Thaler.","u":"Explaining inconsistent financial choices.","m":"A dollar is a dollar; high-interest debt next to idle savings is a common symptom."},
{"t":"Microcap stock","a":["penny stock"],"c":"Markets","l":2,"mod":"INV-062","d":"Shares of a very small company, often thinly traded and with limited public information; very low-priced microcaps are called penny stocks.","u":"Identifying the part of the market most used in pump-and-dump schemes.","m":"Little information and little trading make these easy to manipulate."},
{"t":"Mid-month convention","c":"Taxes","l":3,"mod":"INV-068","d":"The rule that treats residential and nonresidential real property as placed in service, or disposed of, in the middle of the month.","u":"Figuring first-year and final-year depreciation on buildings.","m":"A rental first available in July gets 5.5 months of depreciation in year one: 1.667% of the building's basis.","a":[]},
{"t":"Mill levy","a":["millage","mill rate","mills"],"c":"Real estate","l":2,"mod":"INV-068","d":"A property tax rate expressed in mills, where one mill is one-tenth of a cent: $1 of tax per $1,000 of assessed value.","u":"Converting assessed value into a tax bill.","m":"At 70 mills, a $40,000 assessed value produces a $2,800 tax bill."},
{"t":"Minimum tax credit","a":["AMT credit"],"c":"Taxes","l":3,"mod":"INV-040","d":"A credit for alternative minimum tax paid on timing items, such as an ISO exercise, usable in later years when regular tax exceeds the tentative minimum tax.","u":"Recovering AMT over time.","m":"Recovery can be slow; size ISO exercises to an AMT you can afford."},
{"t":"Missed RMD excise tax","a":["RMD penalty","correction window"],"c":"Taxes","l":2,"mod":"INV-081","d":"A tax of 25% of the amount by which a withdrawal falls short of the RMD, reduced to 10% if corrected within the correction window (26 U.S.C. §4974). It was 50% before SECURE 2.0.","u":"Enforcing required minimum distributions; reported on Form 5329.","m":"Take the missed amount as soon as you notice, file Form 5329, and request a waiver if the error was reasonable."},
{"t":"Modern portfolio theory","a":["MPT"],"c":"Portfolio","l":3,"mod":"INV-004","d":"Harry Markowitz's 1952 framework for choosing portfolios by expected return, volatility and correlation.","u":"Asset allocation and optimization.","m":"Its core insight — combine imperfectly correlated assets — is durable even where its assumptions are not."},
{"t":"Modified Accelerated Cost Recovery System","a":["MACRS"],"c":"Taxes","l":2,"mod":"INV-068","d":"The federal system that sets how business and rental property is depreciated: which recovery period applies to each kind of property, and which method and convention to use.","u":"Figuring yearly depreciation on rental buildings (27.5 or 39 years) and their contents (5, 7 or 15 years).","m":"Nearly every rental placed in service since 1987 is depreciated under MACRS; IRS Publication 946 has its tables."},
{"t":"Modified adjusted gross income","a":["MAGI"],"c":"Taxes","l":3,"d":"AGI with certain items added back; the definition varies by purpose.","u":"Roth IRA eligibility, Medicare IRMAA, net investment income tax and more.","m":"Always check which MAGI definition a rule uses."},
{"t":"Modified duration","c":"Asset classes","l":3,"mod":"INV-009","d":"Macaulay duration divided by (1 + yield per period): the approximate percentage change in a bond's price for a one-percentage-point change in yield.","u":"Estimating how much a bond or bond fund will fall if rates rise.","m":"Fund fact sheets usually report this as 'duration.' A duration of 6 means roughly a 6% loss for a one-point rise in yields.","a":[]},
{"t":"Modified endowment contract","a":["MEC","7-pay test"],"c":"Insurance","l":3,"mod":"INV-017","d":"A life insurance policy funded faster than the '7-pay test' in section 7702A allows. Loans and withdrawals are then taxed as income first, and taxable amounts can face a 10% additional tax (section 72(v)).","u":"Limiting the use of life insurance as a tax shelter for large single premiums.","m":"Overfunding a policy for its tax benefits can backfire; ask the insurer whether a premium would make the policy a MEC."},
{"t":"Momentum","c":"Strategies","l":3,"d":"The tendency for securities that have risen recently to keep rising for a period, and for losers to keep falling.","u":"A widely studied factor.","m":"High turnover and sharp reversals make it costly to capture."},
{"t":"Money market deposit account","a":["MMDA"],"c":"Accounts","l":1,"mod":"INV-008","d":"A bank or credit union savings account, often with check-writing and a higher minimum balance. It is a deposit, not a fund.","u":"Liquid savings with deposit insurance.","m":"Insured by the FDIC or NCUA, unlike a money market fund. The FDIC's national average was 0.63% in September 2026, far below Treasury bill yields."},
{"t":"Money market fund","c":"Asset classes","l":1,"d":"A mutual fund that invests in very short-term, high-quality debt and aims to keep a stable $1 share price.","u":"Holding cash in brokerage accounts; short-term savings.","m":"Not FDIC-insured, but historically very stable; often pays more than a bank sweep."},
{"t":"Money-weighted return","a":["internal rate of return","IRR"],"c":"Portfolio","l":3,"d":"A return measure that reflects the timing and size of your deposits and withdrawals.","u":"Measuring your personal investing results.","m":"If you bought high and sold low, this will be lower than the fund's reported return."},
{"t":"Monte Carlo simulation","c":"Retirement","l":3,"d":"Running thousands of randomized return paths to estimate the range of outcomes for a plan.","u":"Estimating a plan's probability of success.","m":"Results depend entirely on the assumptions fed in."},
{"t":"Mortality and expense risk charge","a":["M&E charge","M&E fee"],"c":"Insurance","l":3,"mod":"INV-017","d":"A yearly charge in a variable annuity that pays the insurer for the insurance guarantees and its costs and profit. The SEC says it is typically about 1.25% of the account value a year.","u":"The largest single fee in most variable annuities, on top of fund expenses and optional rider fees.","m":"Add it to the underlying funds' expense ratios and any rider fees to see the true yearly cost, which compounds against you."},
{"t":"Mortality credits","a":["mortality pooling"],"c":"Insurance","l":3,"mod":"INV-017","d":"The extra income an annuity pool can pay because the premiums of members who die early stay in the pool to support those who live longer.","u":"Explaining why a lifetime annuity can pay more each year than a bond portfolio could safely pay a single person.","m":"The benefit grows with age; the price is giving up the lump sum and, usually, anything for heirs."},
{"t":"Mortgage","c":"Real estate","l":1,"d":"A loan secured by real estate, repaid over a set term.","u":"Buying property.","m":"Compare the rate, points, closing costs and total interest, not just the payment."},
{"t":"Mortgage points","a":["discount points"],"c":"Real estate","l":3,"d":"Upfront fees paid to reduce a mortgage's interest rate; one point is 1% of the loan.","u":"Trading cash now for a lower rate.","m":"Worth it only if you keep the loan past the break-even point."},
{"t":"Mortgage-backed security","a":["MBS","agency MBS"],"c":"Asset classes","l":2,"mod":"INV-010","d":"A bond backed by a pool of home mortgages whose payments pass through to investors. Agency MBS are issued or guaranteed by Ginnie Mae, Fannie Mae or Freddie Mac.","u":"A large part of the investment-grade bond market and of total bond market index funds.","m":"Credit risk is low; the main risk is prepayment. Homeowners refinance when rates fall, so you get money back when reinvesting it is least attractive."},
{"t":"Moving average","a":["simple moving average","SMA"],"c":"Markets","l":2,"mod":"INV-052","d":"The average of the last N prices of an asset, recalculated every period, such as the 10-month or 200-day moving average.","u":"Smoothing price data and generating trend-following signals.","m":"A price crossing its moving average is a description of the past, not a forecast."},
{"t":"Mr. Market","a":[],"c":"Behavior","l":1,"mod":"INV-046","d":"Graham's parable of a moody business partner who offers every day to buy or sell at prices driven by his emotions; you may ignore him or take advantage of him.","u":"Reframing market swings as offers rather than instructions.","m":"A falling price tells you about the market's mood, not necessarily about the business."},
{"t":"MSCI ACWI","a":["All Country World Index","ACWI"],"c":"Markets","l":2,"mod":"INV-054","d":"A global stock index covering large and mid-sized companies in 23 developed and 24 emerging markets (2,458 companies in August 2026).","u":"Measuring global stock performance and benchmarking global funds.","m":"Its country weights are the reference point for judging how tilted toward home your portfolio is."},
{"t":"Multi-factor authentication","a":["MFA","two-factor authentication","2FA"],"c":"Accounts","l":1,"mod":"INV-104","d":"Logging in with two or more different kinds of proof: something you know (a password), something you have (a phone, authenticator app or security key) or something you are (a fingerprint or face).","u":"Protecting financial accounts even if a password is stolen.","m":"FINRA says it can significantly reduce the chance of an account takeover. Prefer an app or key to text codes where your firm offers one."},
{"t":"Multiple support agreement","a":["Form 2120"],"c":"Taxes","l":3,"mod":"INV-097","d":"A written declaration that lets one of several people who together provide more than half of a relative's support claim the relative as a dependent, if that person provided over 10% and the others who provided over 10% agree not to claim.","u":"Siblings sharing the cost of supporting a parent.","m":"Rotate who claims the parent each year if that is fair, and keep records of each sibling's contributions."},
{"t":"Municipal bond","a":["muni"],"c":"Asset classes","l":2,"d":"A bond issued by a state or local government, whose interest is often exempt from federal income tax.","u":"Tax-efficient income for higher-bracket investors.","m":"Compare on a tax-equivalent yield basis; usually not suited to tax-deferred accounts."},
{"t":"Mutual fund","c":"Vehicles","l":1,"d":"A pooled investment that buys a portfolio of securities, priced once a day at net asset value.","u":"Diversified investing in one purchase.","m":"Compare expense ratios, loads and tax efficiency."},
{"t":"Myopic loss aversion","c":"Behavior","l":3,"mod":"INV-060","d":"Loss aversion made worse by evaluating an investment too often, so that normal short-term dips are felt as frequent losses.","u":"Explaining why frequent checking leads to more conservative, and more anxious, investing.","m":"Checking less often does not change your investments, only how often they appear to be losing.","a":[]},
{"t":"Names Rule","a":["Rule 35d-1","fund names rule"],"c":"Advice & regulation","l":3,"mod":"INV-053","d":"The SEC rule under the Investment Company Act that requires a fund whose name suggests a particular focus to invest at least 80% of its assets accordingly; 2023 amendments extended it to names suggesting characteristics such as ESG.","u":"Keeping fund names from misleading investors.","m":"An ESG-named fund must define its terms and follow them; the definition may not match yours."},
{"t":"Nasdaq Composite","c":"Markets","l":2,"mod":"INV-006","d":"An index of the stocks listed on the Nasdaq exchange, heavily weighted toward technology.","u":"Tracking technology-heavy markets.","m":"Fell about 78% from March 2000 to October 2002 and took until 2015 to regain its peak."},
{"t":"NCUA share insurance","a":["NCUA","National Credit Union Administration"],"c":"Accounts","l":1,"mod":"INV-008","d":"Federal insurance of credit union accounts by the National Credit Union Administration's Share Insurance Fund, backed by the full faith and credit of the United States: $250,000 per share owner, per insured credit union, per ownership category.","u":"Protecting credit union savings if the credit union fails.","m":"Works like FDIC insurance. NCUA notes that a few state-chartered credit unions use private insurers, which are not backed by the US government; NCUA's credit union locator shows which are federally insured."},
{"t":"Needs analysis","a":["needs method"],"c":"Insurance","l":2,"mod":"INV-023","d":"A way to size life insurance: the present value of the family's yearly shortfall after other income, plus debts, education and final expenses, minus savings and existing coverage.","u":"Choosing a coverage amount that reflects both needs and existing resources.","m":"More complete than a multiple-of-income rule of thumb; rerun it when your family, debts or savings change."},
{"t":"Needs, wants and wishes","c":"Planning","l":1,"mod":"INV-024","d":"A way of ranking goals: needs change your life if missed, wants matter but are flexible in amount or date, wishes are optional.","u":"Deciding which goals get funded first when the budget cannot cover everything.","m":"Fund needs first and most cautiously; let wishes wait for surplus money.","a":[]},
{"t":"Negative equity","a":["underwater","upside down"],"c":"Real estate","l":1,"mod":"INV-066","d":"Owing more on a property than it is worth.","u":"Describing borrowers after a price decline, especially 2007–2012.","m":"You cannot sell without bringing cash to closing or negotiating with the lender, and you cannot refinance normally."},
{"t":"Net asset value","a":["NAV"],"c":"Vehicles","l":2,"mod":"INV-005","d":"A fund's assets minus liabilities, divided by shares outstanding, calculated at each day's close.","u":"The price at which mutual fund shares are bought and sold.","m":"Orders placed before the cut-off get that day's closing NAV."},
{"t":"Net earnings from self-employment","c":"Taxes","l":3,"mod":"INV-101","d":"Net profit from self-employment multiplied by 92.35%, the base on which self-employment tax is figured on Schedule SE.","u":"Computing SE tax and the income SSA credits to your earnings record.","m":"On $90,000 of profit, net earnings are $83,115.","a":[]},
{"t":"Net income","a":["earnings","profit","bottom line"],"c":"Companies","l":1,"mod":"INV-006","d":"Revenue minus all expenses, interest and taxes: the profit belonging to shareholders.","u":"Computing earnings per share and P/E.","m":"Watch for one-time items that inflate or depress a single year."},
{"t":"Net investment income tax","a":["NIIT"],"c":"Taxes","l":3,"d":"A 3.8% federal tax on investment income for taxpayers above fixed income thresholds.","u":"Additional tax on higher earners' investment income.","m":"The thresholds are not indexed for inflation, so more households cross them over time."},
{"t":"Net margin","c":"Companies","l":2,"mod":"INV-006","d":"Net income as a percentage of revenue.","u":"Overall profitability.","m":"Low-margin businesses are more vulnerable to rising costs."},
{"t":"Net operating income","a":["NOI"],"c":"Real estate","l":2,"d":"A property's rental income minus operating expenses, before mortgage payments and income taxes.","u":"Valuing income property.","m":"Include vacancy, repairs, management, insurance and property tax, not just the mortgage."},
{"t":"Net price","a":["net price calculator"],"c":"Planning","l":1,"mod":"INV-096","d":"What a student actually pays for college after grants and scholarships, which do not have to be repaid. Colleges that take part in federal aid must post a net price calculator.","u":"Comparing colleges on real cost rather than sticker price.","m":"In 2025-26 the average first-year net tuition, fees, housing and food was about $16,200 at public four-year colleges versus a $25,850 sticker price."},
{"t":"Net worth","c":"Foundations","l":1,"d":"Total assets minus total liabilities.","u":"Tracking overall financial progress.","m":"Tracking it once or twice a year shows progress better than any single account balance."},
{"t":"Net-of-fee return","a":["net performance","net return"],"c":"Costs","l":2,"mod":"INV-057","d":"Investment performance after deducting all fees, including advisory fees.","u":"The fair basis for judging an advisor or fund against a benchmark.","m":"The SEC's marketing rule bars registered advisers from advertising gross performance unless net performance is shown with at least equal prominence."},
{"t":"Nominal return","c":"Foundations","l":1,"mod":"INV-001","d":"The percentage change in the dollar value of an investment, before adjusting for inflation.","u":"The return figure most statements and advertisements quote.","m":"Always ask whether a return is nominal or real; over decades the difference is enormous."},
{"t":"Non-GAAP earnings","a":["adjusted earnings"],"c":"Companies","l":3,"mod":"INV-006","d":"Company-defined profit measures that exclude certain items, such as restructuring costs or stock-based pay.","u":"Highlighting underlying performance.","m":"Be skeptical when 'one-time' charges recur every year."},
{"t":"Non-itemizer charitable deduction","c":"Taxes","l":1,"mod":"INV-039","d":"From 2026, a deduction of up to $1,000 ($2,000 joint) of cash gifts to charity for people who take the standard deduction (P.L. 119-21).","u":"Getting some tax benefit from giving without itemizing.","m":"Gifts to donor-advised funds and supporting organizations do not qualify.","a":[]},
{"t":"Non-qualified stock option","a":["NSO","NQSO"],"c":"Taxes","l":3,"d":"A stock option whose spread at exercise is taxed as ordinary income.","u":"Common equity pay.","m":"Plan exercises across tax years to manage brackets."},
{"t":"Non-traded REIT","a":["non-traded real estate investment trust","public non-listed REIT"],"c":"Real estate","l":2,"mod":"INV-014","d":"A real estate investment trust registered with the SEC but not listed on a stock exchange, so its shares cannot readily be sold.","u":"Selling real estate exposure through brokers, often with high advertised distributions.","m":"The SEC warns of limited redemption programs, up-front fees that can reach 15% of the offering price, and distributions that may be paid from your own money or borrowings."},
{"t":"Nondeductible IRA contribution","c":"Accounts","l":2,"mod":"INV-032","d":"A traditional IRA contribution you do not deduct, which becomes after-tax basis reported on Form 8606 and comes out tax-free later.","u":"The first step of a backdoor Roth, or IRA saving above the deduction limits.","m":"Keep every Form 8606, or you may pay tax twice on the same money.","a":[]},
{"t":"Nonqualified deferred compensation","a":["NQDC","deferred compensation plan","deferred comp"],"c":"Accounts","l":3,"mod":"INV-022","d":"An arrangement, usually for higher earners, to receive part of this year's pay in a later year, postponing income tax until it is paid. Governed by Internal Revenue Code Section 409A.","u":"Shifting income from high-tax working years into later years, beyond 401(k) limits.","m":"In an unfunded plan you are a general unsecured creditor of your employer; size it to what you could afford to lose."},
{"t":"Nonresidential real property","c":"Real estate","l":2,"mod":"INV-068","d":"Commercial real estate such as offices, stores and warehouses, depreciated straight-line over 39 years under the general depreciation system.","u":"Classifying non-residential buildings, including a home office in a personal residence.","m":"It recovers its cost much more slowly than an apartment building: $12,308 a year on $480,000 versus $17,455.","a":[]},
{"t":"Nontransferable asset","a":["nontransferable"],"c":"Markets","l":3,"mod":"INV-104","d":"A holding that cannot move through a normal account transfer, such as a firm's proprietary fund that the new firm cannot hold. Under FINRA Rule 11870 the old firm must offer choices: liquidation (disclosing any fees), keeping it at the old firm, or transferring it directly into the customer's name.","u":"Handling the leftovers of an account transfer.","m":"Before opening an account, check whether its default funds could move with you later."},
{"t":"Older Workers Benefit Protection Act","a":["OWBPA"],"c":"Advice & regulation","l":3,"mod":"INV-100","d":"A 1990 amendment to the Age Discrimination in Employment Act requiring that waivers of age-discrimination claims be knowing and voluntary, including at least 21 days to consider (45 in a group layoff) and 7 days to revoke (EEOC).","u":"Protecting workers 40 and older asked to sign a release for severance.","m":"A same-day signing deadline does not meet the rules for a valid age waiver."},
{"t":"One percent rule","a":["1% rule"],"c":"Real estate","l":3,"d":"A rough screen that monthly rent should be at least 1% of a property's purchase price.","u":"Quickly filtering rental candidates.","m":"A screen, not an analysis; it ignores expenses, taxes and local conditions."},
{"t":"One-rollover-per-year rule","c":"Accounts","l":2,"mod":"INV-059","d":"Since 2015, only one IRA-to-IRA rollover is allowed in any 12-month period, counting all of a person's IRAs together (IRS Announcements 2014-15 and 2014-32, following Bobrow v. Commissioner). It does not apply to trustee-to-trustee transfers, Roth conversions, or rollovers to or from workplace plans.","u":"Limiting repeated use of IRA money as a short-term loan.","m":"A second IRA-to-IRA rollover within a year is taxable. Use transfers instead of checks.","a":[]},
{"t":"Open enrollment","c":"Planning","l":1,"mod":"INV-022","d":"The yearly window when employees can choose or change health plans, flexible spending accounts, insurance and other benefits for the coming year.","u":"Re-choosing benefits as your life and the plans change.","m":"Outside it, most elections can change only after a qualifying life event. Do not let last year's choices roll over unexamined.","a":[]},
{"t":"Operating expenses","a":["opex"],"c":"Real estate","l":2,"mod":"INV-065","d":"The ongoing costs of running a rental: property tax, insurance, repairs, maintenance, management, utilities the owner pays, HOA dues and reserves. Loan payments, depreciation and income taxes are not operating expenses.","u":"Calculating net operating income.","m":"New investors most often underestimate this line. List every item for the specific property instead of using a rule of thumb."},
{"t":"Operating margin","c":"Companies","l":2,"mod":"INV-006","d":"Operating income as a percentage of revenue.","u":"Judging the profitability of the core business.","m":"Compare within an industry; margins vary enormously across industries."},
{"t":"Opportunity cost","c":"Foundations","l":1,"mod":"INV-051","d":"What you give up by choosing one option over the next best one; for money held in cash, the extra return the invested alternative would probably have earned.","u":"Measuring the price of waiting, holding too much cash, or any choice with an alternative.","m":"Cash that feels safe is not free; its cost is return you never see.","a":[]},
{"t":"Option","a":["call option","put option"],"c":"Asset classes","l":3,"d":"A contract giving the right, but not the obligation, to buy (call) or sell (put) an asset at a set price by a set date.","u":"Hedging, income strategies and speculation.","m":"Options can expire worthless; many short-term strategies lose money for individual traders."},
{"t":"Option premium","a":["premium (option)"],"c":"Asset classes","l":2,"mod":"INV-016","d":"The price an option buyer pays the option writer (seller) for the contract, quoted per share; a standard equity option covers 100 shares.","u":"The buyer's maximum loss and the writer's maximum gain on a simple option.","m":"A $2 premium costs $200 per contract. It is spent whether or not the option ever pays off."},
{"t":"Order routing report","a":["Rule 606 report"],"c":"Markets","l":3,"mod":"INV-104","d":"A quarterly public report, required by SEC Rule 606 of Regulation NMS, showing where a broker routes customers' stock orders and describing the terms of any payment for order flow arrangements.","u":"Understanding how a broker handles and is paid for order flow.","m":"Worth a look if you trade often; for buy-and-hold fund investors, fees and cash rates matter far more."},
{"t":"Ordinary income","c":"Taxes","l":1,"d":"Income taxed at regular rates: wages, interest, short-term gains, and traditional retirement account withdrawals.","u":"Most income.","m":"Taxed at higher rates than long-term capital gains and qualified dividends."},
{"t":"Out-of-pocket maximum","a":["out-of-pocket limit","OOP max"],"c":"Insurance","l":1,"mod":"INV-023","d":"The most a health plan can require you to pay in a year for covered in-network care through deductibles, copays and coinsurance; premiums do not count.","u":"Knowing your worst case for a covered medical year.","m":"Make sure your emergency fund could cover it. Out-of-network and non-covered costs are outside the cap."},
{"t":"Outcome goal","c":"Planning","l":2,"mod":"INV-024","d":"A goal stated as a result, such as '$40,000 by 2032', as opposed to a behavior goal, the action that produces it, such as '$510 on the first of each month'.","u":"Separating what you control (saving) from what markets partly control (the result).","m":"Review the outcome yearly and adjust the behavior; do not change the behavior every time markets move.","a":[]},
{"t":"Overconfidence","c":"Behavior","l":2,"d":"Overestimating one's knowledge or ability to predict.","u":"Explaining excessive trading.","m":"Research links frequent trading by individuals to lower returns."},
{"t":"Overfitting","a":["data mining","data snooping","curve fitting"],"c":"Strategies","l":3,"mod":"INV-049","d":"Tuning a model so closely to past data that it captures noise rather than a lasting pattern; it then tends to disappoint on new data.","u":"Explaining why the best-looking backtest is often the least reliable.","m":"Be wary of rules whose results change sharply when a setting moves by one notch."},
{"t":"Own-occupation disability coverage","a":["own occupation","own-occupation"],"c":"Insurance","l":3,"mod":"INV-023","d":"A disability-insurance definition that pays if you cannot perform the main duties of your own occupation, even if you could work in another one. 'Any occupation' definitions pay only if you cannot do any suitable work.","u":"Protecting specialized earnings.","m":"Group policies often switch to an any-occupation definition after a period; read the definition before relying on it."},
{"t":"Par value","a":["face value"],"c":"Asset classes","l":1,"mod":"INV-009","d":"The amount a bond's issuer promises to repay at maturity, usually $1,000 per bond; also the basis for calculating its coupon.","u":"Quoting bond prices (as a percentage of par) and computing coupons.","m":"A bond quoted at 96.24 costs $962.40 per $1,000 of par. Held to maturity, you receive par regardless of what you paid."},
{"t":"Parent PLUS loan","c":"Planning","l":2,"mod":"INV-096","d":"A federal Direct loan that parents of a dependent undergraduate can borrow to pay college costs not covered by other aid.","u":"Filling gaps in a college budget.","m":"For new borrowing after July 1, 2026, parents may borrow no more than $20,000 a year and $65,000 in total per dependent student, with a transition rule for students already enrolled.","a":[]},
{"t":"Participation rate","c":"Insurance","l":2,"mod":"INV-017","d":"The share of an index's gain credited to an indexed annuity. At a 75% participation rate, a 10% index gain is credited as 7.5% (SEC example).","u":"One of the limits that funds an indexed annuity's downside protection.","m":"Combined with a cap or spread, it can reduce your share of a good year sharply; insurers can often change it.","a":[]},
{"t":"Passive activity loss rules","c":"Real estate","l":3,"d":"Rules limiting deductions of losses from rental and other passive activities against wages; a special allowance of up to $25,000 phases out between $100,000 and $150,000 of modified AGI for active participants.","u":"Rental property tax planning.","m":"Suspended losses carry forward and are released when you sell."},
{"t":"Passive investing","a":["indexing"],"c":"Strategies","l":1,"d":"Holding broad, low-cost index funds that track the market instead of trying to beat it.","u":"A core strategy for most long-term investors.","m":"Supported by the arithmetic of active management and decades of performance data."},
{"t":"Pay yourself first","c":"Planning","l":1,"d":"Automatically saving a set amount as soon as income arrives, before discretionary spending.","u":"Building savings habits.","m":"Payroll deductions to a 401(k) are the easiest way to do it."},
{"t":"Payment for order flow","a":["PFOF"],"c":"Markets","l":3,"mod":"INV-005","d":"Compensation a broker receives from a market maker for routing customer orders to it.","u":"One way commission-free brokers earn revenue.","m":"Brokers must disclose routing under SEC Rule 606; the practice raises conflict-of-interest questions."},
{"t":"Payout rate","c":"Insurance","l":1,"mod":"INV-082","d":"An annuity's yearly income divided by the premium paid, such as $7,000 a year on $100,000, a 7% payout rate.","u":"Comparing income annuity quotes for the same contract features.","m":"A payout rate is not an interest rate: part of each payment is your own money coming back. Compare quotes for identical contracts.","a":[]},
{"t":"Payout ratio","c":"Valuation","l":2,"mod":"INV-006","d":"Dividends divided by earnings.","u":"Judging dividend sustainability.","m":"Above 100% for long is not sustainable."},
{"t":"Payroll taxes","a":["FICA","FICA taxes"],"c":"Taxes","l":1,"mod":"INV-029","d":"Social Security and Medicare taxes on wages: 6.2% and 1.45% for employees, matched by employers; 12.4% and 2.9% for the self-employed.","u":"Funding Social Security and Medicare.","m":"For many workers they exceed income tax. Traditional 401(k) deferrals do not reduce them; HSA contributions through a cafeteria plan do."},
{"t":"Pension","a":["defined benefit plan"],"c":"Retirement","l":2,"d":"An employer plan promising a set retirement income based on salary and years of service.","u":"Guaranteed retirement income.","m":"The lump-sum-versus-annuity choice is a present-value and longevity decision."},
{"t":"Pension Benefit Guaranty Corporation","a":["PBGC"],"c":"Retirement","l":2,"mod":"INV-080","d":"The federal corporation created by ERISA in 1974 that insures private-sector defined benefit pensions up to limits set by law.","u":"Paying pensions when a plan ends without enough money. For single-employer plans ending in 2026, the maximum straight-life guarantee at 65 is $7,789.77 a month.","m":"Most pensions are below the limit. Early retirees with large benefits should check the table for their age."},
{"t":"Pension risk transfer","c":"Retirement","l":3,"mod":"INV-080","d":"An employer's transfer of pension obligations to an insurance company, usually by buying a group annuity, or by offering participants lump sums.","u":"Letting employers remove pension risk from their books.","m":"If your pension moves to an insurer, protection behind it comes from state guaranty associations, which have their own limits.","a":[]},
{"t":"Per capita","a":["per capita at each generation"],"c":"Estate","l":2,"mod":"INV-085","d":"A way of dividing property equally among the individuals in a class who are alive. The variant 'per capita at each generation' pools the shares of deceased children and divides them equally among all their children.","u":"Treating every member of a generation the same.","m":"It gives a different answer from per stirpes when branches have different numbers of grandchildren. Use the same method in every document."},
{"t":"Per stirpes","c":"Estate","l":2,"mod":"INV-085","d":"A way of dividing property by family branch: shares are set at the children's level, and a deceased child's share passes down to that child's own descendants.","u":"Wills, trusts and beneficiary forms that should keep each branch of the family equal.","m":"If a beneficiary form lacks a per stirpes election, a deceased child's share often goes to the other named beneficiaries and that child's children receive nothing.","a":[]},
{"t":"Percentile band","a":["percentile"],"c":"Foundations","l":2,"mod":"INV-077","d":"A line showing, for each year of a simulation, the value that a given share of simulated paths stayed above; the 10th-percentile line is beaten by 90% of paths.","u":"Displaying the spread of outcomes over time, not just the final success rate.","m":"Look at the 10th or 25th percentile in the first decade: it is the realistic bad path you should be ready to live through."},
{"t":"Performance chasing","c":"Behavior","l":2,"mod":"INV-061","d":"Buying investments after they have risen strongly and selling after they have fallen.","u":"Explaining much of the behavior gap.","m":"A written rebalancing rule makes you do the opposite: trim what has risen, add to what has fallen.","a":[]},
{"t":"Performance fee","a":["incentive fee","carried interest","carry"],"c":"Costs","l":3,"mod":"INV-014","d":"A share of a fund's profits paid to its manager, typically 15–20% for hedge funds according to the SEC, often subject to a high-water mark and a hurdle rate. In private equity it is called carried interest.","u":"Rewarding managers for gains; the '20' in '2 and 20'.","m":"You share your upside but still bear all of the downside, and the fee can encourage the manager to take more risk."},
{"t":"Performance persistence","a":["persistence","persistence scorecard"],"c":"Strategies","l":2,"mod":"INV-043","d":"The tendency, if any, for funds that did well in one period to do well again in the next.","u":"Testing whether good results reflect skill (which should persist) or luck (which should not).","m":"Top-performing funds rarely stay on top; poor, high-cost funds more reliably keep lagging."},
{"t":"Period certain","a":["period-certain annuity","life with period certain"],"c":"Insurance","l":2,"mod":"INV-080","d":"An annuity feature that guarantees payments for a minimum number of years, such as 10, even if the annuitant dies sooner; a beneficiary receives the rest.","u":"Reducing the risk that early death leaves heirs with nothing.","m":"It lowers the monthly income. Compare its cost with other ways of leaving money to heirs."},
{"t":"Period life table","a":["life table","cohort life table"],"c":"Retirement","l":2,"mod":"INV-080","d":"A table of death probabilities and life expectancies by age, based on death rates during one period. The SSA's 2023 period table gives a 65-year-old man 18.12 more years and a woman 20.66.","u":"Valuing pensions and annuities and estimating how long retirement savings must last.","m":"Period tables ignore future improvements in mortality, so real lifespans tend to be somewhat longer. Pension plans use IRS tables for plan participants, who live longer than average."},
{"t":"Period of limitations","a":["statute of limitations (tax)"],"c":"Taxes","l":2,"mod":"INV-059","d":"The period during which you can amend a tax return to claim a refund or the IRS can assess more tax. The IRS ties record keeping to it: generally 3 years, 6 if income over 25% of gross income went unreported, 7 for worthless-securities or bad-debt losses, and indefinitely if no return or a fraudulent one was filed.","u":"Deciding how long to keep tax records.","m":"Most papers can go after three years, but records of what you paid for investments must last until the period ends for the year you sell."},
{"t":"Permanent Portfolio","c":"Strategies","l":3,"d":"Harry Browne's allocation of equal parts stocks, long-term Treasuries, cash and gold.","u":"Resilience across economic regimes.","m":"Lower long-run returns than stock-heavy portfolios in exchange for smaller drawdowns."},
{"t":"Perpetual withdrawal rate","c":"Retirement","l":3,"mod":"INV-072","d":"A withdrawal rate low enough that the portfolio's real value is expected to be preserved indefinitely, rather than spent down over a fixed horizon.","u":"Planning very long early retirements or leaving principal to heirs.","m":"It is at or below the long-run real return you can reliably earn after fees, which history suggests is well under 4% for 50-plus-year horizons.","a":[]},
{"t":"Personal saving rate","c":"Foundations","l":2,"mod":"INV-018","d":"Personal saving as a percentage of disposable personal income for the whole economy, published monthly by the Bureau of Economic Analysis.","u":"Tracking how much of national after-tax income households save.","m":"It is an economy-wide residual that is often revised; it is not comparable with your own savings rate.","a":[]},
{"t":"Phishing","a":["smishing"],"c":"Behavior","l":1,"mod":"INV-104","d":"Messages, by email (phishing) or text (smishing), that impersonate a trusted firm to trick you into revealing login details or visiting a fake website.","u":"The most common opening move in account takeovers and many scams.","m":"Never use a link or phone number from an unexpected message; contact the firm through a number or website you already trust."},
{"t":"Pig butchering","a":["cryptocurrency investment fraud","sha zhu pan"],"c":"Advice & regulation","l":1,"mod":"INV-062","d":"A long-con cryptocurrency investment scam in which a stranger builds a friendly or romantic relationship, then steers the victim to a fake trading platform that shows fake profits; the name comes from 'fattening the pig before slaughter' (FinCEN, 2023).","u":"Recognizing the largest source of reported fraud losses to Americans in 2025 (FBI IC3).","m":"Anyone you have not met in person who brings up investing is a red flag."},
{"t":"PITI","c":"Real estate","l":1,"mod":"INV-064","d":"Principal, interest, taxes and insurance: the full monthly housing payment on a mortgaged home when taxes and insurance are paid through escrow.","u":"Lender affordability tests and household budgeting.","m":"Compare PITI, plus maintenance and any HOA dues, with rent. Principal and interest alone understate what owning costs each month.","a":[]},
{"t":"Plan failure rate","a":["failure rate"],"c":"Retirement","l":2,"mod":"INV-073","d":"The share of historical start years, or simulated paths, in which a withdrawal plan ran out of money before the end of its horizon.","u":"Comparing withdrawal rates and allocations.","m":"Historical windows overlap heavily, so a failure rate from US data is a stress test of one country's history, not a true probability."},
{"t":"Plan loan offset","c":"Accounts","l":3,"mod":"INV-100","d":"The reduction of a 401(k) account by an unpaid loan balance, typically when a participant leaves the employer. It is treated as an actual distribution but may be rolled over.","u":"Closing out a plan loan that can no longer be repaid through payroll.","m":"If the offset is due to leaving the job, you have until your tax return's due date, including extensions, to deposit the same amount in an IRA or plan and avoid tax (IRS).","a":[]},
{"t":"Planning age","a":["planning horizon"],"c":"Planning","l":2,"mod":"INV-075","d":"The age to which a retirement plan is built to last, usually chosen so that there is only a small chance (for example 10–25%) of living longer.","u":"Setting the length of a withdrawal plan or Monte Carlo simulation.","m":"For a couple it should be based on the longer-lived spouse; at 65/65, SSA's table gives about a 21% chance that at least one reaches 95."},
{"t":"Ponzi scheme","c":"Behavior","l":1,"d":"A fraud that pays earlier investors with money from new investors rather than real returns.","u":"Recognizing fraud.","m":"Consistently high returns with no losses, secrecy and pressure to recruit are warning signs."},
{"t":"Pooled trust","a":["(d)(4)(C) trust"],"c":"Estate","l":3,"mod":"INV-102","d":"A trust run by a nonprofit that keeps a separate account for each disabled beneficiary but pools the money for investment; amounts not retained by the trust at death repay Medicaid (SSA POMS SI 01120.203).","u":"Protecting benefits with smaller sums, or when no family member can serve as trustee.","m":"There is no age limit, but transfers at 65 or older can bring a transfer penalty."},
{"t":"Portability","a":["DSUE"],"c":"Estate","l":3,"d":"The ability of a surviving spouse to use the deceased spouse's unused federal estate tax exemption, if elected on a timely estate tax return.","u":"Doubling a couple's exemption.","m":"Requires filing Form 706 even when no tax is due."},
{"t":"Portfolio","c":"Portfolio","l":1,"mod":"INV-055","d":"Everything you own for future spending, across every account: workplace plans, IRAs, brokerage accounts, savings and CDs, managed as one whole.","u":"Setting and checking your overall mix of stocks, bonds and cash against your goals.","m":"A single account can look lopsided and still be right, if the combined mix across all your accounts matches your plan.","a":[]},
{"t":"Portfolio drift","a":[],"c":"Portfolio","l":1,"mod":"INV-056","d":"The change in a portfolio's asset weights caused by its assets earning different returns.","u":"Deciding when to rebalance; many rules trade only when drift passes a set limit.","m":"Left alone, a 60/40 portfolio started in 1928 would have been 99.6% stocks by the end of 2025. Drift adds risk nobody chose."},
{"t":"Postnuptial agreement","a":["postnup"],"c":"Estate","l":2,"mod":"INV-027","d":"An agreement made by spouses after marriage setting how property will be treated or divided.","u":"Recording a plan made after an inheritance, a new business or a second marriage.","m":"Rules on enforceability vary more by state than for prenuptial agreements; each spouse should have their own lawyer."},
{"t":"Pour-over will","c":"Estate","l":2,"mod":"INV-087","d":"A will that leaves anything not already in your living trust to that trust at your death.","u":"A safety net for assets you forgot or acquired after funding the trust.","m":"Property that reaches the trust through a pour-over will still passes through probate first. It does not replace funding the trust.","a":[]},
{"t":"Power of attorney","a":["durable power of attorney"],"c":"Estate","l":1,"d":"A document authorizing someone to act for you in financial or legal matters, often effective if you become incapacitated.","u":"Managing finances during incapacity.","m":"Without it, family may need a court guardianship."},
{"t":"Precommitment","a":["Ulysses contract"],"c":"Behavior","l":2,"mod":"INV-028","d":"Binding your future self to a course of action decided in advance, when you are calm, so that emotion cannot override it later.","u":"Automatic contributions, written rebalancing rules and a written crash plan in an investment policy statement.","m":"The rules you write before a crash are almost always better than the ones you would invent during it."},
{"t":"Preferred stock","a":["preferred shares","preferreds"],"c":"Markets","l":2,"mod":"INV-011","d":"Shares that usually have no voting rights but receive dividends before common stockholders and rank ahead of them, behind bondholders, in a liquidation.","u":"Income investing.","m":"Bond-like income without a bond's claim to repayment. Many preferreds have no maturity and are sensitive to interest rates."},
{"t":"Premium or discount to NAV","a":["ETF premium","ETF discount"],"c":"Vehicles","l":3,"mod":"INV-012","d":"The percentage difference between an ETF's market price and its net asset value per share.","u":"Judging whether you are paying more or less than an ETF's holdings are worth.","m":"SEC Rule 6c-11 requires ETFs to post it daily on their websites. Use limit orders, especially in volatile markets."},
{"t":"Premium tax credit","a":["PTC","advance premium tax credit","APTC"],"c":"Insurance","l":2,"mod":"INV-074","d":"A federal credit that lowers marketplace health-insurance premiums: the benchmark plan's premium minus an expected contribution set as a percentage of household income.","u":"Making individual coverage affordable for people without job-based insurance, including early retirees.","m":"For 2026 it is available from 100% to 400% of the poverty line, and excess advance credits must be repaid in full at tax time."},
{"t":"Prenuptial agreement","a":["prenup","premarital agreement"],"c":"Planning","l":2,"mod":"INV-095","d":"A written contract signed before marriage that changes the state's default rules on property, debts and, within limits, support.","u":"Protecting a business, an inheritance or assets meant for children from an earlier relationship, and settling in advance how property would be divided.","m":"It must be fair when signed. Arizona, for example, will not enforce one signed involuntarily, or one that was unconscionable where fair financial disclosure was missing."},
{"t":"Prepayment risk","c":"Asset classes","l":3,"mod":"INV-010","d":"The risk that borrowers repay a loan early, usually when interest rates fall, returning principal to the investor sooner than expected.","u":"Analyzing mortgage-backed securities and callable debt.","m":"It caps price gains when rates fall and lengthens duration when rates rise, which is why MBS pay more than Treasuries.","a":[]},
{"t":"Present bias","c":"Behavior","l":2,"mod":"INV-060","d":"Giving much more weight to rewards now than to larger rewards later.","u":"Explaining under-saving and procrastination.","m":"Automatic payroll saving and escalation remove the decision from the moment.","a":[]},
{"t":"Present interest","a":["future interest"],"c":"Estate","l":3,"mod":"INV-092","d":"A gift the recipient can use, possess or enjoy immediately. A gift that can be enjoyed only later is a future interest. Only present interests qualify for the annual gift exclusion (IRC 2503(b)).","u":"Deciding whether a gift, especially one into a trust, is covered by the annual exclusion.","m":"Outright gifts qualify; gifts to most trusts need a withdrawal right to qualify."},
{"t":"Present value","a":["PV","discounting"],"c":"Foundations","l":1,"mod":"INV-002","d":"The value today of money to be received in the future: PV = FV ÷ (1 + r)^n.","u":"Comparing lump sums with payment streams; valuing bonds, pensions and businesses.","m":"You cannot compare dollars at different dates until you convert them to the same date."},
{"t":"Price-to-book ratio","a":["P/B"],"c":"Valuation","l":2,"mod":"INV-006","d":"Share price divided by book value per share.","u":"Valuing banks and asset-heavy firms; value investing screens.","m":"Less meaningful for companies whose value is mostly intangible."},
{"t":"Price-to-earnings ratio","a":["P/E","P/E ratio"],"c":"Valuation","l":1,"mod":"INV-006","d":"Share price divided by earnings per share.","u":"Gauging how much optimism a price contains.","m":"High is not automatically expensive, nor low automatically cheap; it shows expectations."},
{"t":"Price-to-rent ratio","a":["P/R ratio"],"c":"Real estate","l":1,"mod":"INV-063","d":"A home's price divided by one year's rent for a comparable home. A $300,000 home that would rent for $1,500 a month has a ratio of 300,000 ÷ 18,000 = 16.7.","u":"Comparing how expensive buying is relative to renting across cities and over time.","m":"A high ratio means each dollar of price buys little rent-equivalent; renting and investing the difference tends to look better. It is a screen, not a decision."},
{"t":"Primary beneficiary","c":"Estate","l":1,"mod":"INV-027","d":"The first person or entity named to receive an account or policy at the owner's death.","u":"Directing retirement accounts, life insurance and transfer-on-death accounts outside the will.","m":"For employer plans, the form on file decides who is paid; update it after every marriage, divorce, birth or death.","a":[]},
{"t":"Primary insurance amount","a":["PIA"],"c":"Retirement","l":3,"d":"The Social Security benefit payable at full retirement age, calculated from your average indexed monthly earnings.","u":"The base for your own, spousal and survivor benefits.","m":"Your my Social Security account at ssa.gov shows your estimate."},
{"t":"Primary market","c":"Markets","l":2,"mod":"INV-005","d":"Where new securities are first sold by the issuer to investors, as in an initial public offering.","u":"Raising capital for companies and governments.","m":"Most individual investors buy existing shares in the secondary market."},
{"t":"Prime money market fund","c":"Vehicles","l":3,"mod":"INV-008","d":"A money market fund that may also hold short-term corporate debt such as commercial paper, in addition to government securities.","u":"Earning slightly more than a government fund in exchange for some credit risk.","m":"The Reserve Primary Fund, a prime fund, broke the buck in 2008. Institutional prime funds must float their share price and may charge liquidity fees under the 2023 rules.","a":[]},
{"t":"Principal","c":"Foundations","l":1,"d":"The original amount invested or borrowed, excluding interest or gains.","u":"Loans, bonds and deposits.","m":"On a loan, extra payments usually reduce principal and therefore all future interest."},
{"t":"Private credit","c":"Asset classes","l":3,"d":"Loans made to companies by non-bank lenders, typically through private funds.","u":"Higher-yield income outside public bond markets.","m":"Less liquid and less transparent than public bonds."},
{"t":"Private equity","c":"Asset classes","l":3,"d":"Ownership stakes in companies that are not publicly traded, usually through long-term funds.","u":"Institutional and wealthy investors seeking returns beyond public markets.","m":"Illiquid, high-fee and hard to value; smoothed reported values can understate risk."},
{"t":"Private foundation","c":"Estate","l":2,"mod":"INV-093","d":"A charitable organization typically funded and controlled by one family, run by its own board. It generally must pay out about 5% of investment assets a year (IRC 4942) and pays a 1.39% excise tax on net investment income (IRC 4940).","u":"Long-term family philanthropy with full control over grants, staff and programs.","m":"Costlier and more regulated than a donor-advised fund, with lower deduction limits for lifetime gifts.","a":[]},
{"t":"Private key","a":["seed phrase","recovery phrase"],"c":"Asset classes","l":1,"mod":"INV-015","d":"The secret number that authorizes transfers from a crypto address. Wallets usually encode it as a seed or recovery phrase of 12 or 24 words.","u":"Proving control of crypto assets and signing transactions.","m":"Whoever holds the key controls the coins. Lose it and the assets are unrecoverable; share it and they can be stolen, with no bank to reverse the transfer."},
{"t":"Private mortgage insurance","a":["PMI"],"c":"Real estate","l":2,"d":"Insurance that protects the lender, usually required on conventional loans with less than 20% down.","u":"Enabling smaller down payments.","m":"It can generally be removed once enough equity is built."},
{"t":"Pro-rata rule","c":"Taxes","l":3,"d":"The rule that IRA conversions and distributions are treated as coming proportionally from pre-tax and after-tax money across all your traditional, SEP and SIMPLE IRAs.","u":"Calculating tax on conversions.","m":"Rolling pre-tax IRA money into a workplace plan can make a backdoor Roth cleaner."},
{"t":"Probate","c":"Estate","l":1,"d":"The court process of validating a will, paying debts and distributing assets.","u":"Settling estates.","m":"Can be slow, public and costly; beneficiary designations and trusts avoid it."},
{"t":"Professional designation","a":["financial credential"],"c":"Advice & regulation","l":2,"mod":"INV-103","d":"A title or set of letters awarded by a private organization, such as the CFP mark. Designations vary widely in education, exams, continuing education and enforcement. FINRA keeps a free database describing their requirements and states that it does not approve or endorse any credential.","u":"Signaling training in a specialty.","m":"Give weight only to a credential you can verify with the body that issues it."},
{"t":"Profitability factor","a":["RMW","robust minus weak"],"c":"Strategies","l":3,"mod":"INV-048","d":"The return of companies with robust operating profitability minus those with weak profitability; part of the Fama–French five-factor model.","u":"Measuring the 'quality' premium.","m":"Profitable companies earned more than weak ones from 1964 to 2025, with less volatility; it had its own bad years, such as 1999."},
{"t":"Projection bias","c":"Behavior","l":2,"mod":"INV-025","d":"The tendency to assume that your future preferences and feelings will match how you feel now.","u":"Explaining why risk-tolerance scores rise after market gains and fall after declines.","m":"A questionnaire answered after a long bull market probably overstates how calmly you will take the next crash.","a":[]},
{"t":"Promote","a":[],"c":"Real estate","l":3,"mod":"INV-069","d":"The sponsor's share of a deal's profits above the preferred return, such as 20% or 30%.","u":"Rewarding the sponsor for good results.","m":"Combined with fees, it can take several percentage points a year from investors' returns even in a successful deal."},
{"t":"Property manager","a":["property management company"],"c":"Real estate","l":1,"mod":"INV-067","d":"A person or company paid to market a rental, screen tenants, collect rent, arrange repairs and handle notices and evictions for the owner.","u":"Turning a rental into a more passive investment.","m":"Fees are usually a share of collected rent plus leasing and other charges; compare the total with the hours and legal risk you would otherwise carry."},
{"t":"Property tax","c":"Real estate","l":1,"mod":"INV-063","d":"A tax local governments levy each year on the assessed value of real estate. Rates and assessment rules vary widely by state, county and city.","u":"Funding schools and local services; a major ongoing cost of owning.","m":"It never goes away when the mortgage is paid off. Check the actual bill for a specific property, not a state average.","a":[]},
{"t":"Proportional withdrawal","c":"Retirement","l":2,"mod":"INV-042","d":"Taking each year's spending from every account in proportion to its balance.","u":"Spreading taxable income evenly without yearly bracket calculations.","m":"Often beats the conventional order and is easy to automate.","a":[]},
{"t":"Prospect theory","c":"Behavior","l":2,"mod":"INV-060","d":"Daniel Kahneman and Amos Tversky's 1979 model of how people actually choose under risk: outcomes are judged as gains and losses from a reference point, losses weigh more than equal gains, and probabilities are weighted unevenly.","u":"Explaining choices that expected-value math cannot, such as buying lottery tickets and insurance at the same time.","m":"Your feelings about a portfolio depend on where you start counting; decide that starting point deliberately.","a":[]},
{"t":"Protected class","a":["protected characteristic"],"c":"Real estate","l":1,"mod":"INV-067","d":"A characteristic that fair housing or civil rights law says cannot be the basis for different treatment.","u":"Defining who fair housing laws protect.","m":"Know the federal seven and your state's and city's additions before you write an ad or a screening policy."},
{"t":"Protective put","a":["married put"],"c":"Strategies","l":3,"mod":"INV-016","d":"Buying a put option on shares you own, so that your loss below the strike is capped for the life of the option.","u":"Insuring a concentrated stock position against a fall for a set period.","m":"Like any insurance, it costs a premium every time you renew it; protecting a portfolio this way for years is expensive."},
{"t":"Provisional income","a":["combined income"],"c":"Taxes","l":2,"mod":"INV-081","d":"Adjusted gross income without Social Security, plus tax-exempt interest, plus half of Social Security benefits. Above $25,000 single ($32,000 joint) part of benefits becomes taxable; above $34,000 ($44,000 joint), up to 85% (IRS Publication 915).","u":"Working out how much of your Social Security is taxable.","m":"These thresholds are not indexed for inflation, so IRA withdrawals and RMDs push more retirees over them each year."},
{"t":"Public Service Loan Forgiveness","a":["PSLF"],"c":"Planning","l":2,"mod":"INV-020","d":"A federal program that forgives the remaining balance on Direct Loans after qualifying payments while working full time for a government or qualifying nonprofit employer.","u":"Reducing student debt for public-sector and nonprofit workers.","m":"Its rules are strict; payments under the Repayment Assistance Plan count. Private refinancing ends eligibility."},
{"t":"Pump-and-dump","a":["pump and dump"],"c":"Advice & regulation","l":1,"mod":"INV-062","d":"A scheme in which promoters raise a stock's or token's price with false or misleading hype, then sell their own holdings to the buyers they attracted.","u":"Recognizing hyped tips about little-known securities.","m":"A tip that urges you to buy quickly is usually someone else's exit."},
{"t":"Purchasing power","c":"Foundations","l":1,"mod":"INV-001","d":"The quantity of goods and services a sum of money can buy.","u":"Judging whether savings and income have kept up with prices.","m":"A balance that never falls in dollars can still lose purchasing power every year."},
{"t":"Pyramid scheme","c":"Advice & regulation","l":1,"mod":"INV-062","d":"A fraud in which participants are paid mainly for recruiting others rather than for selling a real product or earning a real return.","u":"Recognizing recruitment-based frauds.","m":"If the money comes from recruits, not customers, it must collapse when recruiting slows.","a":[]},
{"t":"QTIP trust","a":["qualified terminable interest property","QTIP"],"c":"Estate","l":3,"mod":"INV-087","d":"A trust that pays a surviving spouse all its income at least annually for life, with no one able to direct the property elsewhere during the spouse's life, and that the executor elects to qualify for the marital deduction (26 U.S.C. 2056(b)(7)).","u":"Supporting a surviving spouse while guaranteeing the remainder goes to the first spouse's chosen heirs.","m":"Common in blended families. No estate tax at the first death, but the trust is taxed in the survivor's estate."},
{"t":"Qualified appreciated stock","c":"Taxes","l":3,"mod":"INV-039","d":"Publicly traded stock held more than one year that has risen in value; given to a public charity, it is generally deductible at fair market value up to 30% of AGI.","u":"Giving gains away untaxed along with the shares.","m":"Your lowest-basis shares make your cheapest gifts.","a":[]},
{"t":"Qualified business income deduction","a":["QBI deduction","Section 199A deduction","QBI"],"c":"Taxes","l":2,"mod":"INV-101","d":"A deduction of up to 20% of qualified business income from pass-through businesses, limited to 20% of taxable income minus net capital gain. P.L. 119-21 removed its post-2025 expiration, widened the phase-in ranges and added a $400 minimum for active businesses.","u":"Reducing income tax, not self-employment tax, on business profits.","m":"For 2026, below $201,750 of taxable income ($403,500 joint), the wage and service-business limits do not apply."},
{"t":"Qualified charitable distribution","a":["QCD"],"c":"Taxes","l":3,"d":"A direct transfer from an IRA to a charity by someone aged 70½ or older, excluded from income and counting toward RMDs, up to an annual limit.","u":"Tax-efficient giving in retirement.","m":"Often better than giving cash for retirees who take the standard deduction."},
{"t":"Qualified custodian","a":["custody rule"],"c":"Advice & regulation","l":3,"mod":"INV-103","d":"A bank, broker-dealer or similar institution that holds client assets. Under the SEC's custody rule, an adviser with custody generally must keep client funds and securities at a qualified custodian and have a reasonable basis to believe the custodian sends clients statements at least quarterly.","u":"Separating the person who advises you from the institution that holds your money.","m":"You should receive statements directly from the custodian. Compare them with any report your adviser sends."},
{"t":"Qualified default investment alternative","a":["QDIA"],"c":"Accounts","l":2,"mod":"INV-050","d":"A default investment for workers who do not choose one, meeting the Labor Department's regulation at 29 CFR 2550.404c-5: a target-date fund, balanced fund, managed account, or (for up to 120 days) a capital-preservation product.","u":"Giving employers fiduciary relief when they invest automatically enrolled workers' money.","m":"The default is chosen for a typical worker of your age, not for you; you can move out at least once every three months."},
{"t":"Qualified disability expenses","a":["QDE"],"c":"Accounts","l":3,"mod":"INV-102","d":"Expenses for an ABLE beneficiary related to the disability, broadly including education, housing, transportation, employment support, assistive technology, health, legal and financial management, funeral costs and basic living expenses (SSA).","u":"Determining which ABLE withdrawals are tax-free and ignored by SSI.","m":"Housing is included, but money withdrawn for housing and kept past the month can count as a resource."},
{"t":"Qualified disclaimer","a":["disclaimer"],"c":"Estate","l":3,"mod":"INV-085","d":"A written refusal to accept an inheritance that meets federal requirements, including delivery within nine months of the transfer (or of turning 21) and no acceptance of benefits (26 U.S.C. 2518).","u":"Letting property pass as if the person had died first, without being treated as a gift by the person disclaiming.","m":"A family can use it to fix some planning problems after a death, but the property can only go where the document or law would otherwise send it."},
{"t":"Qualified dividend","c":"Taxes","l":2,"d":"A dividend meeting holding-period and source rules, taxed at long-term capital gains rates.","u":"Lower tax on most US stock dividends.","m":"Interest and non-qualified dividends are taxed as ordinary income."},
{"t":"Qualified domestic relations order","a":["QDRO"],"c":"Retirement","l":2,"mod":"INV-095","d":"A court order, accepted by a retirement plan, that directs the plan to pay part of a participant's benefit to an alternate payee such as a former spouse or child.","u":"Dividing 401(k)s, 403(b)s and pensions at divorce, or paying support from them.","m":"A former spouse can roll the money into their own IRA tax-free, or take cash directly from the plan with income tax but no 10% early-withdrawal penalty."},
{"t":"Qualified domestic trust","a":["QDOT"],"c":"Estate","l":3,"mod":"INV-088","d":"A trust that lets property left to a surviving spouse who is not a US citizen qualify for the estate tax marital deduction, with estate tax imposed as principal is distributed.","u":"Planning for couples in which one spouse is not a US citizen.","m":"Without it, the marital deduction is not available for a non-citizen spouse. The 2026 annual gift exclusion for such a spouse is $194,000 instead of unlimited."},
{"t":"Qualified higher education expenses","a":["qualified education expenses"],"c":"Accounts","l":2,"mod":"INV-034","d":"For a 529 plan, tuition, required fees, books, supplies, equipment and computers at an eligible postsecondary school, and room and board for students enrolled at least half-time. The 529 definition also covers limited K–12 costs, apprenticeships, recognized credentials and up to $10,000 of student loans.","u":"Deciding whether a 529 withdrawal is tax-free.","m":"Match withdrawals to expenses in the same calendar year and keep the bills."},
{"t":"Qualified intermediary","a":["QI","exchange accommodator"],"c":"Real estate","l":3,"mod":"INV-068","d":"An independent party who, under a written exchange agreement, holds sale proceeds and acquires replacement property for you in a deferred 1031 exchange.","u":"Keeping you from actually or constructively receiving the cash, which would make the sale taxable.","m":"Your own real estate agent, attorney or accountant within the past two years is generally disqualified from the role."},
{"t":"Qualified joint and survivor annuity","a":["QJSA"],"c":"Retirement","l":3,"mod":"INV-027","d":"A lifetime annuity for a married plan participant that continues to the surviving spouse at 50% to 100% of the amount paid during the participant's life.","u":"The default payout form that pension-type plans must offer married participants unless both spouses consent in writing to another form.","m":"Your spouse's signature, witnessed by a notary or plan representative, is needed to choose a single-life payout from such a plan."},
{"t":"Qualified joint interest","c":"Estate","l":3,"mod":"INV-090","d":"Property held by spouses as tenants by the entirety, or as joint tenants with right of survivorship when they are the only joint tenants. Half its value is included in the estate of the first spouse to die, whoever paid for it.","u":"Determining how much of a jointly owned asset steps up at the first death.","m":"Outside community-property states, a joint account or home gets a step-up on half, not all, at the first death.","a":[]},
{"t":"Qualified medical expense","c":"Accounts","l":2,"mod":"INV-033","d":"A cost that would qualify for the medical expense deduction, such as doctor, hospital, prescription, dental and vision bills, for you, your spouse or dependents. Insurance premiums generally do not qualify, except long-term care, COBRA, coverage during unemployment, and Medicare (not Medigap) after 65.","u":"Deciding whether an HSA withdrawal is tax-free.","m":"The same expense cannot be both reimbursed tax-free from an HSA and deducted.","a":[]},
{"t":"Qualified optional survivor annuity","a":["QOSA"],"c":"Retirement","l":3,"mod":"INV-080","d":"A second survivor option plans must offer alongside the default joint and survivor annuity: 75% if the default survivor share is below 75%, or 50% if the default is 75% or more (26 U.S.C. §417(g)).","u":"Giving couples a choice between more income now and more protection for the survivor.","m":"Price each survivor level with a calculator; the best choice depends on how long your spouse is likely to outlive you."},
{"t":"Qualified public safety employee","c":"Retirement","l":3,"mod":"INV-074","d":"A worker, such as a state or local police officer or firefighter, for whom the separation-from-service exception to the 10% early-withdrawal tax applies from age 50 rather than 55.","u":"Early retirement for public safety workers in governmental plans.","m":"The IRS now includes specified federal law enforcement officers, corrections officers, customs and border protection officers, federal and private-sector firefighters, and air traffic controllers.","a":[]},
{"t":"Qualified purchaser","c":"Advice & regulation","l":3,"mod":"INV-014","d":"Under the Investment Company Act of 1940, a natural person who owns at least $5,000,000 in investments (with other tests for companies, trusts and institutions).","u":"Access to private funds that are open only to qualified purchasers.","m":"A higher bar than accredited investor status, and, like it, a wealth test rather than a test of whether an investment suits you.","a":[]},
{"t":"Qualified REIT dividend","a":["Section 199A dividend","199A dividend"],"c":"Taxes","l":3,"mod":"INV-069","d":"An ordinary REIT dividend that is neither a capital gain dividend nor a qualified dividend, reported in box 5 of Form 1099-DIV.","u":"Claiming the 20% section 199A deduction, if you held the shares more than 45 days in the 91-day window around the ex-dividend date.","m":"In the 24% bracket, the deduction lowers the top federal rate on these dividends to 19.2%."},
{"t":"Qualifying life event","c":"Planning","l":2,"mod":"INV-022","d":"A change such as marriage, divorce, a birth or adoption, or loss of other coverage that allows benefit elections to be changed outside open enrollment.","u":"Updating coverage when your household changes.","m":"Plans set short deadlines after the event; act quickly.","a":[]},
{"t":"Qualifying longevity annuity contract","a":["QLAC"],"c":"Retirement","l":3,"mod":"INV-017","d":"A deferred income annuity bought inside an IRA or employer plan that meets IRS rules, so its value is excluded when figuring required minimum distributions. The premium limit is $210,000 for 2026 (IRS Notice 2025-67).","u":"Reducing required minimum distributions while insuring late-life income.","m":"Useful for retirees like Ruth with large IRAs and long family longevity; the money is committed and generally cannot be withdrawn."},
{"t":"Qualifying relative","c":"Taxes","l":2,"mod":"INV-097","d":"A person, such as a parent, who can be your dependent if related to you (or a member of your household), has gross income under $5,300 for 2026, and receives more than half of their total support from you.","u":"Claiming the credit for other dependents, head-of-household status and medical expenses for a relative you support.","m":"Tax-exempt income, such as untaxed Social Security, does not count toward the income limit. A parent does not have to live with you.","a":[]},
{"t":"Qualifying surviving spouse","a":["qualifying widow(er)","qualifying widow"],"c":"Taxes","l":2,"mod":"INV-098","d":"A filing status that lets a widow or widower use the joint brackets and standard deduction for the two tax years after the year of the spouse's death, if they have not remarried and maintain a home for a dependent child or stepchild.","u":"Softening the tax change for widowed parents raising children.","m":"Retired widows without a dependent child at home do not qualify; they file as single from the year after the death."},
{"t":"Quality investing","c":"Strategies","l":3,"d":"Favoring companies with high profitability, stable earnings and strong balance sheets.","u":"A factor-based and fundamental strategy.","m":"Aims to avoid fragile businesses rather than to find bargains."},
{"t":"Random seed","a":["seed"],"c":"Foundations","l":3,"mod":"INV-077","d":"The starting number for a computer's pseudo-random number generator; the same seed always produces the same sequence.","u":"Making simulations reproducible.","m":"If changing only the seed changes the answer a lot, run more simulations; the difference is noise."},
{"t":"Rate cap","a":["annuity cap","cap (annuity)"],"c":"Insurance","l":2,"mod":"INV-017","d":"The maximum return an indexed annuity can credit in a period. With a 7% cap, a 12% index gain is credited as 7% (SEC example). Not the same as a real estate capitalization rate.","u":"Limiting the insurer's cost of the product's downside protection.","m":"Caps usually reset periodically at the insurer's discretion, so the first-year cap may not last."},
{"t":"Rate caps","a":["ARM caps","interest rate caps"],"c":"Real estate","l":2,"mod":"INV-064","d":"Limits on how much an adjustable-rate mortgage's rate can change: at the first adjustment, at each later adjustment, and over the life of the loan.","u":"Estimating the worst-case payment on an ARM.","m":"Calculate the payment at the lifetime cap before you sign. If you could not afford it, the ARM is a bet you cannot cover."},
{"t":"Rate lock-in effect","a":["lock-in effect","mortgage lock-in"],"c":"Real estate","l":2,"mod":"INV-064","d":"The reluctance of owners with low fixed-rate mortgages to sell or move when market rates are much higher, because a new loan would cost more.","u":"Explaining low housing turnover after rates rose in 2022.","m":"A 3% mortgage is a valuable asset, but it should not trap you in a house that no longer fits your life."},
{"t":"Real estate investment trust","a":["REIT"],"c":"Asset classes","l":2,"d":"A company that owns or finances income-producing real estate and must distribute most of its taxable income as dividends.","u":"Liquid real estate exposure.","m":"Trades like a stock and can be as volatile as stocks."},
{"t":"Real estate professional status","c":"Real estate","l":3,"d":"A tax status for people who spend more than 750 hours and more than half their working time in real property businesses, allowing rental losses to offset other income.","u":"Tax planning for full-time real estate investors.","m":"Heavily scrutinized; records of time spent are essential."},
{"t":"Real estate syndication","c":"Real estate","l":3,"d":"A pooled private investment in a property, run by a sponsor, usually for accredited investors.","u":"Passive access to large properties.","m":"Illiquid, fee-heavy and dependent on the sponsor's honesty and skill."},
{"t":"Real return","c":"Foundations","l":1,"mod":"INV-001","d":"The return after removing inflation: (1 + nominal return) ÷ (1 + inflation) − 1.","u":"Comparing investments across periods with different inflation; planning in today's dollars.","m":"Real return is what actually makes you richer. US stocks returned about 6.8% a year after inflation over 1928–2025."},
{"t":"Real yield","c":"Asset classes","l":2,"mod":"INV-010","d":"A yield measured above inflation. For TIPS, the yield set in the market on top of changes in the CPI-U.","u":"Comparing inflation-protected investments and judging what safe money earns in buying power.","m":"The 10-year TIPS real yield was −0.97% on January 3, 2022 and 2.83% on September 25, 2026 (U.S. Treasury).","a":[]},
{"t":"Reasonable accommodation","a":["reasonable accommodations"],"c":"Real estate","l":2,"mod":"INV-067","d":"A change in a rule, policy, practice or service that a person with a disability needs to have equal opportunity to use and enjoy a dwelling, such as allowing an assistance animal in a no-pets building.","u":"A duty landlords have under the Fair Housing Act.","m":"Refusing a reasonable request can be discrimination even if your rule applies to everyone."},
{"t":"Rebalancing","c":"Portfolio","l":1,"mod":"INV-004","d":"Returning a portfolio to its target mix by selling some of what has grown and buying what has lagged.","u":"Keeping risk at the chosen level.","m":"It is mechanical buy-low, sell-high discipline, most valuable after big market moves."},
{"t":"Rebalancing band","a":["tolerance band","rebalancing threshold"],"c":"Portfolio","l":2,"mod":"INV-028","d":"The allowed range around a target weight, such as 55% to 65% around a 60% stock target, outside which you rebalance.","u":"Limiting both risk drift and unnecessary trading.","m":"Bands of about 5 percentage points for large holdings, or a quarter of the target for small ones, are common choices."},
{"t":"Recapture tax","c":"Taxes","l":3,"mod":"INV-074","d":"The tax due if a 72(t) series is changed before the later of five years or age 59½: the 10% that would have applied to every earlier payment, plus interest.","u":"Enforcing the commitment of a 72(t) series.","m":"Breaking a five-year series in year four can mean four years of 10% taxes at once. Size the series carefully.","a":[]},
{"t":"Recency bias","c":"Behavior","l":2,"d":"Giving too much weight to recent events when predicting the future.","u":"Explaining performance chasing.","m":"Last year's best fund is rarely next year's."},
{"t":"Recession","c":"Foundations","l":1,"d":"A significant, widespread decline in economic activity lasting more than a few months; US recessions are dated by the National Bureau of Economic Research.","u":"Economic context for markets.","m":"Stock markets often fall before recessions begin and recover before they end."},
{"t":"Recharacterization","c":"Accounts","l":3,"mod":"INV-032","d":"Treating an IRA contribution as if it had been made to the other type of IRA, by transferring it with its earnings before the filing deadline. Conversions made in 2018 or later can no longer be recharacterized.","u":"Fixing a contribution made to the wrong type of IRA.","m":"A Roth conversion is now permanent; size it carefully.","a":[]},
{"t":"Recourse loan","a":["recourse debt"],"c":"Real estate","l":3,"mod":"INV-066","d":"A loan where the lender can pursue the borrower's other assets if the collateral sells for less than the debt. A non-recourse loan limits the lender to the collateral.","u":"Allocating loss when a property is worth less than its loan.","m":"State law and loan documents decide which you have. With recourse, a leveraged real estate loss can exceed your down payment."},
{"t":"Recovery scam","c":"Advice & regulation","l":1,"mod":"INV-062","d":"A second fraud aimed at people who have already lost money, offering to recover it for an up-front fee.","u":"Protecting fraud victims from being targeted again.","m":"Government agencies do not charge fees to recover your money.","a":[]},
{"t":"Recovery time","c":"Foundations","l":2,"mod":"INV-003","d":"How long an investment takes to regain a previous peak after a drawdown.","u":"Judging the lasting impact of a crash.","m":"After inflation, US stocks bought at the start of 1973 took until 1985 to break even."},
{"t":"Reference point","c":"Behavior","l":2,"mod":"INV-060","d":"The level against which an outcome is judged a gain or a loss, such as the price you paid, last month's balance or a round-number goal.","u":"Explaining why the same balance can feel like a win or a loss.","m":"Measuring progress against your plan, not your portfolio's recent high, reduces the urge to act.","a":[]},
{"t":"Refinancing","a":["refinance","refi"],"c":"Real estate","l":1,"mod":"INV-064","d":"Replacing an existing loan with a new one, usually to get a lower rate, change the term or take cash out.","u":"Lowering interest costs or restructuring debt.","m":"Compare the break-even time on closing costs with how long you will keep the loan, and watch for a longer term hiding in a lower payment."},
{"t":"Refund option","a":["cash refund","installment refund"],"c":"Insurance","l":2,"mod":"INV-082","d":"An annuity feature that pays a beneficiary any part of the premium not yet received as income if the annuitant dies early, in a lump sum (cash refund) or by continuing payments (installment refund).","u":"Guaranteeing that the premium is at least paid back to someone.","m":"It reduces the income. If leaving money matters, compare it with simply annuitizing less."},
{"t":"Refundable tax credit","c":"Taxes","l":2,"mod":"INV-029","d":"A credit that can be paid to you even if it exceeds the tax you owe. A nonrefundable credit can only reduce tax to zero.","u":"Delivering benefits to lower-income families who owe little income tax.","m":"For 2026, up to $1,700 of the $2,200 child tax credit per child is refundable, limited to 15% of earned income above $2,500.","a":[]},
{"t":"Registered investment adviser","a":["RIA"],"c":"Advice & regulation","l":2,"d":"A firm registered with the SEC or a state to give investment advice for a fee, owing clients a fiduciary duty.","u":"Fee-based investment advice.","m":"Its Form ADV discloses fees, conflicts and disciplinary history."},
{"t":"Registered representative","a":["stockbroker","registered rep"],"c":"Advice & regulation","l":2,"mod":"INV-103","d":"An individual registered through FINRA to buy and sell securities for customers on behalf of a broker-dealer.","u":"Executing trades and recommending securities, usually for commissions.","m":"When a registered representative recommends something, Regulation Best Interest applies; check their record on BrokerCheck."},
{"t":"Regret aversion","a":["regret minimization"],"c":"Behavior","l":2,"mod":"INV-051","d":"The tendency to choose the option that minimizes the chance of later blaming yourself, even at the cost of a lower expected outcome.","u":"Explaining the popularity of cost averaging and of doing nothing.","m":"If a short, pre-scheduled phase-in is what gets you invested at all, its small expected cost can be worth paying."},
{"t":"Regulation A","a":["Reg A","Reg A+","Regulation A+"],"c":"Advice & regulation","l":3,"mod":"INV-069","d":"An SEC exemption for public offerings of up to $20 million (Tier 1) or $75 million (Tier 2) in 12 months, with an offering statement filed with the SEC.","u":"Raising money from the public with lighter requirements than a full registration.","m":"In Tier 2, a non-accredited investor may buy no more than 10% of the greater of annual income or net worth, unless the securities will be listed on an exchange."},
{"t":"Regulation Best Interest","a":["Reg BI"],"c":"Advice & regulation","l":3,"d":"An SEC rule, effective since 2020, requiring broker-dealers to act in a retail customer's best interest when recommending securities.","u":"Standards for brokers' recommendations.","m":"Not identical to an adviser's fiduciary duty; ask how each applies to your relationship."},
{"t":"Regulation Crowdfunding","a":["Reg CF"],"c":"Advice & regulation","l":2,"mod":"INV-069","d":"An SEC exemption letting a company raise up to $5 million in 12 months online through a registered broker-dealer or funding portal, with limits on what non-accredited investors may invest.","u":"Offering small investments, including real estate deals, to the general public.","m":"If your income or net worth is under $124,000, your 12-month limit is the greater of $2,500 or 5% of the greater of the two; shares generally cannot be resold for a year."},
{"t":"Regulation D","a":["Reg D","Rule 506(b)","Rule 506(c)"],"c":"Advice & regulation","l":3,"mod":"INV-069","d":"SEC exemptions that let companies raise money privately without registering. Rule 506(b) allows up to 35 non-accredited sophisticated buyers without advertising; Rule 506(c) allows advertising if every buyer is a verified accredited investor.","u":"The legal basis for most real estate syndications.","m":"Exempt offerings are not reviewed by the SEC; your protection is your own diligence."},
{"t":"Reinvestment risk","c":"Asset classes","l":2,"mod":"INV-009","d":"The risk that coupons and maturing principal must be reinvested at lower interest rates than before.","u":"Understanding the trade-off between short and long bonds.","m":"Short-term savers faced it in 2009–2021, when T-bills returned 0.48% a year. Long bonds reduce it but carry more price risk.","a":[]},
{"t":"Rent versus buy","c":"Real estate","l":1,"d":"The decision whether to rent a home or buy one, comparing total costs, returns and flexibility.","u":"Housing decisions.","m":"Renting is not 'throwing money away'; mortgage interest, taxes, maintenance and lost investment returns are real costs of owning."},
{"t":"Repayment Assistance Plan","a":["RAP"],"c":"Planning","l":2,"mod":"INV-020","d":"The income-driven federal student-loan plan created by Public Law 119-21 and available from July 1, 2026: 1% to 10% of adjusted gross income depending on income band, minus $50 a month per dependent, with a $10 minimum.","u":"Income-based repayment for any eligible borrower, and one of only two plans for loans made on or after July 1, 2026.","m":"For on-time payments, unpaid interest is waived and small principal reductions are topped up; any balance left after 360 qualifying payments is forgiven."},
{"t":"Replacement cost coverage","a":["replacement cost","actual cash value"],"c":"Insurance","l":2,"mod":"INV-023","d":"Property coverage that pays what it costs to repair or replace an item or building. Actual cash value coverage pays replacement cost minus depreciation.","u":"Choosing how a home or renter's policy values a loss.","m":"Actual cash value can pay far less for older belongings; replacement cost usually costs a little more."},
{"t":"Replacement ratio","a":["replacement rate"],"c":"Retirement","l":1,"mod":"INV-075","d":"Retirement income as a percentage of income just before retirement. A $75,000 retirement income after a $100,000 final salary is a 75% replacement ratio.","u":"Setting a first-pass retirement target decades ahead, and describing how much of a paycheck Social Security replaces (SSA's 2026 booklet: about 78% for very low earners, 42% for medium earners and 28% for high earners at 67).","m":"A shortcut for your spending, not a rule. Heavy savers and people whose mortgage ends often need much less than 75%; switch to a budget within about ten years of retiring."},
{"t":"Representative payee","c":"Retirement","l":2,"mod":"INV-097","d":"A person or organization the Social Security Administration appoints to receive and manage Social Security or SSI payments for a beneficiary who cannot manage them.","u":"Managing a parent's Social Security when they can no longer do it themselves.","m":"The payee must use the money for the beneficiary and keep records of how it was spent or saved.","a":[]},
{"t":"Required beginning date","c":"Retirement","l":2,"mod":"INV-081","d":"The deadline for your first required minimum distribution: April 1 of the year after you reach your applicable age (73 if born 1951 to 1959, 75 if born 1960 or later).","u":"Setting when RMDs must start; every later RMD is due by December 31.","m":"Waiting until April 1 puts two RMDs in the same tax year. It helps only if the next year's tax rate will be lower.","a":[]},
{"t":"Required minimum distribution","a":["RMD","RMDs"],"c":"Retirement","l":2,"d":"The minimum amount that must be withdrawn each year from tax-deferred retirement accounts, starting at 73 for people born 1951–1959 and 75 for those born 1960 or later (SECURE 2.0).","u":"Ensuring deferred taxes are eventually paid.","m":"Large RMDs can raise taxes and Medicare premiums; Roth conversions earlier can reduce them."},
{"t":"Required minimum distribution method","a":["RMD method"],"c":"Retirement","l":3,"mod":"INV-074","d":"One of three IRS methods for 72(t) payments: the account balance divided by the life expectancy from the chosen IRS table, recomputed every year.","u":"The smallest and most flexible 72(t) payment.","m":"Payments rise and fall with the account. It is the only method you may switch into once without breaking the series."},
{"t":"Residential rental property","c":"Real estate","l":2,"mod":"INV-068","d":"A building or structure in which 80% or more of the rental income comes from dwelling units, such as a rented house, duplex or apartment building. Under the general depreciation system it is depreciated straight-line over 27.5 years.","u":"Classifying a rental building for depreciation.","m":"On a $320,000 building (land excluded), depreciation is about $11,636 a year.","a":[]},
{"t":"Restricted stock unit","a":["RSU","RSUs"],"c":"Taxes","l":2,"d":"A promise of company shares delivered when vesting conditions are met; the value at vesting is taxed as ordinary income.","u":"Common equity pay at public companies.","m":"Holding vested RSUs is the same decision as buying your employer's stock with cash."},
{"t":"Retirement income source tax","a":["source tax"],"c":"Taxes","l":3,"mod":"INV-041","d":"A state tax on retirement income earned in the state but received after the person moves away. Federal law (4 U.S.C. 114) bars states from imposing it on nonresidents.","u":"Protecting retirees who move to another state.","m":"Once you truly change domicile, your former state cannot tax your pension or IRA income."},
{"t":"Retirement Savings Lost and Found","c":"Accounts","l":1,"mod":"INV-059","d":"A Department of Labor online database, required by the SECURE 2.0 Act, that lets workers search for private-sector pension and 401(k)-type plans linked to their Social Security number.","u":"Finding retirement benefits from old or merged employers.","m":"If you think you have a forgotten plan, search lostandfound.dol.gov. Better still, consolidate and list every account in your family file.","a":[]},
{"t":"Retirement spending smile","a":["spending smile"],"c":"Retirement","l":2,"mod":"INV-075","d":"The pattern, found in household survey data, that inflation-adjusted retiree spending tends to fall during retirement, faster in early and late years. David Blanchett (2014) found an average real decline of about 1% a year.","u":"Deciding whether a plan should assume spending rises fully with inflation every year.","m":"Assuming full inflation increases is a conservative default; do not assume a decline until your own spending shows it."},
{"t":"Return","c":"Foundations","l":1,"mod":"INV-001","d":"The gain or loss on an investment over a period, including income and change in price, usually as a percentage.","u":"Comparing investments and measuring progress.","m":"Always check the period, whether income is included, and whether it is before or after fees, taxes and inflation."},
{"t":"Return on equity","a":["ROE"],"c":"Companies","l":2,"mod":"INV-006","d":"Net income divided by shareholders' equity.","u":"Judging how productively a company uses owners' capital.","m":"High ROE from heavy debt is riskier than high ROE from a strong business."},
{"t":"Return smoothing","a":["appraisal smoothing","stale pricing","smoothed returns"],"c":"Portfolio","l":3,"mod":"INV-014","d":"The tendency of reported returns on illiquid assets, valued by appraisal or models rather than market trades, to lag and understate true swings in value.","u":"Explaining why private real estate, private equity and some hedge funds report low volatility and low correlation with stocks.","m":"Smoothing makes an asset look safer than it is. Getmansky, Lo and Makarov (2004) show it understates volatility and inflates Sharpe ratios."},
{"t":"Revenue","a":["sales","top line"],"c":"Companies","l":1,"mod":"INV-006","d":"The total amount customers paid a company for goods and services in a period.","u":"Measuring size and growth.","m":"Growing revenue with shrinking profit can signal a weakening business."},
{"t":"Revenue bond","c":"Asset classes","l":2,"mod":"INV-010","d":"A municipal bond repaid only from a specific revenue source, such as tolls, utility charges or lease fees, not from general taxes.","u":"Financing projects that generate their own revenue.","m":"Its safety depends on that project's finances; some are non-recourse if the revenue dries up.","a":[]},
{"t":"Revocable living trust","c":"Estate","l":2,"d":"A trust you control during life and can change, which becomes irrevocable at death.","u":"Avoiding probate; planning for incapacity.","m":"Does not by itself reduce estate taxes or protect assets from creditors."},
{"t":"Risk","c":"Foundations","l":1,"mod":"INV-003","d":"The chance that an investment's actual result differs from what was expected, especially that it falls short when the money is needed.","u":"Choosing how much to invest in each asset.","m":"The risk that matters most is personal: being forced to sell low or reaching a goal without enough."},
{"t":"Risk capacity","c":"Planning","l":1,"d":"Your financial ability to absorb losses without derailing your goals, based on income, savings, time horizon and obligations.","u":"Setting the upper limit on risk.","m":"You can be willing to take risk but unable to afford it, or the reverse."},
{"t":"Risk need","c":"Planning","l":2,"d":"The level of return, and therefore risk, required to reach your goals.","u":"Avoiding unnecessary risk once goals are within reach.","m":"If you have already 'won the game,' you may not need to keep playing as hard."},
{"t":"Risk premium","c":"Foundations","l":2,"mod":"INV-001","d":"The extra expected return an investment offers above a safe alternative, as compensation for its risk.","u":"Setting long-run expectations; screening implausible offers.","m":"A product offering high returns with no risk is misdescribing one or the other."},
{"t":"Risk questionnaire","a":["risk profile questionnaire","risk tolerance questionnaire"],"c":"Planning","l":1,"mod":"INV-025","d":"A scored set of questions about reactions, experience, goals and finances used to estimate how much investment risk someone should take.","u":"A starting point for choosing an asset allocation, used by many brokers, advisors and robo-advisors.","m":"Treat the score as a range, check it against dollar losses and your real past behavior, and separate willingness from ability."},
{"t":"Risk tolerance","c":"Planning","l":1,"d":"Your emotional willingness to accept investment losses and volatility.","u":"Choosing an allocation you can stick with.","m":"Often overestimated in bull markets; test it against real crash numbers."},
{"t":"Risk-free rate","c":"Foundations","l":2,"mod":"INV-057","d":"The return on an investment treated as having no default risk over the period, usually short-term US Treasury bills.","u":"The baseline for excess returns and the Sharpe ratio.","m":"Any risky investment should, over time, be expected to beat this rate; otherwise the risk is not being rewarded.","a":[]},
{"t":"RMD aggregation","c":"Retirement","l":3,"mod":"INV-081","d":"The rule that lets you total the RMDs for all your IRAs and take the sum from any of them, and likewise among 403(b) contracts. Each 401(k) and 457(b) plan must pay its own RMD.","u":"Simplifying withdrawals and choosing which account to draw from.","m":"You cannot satisfy a 401(k) RMD from an IRA, and inherited accounts are calculated separately (IRS RMD FAQs).","a":[]},
{"t":"Robo-advisor","a":["robo-adviser","robo advisor","automated investment adviser"],"c":"Advice & regulation","l":1,"mod":"INV-104","d":"An automated investment manager, typically a registered investment adviser, that uses online algorithmic programs to build and manage portfolios from a client's questionnaire answers, often with automatic rebalancing and tax-loss harvesting.","u":"Low-cost, low-maintenance portfolio management.","m":"It is a fiduciary like any adviser. Check its fee, the cash share of its portfolios, and what its brochure says about the algorithm's assumptions."},
{"t":"Roll yield","a":["roll return","rolling futures"],"c":"Asset classes","l":2,"mod":"INV-013","d":"The gain or loss a futures investor earns by selling contracts that are about to expire and buying later ones. Negative in contango, positive in backwardation.","u":"Explaining why commodity funds' returns differ from the spot price of the commodity.","m":"A roll cost of 1% a month compounds to about 11% a year; check a fund's long-run record against the spot price before buying."},
{"t":"Romance scam","a":["confidence scam","confidence fraud"],"c":"Advice & regulation","l":1,"mod":"INV-062","d":"A fraud in which a criminal uses a fake online identity to build trust or a relationship and then asks for money.","u":"Recognizing a common route into investment fraud.","m":"Never send money or cryptocurrency to someone you know only online."},
{"t":"Roth catch-up rule","c":"Accounts","l":3,"mod":"INV-031","d":"A SECURE 2.0 requirement that catch-up contributions by participants whose prior-year FICA wages from the employer exceeded an indexed threshold be made as Roth contributions. For 2026 catch-ups the threshold is $150,000 of 2025 wages. It applies from 2026; final regulations generally apply from 2027.","u":"Workplace plans' treatment of higher earners' catch-ups.","m":"Your regular deferral can still be traditional; only the catch-up must be Roth.","a":[]},
{"t":"Roth conversion","c":"Taxes","l":2,"d":"Moving money from a traditional IRA or plan to a Roth account, paying ordinary income tax on the converted amount now.","u":"Filling low tax brackets; reducing future RMDs.","m":"Most useful in years when your tax rate is unusually low, such as early retirement."},
{"t":"Roth conversion ladder","c":"Retirement","l":3,"d":"Converting traditional retirement money to Roth each year, then withdrawing each conversion after five years.","u":"Early retirees accessing funds before 59½.","m":"Requires other money to live on for the first five years."},
{"t":"Roth five-year rules","a":["five-year rule"],"c":"Accounts","l":2,"mod":"INV-074","d":"Two separate clocks: one for qualified (tax-free) earnings, starting with your first Roth IRA contribution year; and one for each conversion, starting January 1 of the conversion year, that governs the 10% tax on converted amounts before 59½.","u":"Timing Roth withdrawals and conversion ladders.","m":"A conversion made anytime in 2026 can be withdrawn without the 10% tax from January 1, 2031."},
{"t":"Roth IRA","c":"Accounts","l":1,"d":"An IRA funded with after-tax dollars; qualified withdrawals, including growth, are tax-free, subject to a five-year rule and age 59½.","u":"Tax-free retirement income; flexibility in retirement tax planning.","m":"Direct contributions are limited by income; contributions (not earnings) can be withdrawn anytime."},
{"t":"Roth ordering rules","c":"Accounts","l":2,"mod":"INV-074","d":"The IRS order for a nonqualified Roth IRA withdrawal: regular contributions first, then conversions and rollovers oldest first (taxable part first), then earnings.","u":"Working out whether any part of an early Roth withdrawal is taxed or penalized.","m":"You can take back your own contributions at any age without tax or penalty.","a":[]},
{"t":"Rule of 25","a":["25x rule","25 times rule"],"c":"Retirement","l":1,"mod":"INV-075","d":"A target nest egg of 25 times the yearly amount you plan to withdraw from savings: the 4% withdrawal rate turned upside down (1 ÷ 0.04 = 25).","u":"Turning a yearly spending gap into a savings target in one step.","m":"Apply it to the gap after Social Security and pensions, not to your whole budget, and add taxes and fees; a lower withdrawal rate means a higher multiple."},
{"t":"Rule of 55","c":"Retirement","l":3,"d":"An exception allowing penalty-free withdrawals from a workplace plan if you leave that employer in or after the year you turn 55.","u":"Early retirement income.","m":"Applies to that employer's plan, not to IRAs."},
{"t":"Rule of 72","c":"Foundations","l":1,"mod":"INV-002","d":"A shortcut for doubling time: years ≈ 72 ÷ annual percentage rate.","u":"Quick mental estimates of growth, inflation, fees and debt.","m":"At 7%, money doubles about every 10 years; at 3% inflation, prices double about every 24."},
{"t":"Runway","c":"Planning","l":1,"mod":"INV-100","d":"The number of months a household's cash and benefits can cover essential spending after its income stops.","u":"Measuring how urgently to cut spending or find bridge income during a job loss or break.","m":"Runway = cushion ÷ (essential spending − benefits − other income). Knowing the number turns worry into a plan.","a":[]},
{"t":"S&P 500","c":"Markets","l":1,"d":"An index of about 500 large US companies, weighted by market capitalization, maintained by S&P Dow Jones Indices.","u":"The most common benchmark for US stocks.","m":"Covers most of the US market's value but not small companies or other countries."},
{"t":"Safe withdrawal rate","a":["4% rule"],"c":"Retirement","l":2,"d":"The share of a portfolio that can be withdrawn in the first year of retirement, then adjusted for inflation, with a high historical chance of lasting a set period. William Bengen's 1994 study found about 4% survived every 30-year US period he tested.","u":"Retirement income planning.","m":"A historical rule of thumb, not a guarantee; flexible spending can support more."},
{"t":"Sales load","a":["load","front-end load","back-end load"],"c":"Costs","l":2,"mod":"INV-007","d":"A sales charge on some mutual funds, taken at purchase (front-end) or sale (back-end).","u":"Compensating selling brokers.","m":"Many equivalent no-load funds exist."},
{"t":"SALT cap","a":["state and local tax deduction limit"],"c":"Taxes","l":2,"mod":"INV-041","d":"The federal limit on the itemized deduction for state and local taxes: $40,400 for 2026 under P.L. 119-21, reduced by 30% of modified AGI above $505,000 but not below $10,000, and returning to $10,000 from 2030.","u":"Knowing how much of your state and property taxes you can deduct.","m":"Only matters if you itemize."},
{"t":"SALT deduction cap","a":[],"c":"Taxes","l":2,"mod":"INV-068","d":"The limit on the itemized deduction for state and local income, sales and property taxes. P.L. 119-21 set it at $40,400 for 2026, reduced by 30% of modified AGI above $505,000 but not below $10,000.","u":"Figuring how much property tax on your own home you can deduct.","m":"Property tax on a rental is a rental expense on Schedule E rather than an itemized deduction."},
{"t":"Saver's credit","a":["retirement savings contributions credit"],"c":"Taxes","l":2,"mod":"INV-029","d":"A nonrefundable credit for retirement contributions by lower- and moderate-income workers. For 2026 it is available with AGI up to $80,500 (joint), $60,375 (head of household) or $40,250 (single).","u":"Rewarding retirement saving by people with modest incomes.","m":"It is on top of any deduction for the contribution itself."},
{"t":"Saving","c":"Foundations","l":1,"mod":"INV-001","d":"Setting money aside in forms that keep their dollar value and are easy to reach, such as bank accounts, money market funds and short CDs.","u":"Near-term spending and emergency reserves.","m":"The right home for money you will need within about three years; a poor home for money needed in 20."},
{"t":"Savings rate","c":"Planning","l":1,"mod":"INV-002","d":"The share of income saved and invested, usually as a percentage of gross or take-home pay.","u":"Measuring progress; driving financial-independence timelines.","m":"Early in a career, your savings rate matters far more than your investment return."},
{"t":"Secondary market","c":"Markets","l":2,"mod":"INV-005","d":"Where investors trade existing securities with each other; the issuer is not involved.","u":"Everyday trading on exchanges.","m":"Its liquidity is why you can sell a stock any trading day."},
{"t":"Section 1042 rollover","c":"Taxes","l":3,"mod":"INV-094","d":"An election to defer capital gain on selling stock of a domestic C corporation with no publicly traded stock to an ESOP that owns at least 30% after the sale, if the seller held the shares 3 years and reinvests in qualified replacement securities within 3 months before to 12 months after the sale.","u":"Tax-deferred exit for owners selling to employees.","m":"The deferred gain carries into the replacement securities' basis, and may be erased by a step-up if they are held until death.","a":[]},
{"t":"Section 1245 property","c":"Taxes","l":3,"mod":"INV-068","d":"Depreciable personal property such as appliances, carpets and furniture, as opposed to buildings (section 1250 property).","u":"Determining how depreciation is recaptured at sale: gain on 1245 property is ordinary income up to the depreciation taken.","m":"Items moved into 5- or 7-year classes by cost segregation are recaptured at your full ordinary rate, with no 25% cap.","a":[]},
{"t":"Section 1256 contract","a":["60/40 rule","mark-to-market rule"],"c":"Taxes","l":3,"mod":"INV-013","d":"A tax category that includes regulated futures contracts and nonequity options such as options on broad-based stock indexes. Positions held at year-end are treated as sold at fair market value, and gains or losses are treated as 60% long-term and 40% short-term regardless of holding period.","u":"Taxing futures, commodity funds that hold futures, and index options such as those on the S&P 500.","m":"You can owe tax on a futures gain you have not closed. The 60/40 split can lower the rate compared with ordinary short-term gains."},
{"t":"Section 6166 deferral","c":"Estate","l":3,"mod":"INV-094","d":"An election letting an estate pay the estate tax attributable to a closely held business worth more than 35% of the adjusted gross estate in up to 10 annual installments, starting up to 5 years after the due date, with 2% interest on the first part.","u":"Avoiding a forced sale of a family business to pay estate tax within nine months.","m":"Selling or withdrawing half or more of the business can accelerate the remaining tax.","a":[]},
{"t":"Section 7520 rate","c":"Estate","l":3,"mod":"INV-093","d":"The monthly IRS interest rate used to value annuities, life estates, remainders and similar split interests. 5.6% for October 2026.","u":"Calculating deductions for charitable trusts and the taxable value of gifts to lead trusts and similar arrangements.","m":"Lower rates make lead trusts more attractive, because the charity's annuity is valued higher and the taxable remainder lower.","a":[]},
{"t":"Secular bear market","c":"Markets","l":3,"mod":"INV-061","d":"A long stretch, often a decade or more, in which stock prices make little net progress despite rallies, such as 1966–1982 or 2000–2012 for US prices.","u":"Describing long periods of poor returns, as opposed to a single sharp fall.","m":"Dividends, rebalancing and continued saving matter most in these periods.","a":[]},
{"t":"Securities and Exchange Commission","a":["SEC"],"c":"Advice & regulation","l":1,"mod":"INV-103","d":"The federal agency that regulates securities markets, public companies' disclosures, broker-dealers and larger investment advisers.","u":"Rulemaking (such as Regulation Best Interest and Form CRS), examinations and enforcement.","m":"Its free Investor.gov and IAPD sites let you check firms and professionals before you invest."},
{"t":"Security deposit","c":"Real estate","l":1,"mod":"INV-067","d":"Money a tenant pays at move-in that the landlord holds against unpaid rent or damage beyond normal wear and tear, returned under rules set by state law.","u":"Protecting a landlord against losses at the end of a lease.","m":"States cap the amount and set deadlines for returning it with an itemized list. Missing the deadline can cost you more than the deposit.","a":[]},
{"t":"See-through trust","c":"Estate","l":3,"mod":"INV-091","d":"A trust named as a retirement-account beneficiary that meets the IRS requirements (valid under state law, irrevocable at death, identifiable beneficiaries, documentation to the custodian) so its beneficiaries are treated as designated beneficiaries.","u":"Controlling inherited retirement money for minors, spendthrifts or people with special needs.","m":"Drafting matters: a trust that keeps withdrawals inside can pay the top 37% rate above a low threshold.","a":[]},
{"t":"Segment rates","a":["417(e) rates","minimum present value segment rates"],"c":"Retirement","l":3,"mod":"INV-080","d":"Three interest rates the IRS publishes monthly from high-quality corporate bond yields, for payments due within 5 years, from 5 to 20 years, and after 20 years (26 U.S.C. §430(h)(2)).","u":"Computing the minimum lump sum a pension plan must pay under IRC section 417(e); plans use a set lookback month and stability period.","m":"When these rates rise, lump sums fall. For May 2026 they were 4.42%, 5.47% and 6.31%."},
{"t":"Self-custody","a":["hardware wallet","cold storage","non-custodial wallet"],"c":"Asset classes","l":2,"mod":"INV-015","d":"Holding the private keys to your own crypto assets, for example in a hardware wallet, instead of leaving them with an exchange or other custodian.","u":"Removing the risk that an exchange fails or freezes withdrawals.","m":"You trade counterparty risk for personal-error risk: theft, loss and inheritance planning all become your job."},
{"t":"Self-employed health insurance deduction","a":["Form 7206"],"c":"Taxes","l":2,"mod":"INV-101","d":"A deduction for medical, dental, vision and qualified long-term care premiums paid by a self-employed person for themselves, a spouse, dependents and a child under 27, limited by the business's earnings. It is not allowed for months the person was eligible for an employer-subsidized plan, including a spouse's.","u":"Giving the self-employed a tax break similar to employer-paid coverage.","m":"Check eligibility for a spouse's employer plan before claiming it."},
{"t":"Self-employment tax","a":["SE tax"],"c":"Taxes","l":1,"mod":"INV-101","d":"Social Security and Medicare tax for the self-employed: 12.4% plus 2.9%, applied to 92.35% of net profit, owed when net earnings are $400 or more. The Social Security part stops at the wage base ($184,500 for 2026).","u":"Funding Social Security and Medicare benefits for people who work for themselves.","m":"It is owed on top of income tax; half of it is deductible when figuring adjusted gross income."},
{"t":"Self-proved will","a":["self-proving affidavit"],"c":"Estate","l":2,"mod":"INV-086","d":"A will signed with notarized affidavits of the testator and witnesses, so the court can accept it without the witnesses testifying (in Pennsylvania, 20 Pa.C.S. 3132.1).","u":"Speeding up the start of probate.","m":"A small step at signing that saves the executor time and trouble later."},
{"t":"Self-sufficiency test","c":"Real estate","l":3,"mod":"INV-070","d":"An FHA rule for three- and four-unit properties: the monthly principal, interest, taxes and insurance, divided by fair market rent for all units minus the greater of the vacancy estimate or 25%, may not exceed 100%.","u":"Making sure a small multifamily building bought with FHA can largely carry itself.","m":"A fourplex whose payment is 109% of net rent would not qualify without a larger down payment or higher rents.","a":[]},
{"t":"Semi-retirement","c":"Independence","l":1,"mod":"INV-073","d":"Leaving full-time work for part-time or seasonal work that covers some living costs.","u":"Barista FI and other partial-independence plans.","m":"Even modest earnings in the first years reduce withdrawals when a market fall would do the most damage.","a":[]},
{"t":"Semi-strong-form efficiency","a":["semi-strong form"],"c":"Strategies","l":2,"mod":"INV-043","d":"The version of the efficient market hypothesis in which prices adjust quickly and without bias to all public information, such as earnings, news and filings.","u":"Event studies that measure how fast prices react to announcements.","m":"Reading public news rarely gives you an edge; the price has usually moved already."},
{"t":"Senior deduction","a":["OBBBA senior deduction","deduction for seniors"],"c":"Taxes","l":2,"mod":"INV-081","d":"A deduction of $6,000 per person age 65 or older for 2025 through 2028, reduced by 6% of modified adjusted gross income over $75,000 ($150,000 joint), added by the One Big Beautiful Bill Act (IRC §151(d)(5)(C)).","u":"Lowering taxable income for older taxpayers, whether or not they itemize, on top of the regular additional standard deduction for age 65+.","m":"It expires after 2028 under current law, making 2026 to 2028 unusually good years for Roth conversions for people over 65."},
{"t":"SEP IRA","c":"Accounts","l":3,"d":"A simplified employer pension: an IRA funded by employer contributions, popular with the self-employed.","u":"Easy retirement saving for small businesses.","m":"Contributions are a percentage of compensation."},
{"t":"Separate property","a":["commingling"],"c":"Planning","l":2,"mod":"INV-095","d":"Property that belongs to one spouse alone, typically what they owned before marriage and gifts or inheritances they received. Mixing it with marital money, called commingling, can make it marital.","u":"Keeping premarital or inherited assets out of a divorce division.","m":"Keep inherited money in an account in your own name and keep records that trace it."},
{"t":"Separation from service","c":"Retirement","l":3,"mod":"INV-074","d":"Ending employment with the employer that sponsors a retirement plan.","u":"Triggering the Rule of 55 (separation during or after the year you turn 55) and allowing 72(t) payments from that plan.","m":"The exception follows the employer you leave: a plan left behind at an earlier employer before the year you turned 55 is not covered.","a":[]},
{"t":"Sequence-of-returns risk","a":["sequence risk"],"c":"Retirement","l":2,"mod":"INV-003","d":"The danger that poor returns early in retirement, while withdrawals are being taken, permanently reduce how long a portfolio lasts.","u":"Retirement income planning.","m":"A few years of withdrawals held in safe assets reduce forced selling in a crash."},
{"t":"Settlement","a":["T+1"],"c":"Markets","l":2,"mod":"INV-005","d":"The actual exchange of cash and securities after a trade. The US standard for most securities has been one business day after the trade (T+1) since May 28, 2024.","u":"Knowing when you own shares and when cash is available.","m":"Sale proceeds settle the next business day."},
{"t":"Seven-day yield","a":["7-day yield"],"c":"Vehicles","l":2,"mod":"INV-008","d":"The standard yield quoted for money market funds: an annualized figure based on the fund's income over the most recent seven days, after expenses.","u":"Comparing money market funds with each other and with savings rates.","m":"It changes daily with short-term interest rates. Compare it with savings APYs and T-bill yields, remembering the tax differences."},
{"t":"Severance pay","a":["severance"],"c":"Planning","l":1,"mod":"INV-100","d":"Money an employer pays when a job ends, often a set number of weeks of pay, usually in exchange for a release of legal claims. It is wages subject to income tax withholding and Social Security and Medicare taxes (IRS Publication 525).","u":"Bridging the gap to the next job.","m":"Plan around the amount after withholding, and read the release before signing."},
{"t":"Share buyback","a":["stock repurchase"],"c":"Companies","l":2,"mod":"INV-006","d":"A company buying its own shares, reducing the number outstanding.","u":"Returning cash to shareholders besides dividends.","m":"Raises each remaining share's claim on profits; value depends on the price paid."},
{"t":"Share class","c":"Vehicles","l":3,"d":"Different versions of the same mutual fund with different fees and loads, such as Class A, C, I or Admiral.","u":"Distribution through different channels.","m":"The same portfolio can cost very different amounts depending on the share class."},
{"t":"Share repurchase plan","a":["redemption plan"],"c":"Vehicles","l":3,"mod":"INV-069","d":"The program through which a non-traded REIT buys back shares from investors, typically subject to monthly and quarterly limits as a percentage of net asset value that the board can change or suspend.","u":"Providing limited liquidity for shares that do not trade.","m":"In November 2022, one large non-traded REIT hit its 2% monthly limit and paid out only about 43% of the shares submitted."},
{"t":"Shareholder engagement","a":["stewardship","proxy voting"],"c":"Strategies","l":2,"mod":"INV-053","d":"Using the rights of share ownership, such as voting at annual meetings and meeting with management, to influence how a company is run.","u":"Seeking change from inside rather than by selling shares.","m":"Your fund's manager votes the shares it holds for you; its voting policy is part of what you choose."},
{"t":"Sharpe ratio","c":"Foundations","l":3,"mod":"INV-003","d":"Excess return over the risk-free rate divided by volatility: (R − Rf) ÷ σ.","u":"Comparing reward per unit of volatility across investments.","m":"Useful for comparisons; shares all the limitations of volatility as a risk measure."},
{"t":"Short selling","a":["short sale","shorting"],"c":"Markets","l":3,"mod":"INV-005","d":"Borrowing shares and selling them, planning to buy them back later at a lower price.","u":"Betting on a decline; hedging.","m":"Losses are theoretically unlimited because a price can keep rising."},
{"t":"Short-term capital gain","c":"Taxes","l":1,"d":"A gain on an asset held one year or less, taxed as ordinary income.","u":"Tax planning for sales.","m":"Holding just past one year can cut the tax substantially."},
{"t":"Short-term rental","a":["STR","vacation rental"],"c":"Real estate","l":1,"mod":"INV-070","d":"Renting a furnished home or room for short stays, typically by the night through a booking platform.","u":"Earning more rent per night than a lease, at the cost of more work, costs and regulation.","m":"Check your city's rules first: some allow it only in your primary residence or with the host present."},
{"t":"SIM swap","a":["SIM swapping"],"c":"Behavior","l":2,"mod":"INV-104","d":"A fraud in which a criminal takes over your mobile phone number, so that calls and text-message security codes go to the criminal instead of you.","u":"Defeating text-message security codes in account takeovers.","m":"Ask your phone carrier about extra account protection, and use an authenticator app or security key for financial logins."},
{"t":"Simple Dietz method","a":["modified Dietz method","Dietz method"],"c":"Portfolio","l":3,"mod":"INV-057","d":"An approximation of a money-weighted return that divides the investment gain by the beginning value plus half of the net cash flows (simple Dietz) or plus each flow weighted by the time it was invested (modified Dietz).","u":"Estimating your own return from a statement's beginning value, deposits and ending value.","m":"(End - Begin - Net flows) / (Begin + half of net flows) gets you close enough to judge a year."},
{"t":"Simple interest","c":"Foundations","l":1,"mod":"INV-002","d":"Interest paid only on the original principal, never on accumulated interest.","u":"Some short loans and bonds that pay out interest rather than reinvesting it.","m":"The contrast with compound interest shows how much reinvesting adds over long periods."},
{"t":"SIMPLE IRA","c":"Accounts","l":3,"d":"A retirement plan for small employers combining employee deferrals with required employer contributions.","u":"Small-business retirement plans.","m":"Early withdrawals within the first two years face a higher additional tax."},
{"t":"Single Life Table","c":"Retirement","l":3,"mod":"INV-091","d":"The IRS table of single life expectancies by age (Table I in Publication 590-B) used to calculate beneficiaries' required minimum distributions.","u":"The divisor for an inherited account's annual minimum: the table value in the first year, then reduced by one each year.","m":"A 50-year-old beneficiary's first divisor is 36.2, so the first minimum is about 2.8% of the balance.","a":[]},
{"t":"Single-life annuity","a":["straight-life annuity","life-only annuity"],"c":"Retirement","l":1,"mod":"INV-080","d":"Income paid for one person's life only, stopping at death, with nothing for a survivor or heirs.","u":"Providing the largest possible monthly payment from a pension or annuity purchase.","m":"Right for single people or when a spouse has ample income of their own; risky if a spouse would depend on it."},
{"t":"Sinking fund","c":"Planning","l":1,"mod":"INV-024","d":"Money set aside in regular amounts for a specific, expected future expense such as a car, a roof, property taxes or tuition.","u":"Turning a large known bill into small monthly amounts so it never becomes an emergency or a debt.","m":"Keep it separate from the emergency fund, which is for surprises, not for bills you can see coming.","a":[]},
{"t":"SIPC","a":["Securities Investor Protection Corporation"],"c":"Markets","l":1,"mod":"INV-005","d":"A nonprofit membership corporation that restores missing customer cash and securities when a member brokerage fails, up to $500,000 per customer including $250,000 of cash.","u":"Protection against broker failure.","m":"It does not protect against investment losses or bad advice."},
{"t":"Size premium","a":["SMB","small minus big","small-cap premium"],"c":"Strategies","l":2,"mod":"INV-048","d":"The extra average return of small companies over large ones; Fama and French's SMB factor.","u":"Explaining small-company fund behavior and designing small-cap tilts.","m":"In US data it averaged about 4.7% a year from 1927 to 1981 and about zero since 1982."},
{"t":"Skilled nursing facility","a":["SNF"],"c":"Retirement","l":2,"mod":"INV-083","d":"A facility that provides daily skilled nursing or therapy. Medicare Part A covers a stay after a qualifying 3-day inpatient hospital stay, up to 100 days per benefit period.","u":"Short-term recovery care. In 2026 patients pay $0 for days 1 to 20 (after the Part A deductible) and $217 a day for days 21 to 100.","m":"Coverage ends when skilled care is no longer needed, even if you still need help with daily living."},
{"t":"Skip person","c":"Estate","l":3,"mod":"INV-088","d":"For the GST tax, a person two or more generations below the transferor (such as a grandchild), or an unrelated person born more than 37 and a half years after the transferor, or a trust held only for such people.","u":"Deciding whether a gift or bequest is subject to the GST tax.","m":"If your child has died, their children generally move up a generation and are not skip persons for your gifts.","a":[]},
{"t":"Small estate affidavit","a":["small estate procedure","collection by affidavit"],"c":"Estate","l":1,"mod":"INV-086","d":"A simplified way for heirs to collect a small estate without full probate, by sworn statement or short petition, when the probate property is below a state limit.","u":"Estates whose probate property is small, often after a waiting period.","m":"Limits differ widely: in 2026, $20,000 of personal property in North Carolina, $50,000 in Pennsylvania (excluding real estate) and $200,000 in Arizona."},
{"t":"SMART goal","c":"Planning","l":1,"mod":"INV-024","d":"A goal that is Specific, Measurable, Assignable, Realistic and Time-related, the test proposed by George Doran in 1981. Later versions often use Achievable and Relevant.","u":"Turning a wish such as 'save for college' into an amount, a date and a monthly action.","m":"If you cannot write down the amount and the date, you cannot choose an account or an investment for the goal.","a":[]},
{"t":"Social Security","c":"Retirement","l":1,"d":"The federal program paying retirement, disability, spousal and survivor benefits based on a worker's earnings record.","u":"The foundation of most retirement incomes.","m":"Inflation-adjusted lifetime income; claiming age changes the amount permanently."},
{"t":"Social Security credits","a":["quarter of coverage","quarters of coverage","work credits"],"c":"Retirement","l":2,"mod":"INV-078","d":"Units earned by working and paying Social Security tax; in 2026 you earn one credit for each $1,890 of earnings, up to four a year.","u":"Qualifying for benefits: people born in 1929 or later need 40 credits for a retirement benefit, and 40 quarters also give premium-free Medicare Part A.","m":"Credits decide whether you qualify; the amount of the benefit comes from your earnings, not your credits."},
{"t":"Social Security Fairness Act","c":"Retirement","l":2,"mod":"INV-078","d":"A federal law signed January 5, 2025, that repealed the Windfall Elimination Provision and Government Pension Offset for benefits payable after December 2023.","u":"Restoring benefits for over 2.8 million people with non-covered pensions; SSA sent over 3.1 million retroactive payments totaling $17 billion by July 2025.","m":"If you have a pension from non-covered work, check your benefit estimate again.","a":[]},
{"t":"Social Security trust funds","a":["OASI Trust Fund","OASDI","Trustees Report"],"c":"Retirement","l":2,"mod":"INV-078","d":"The Old-Age and Survivors Insurance and Disability Insurance funds that hold Social Security's reserves. The 2026 Trustees Report projects OASI depletion in late 2032 (78% of scheduled benefits payable afterward) and combined OASDI depletion in 2034 (83%).","u":"Measuring the program's long-range finances.","m":"Depletion would mean reduced benefits, not zero; test your plan at about 80% of scheduled benefits."},
{"t":"Social Security wage base","a":["taxable maximum","wage base"],"c":"Taxes","l":2,"mod":"INV-101","d":"The yearly maximum of wages and self-employment earnings subject to the 12.4% Social Security tax: $184,500 for 2026 (SSA).","u":"Capping Social Security payroll and self-employment tax, and the earnings that count toward benefits.","m":"W-2 wages and self-employment earnings share one wage base; Medicare tax has no cap."},
{"t":"Soft inquiry","a":["soft pull"],"c":"Planning","l":2,"mod":"INV-021","d":"A check of your credit that is not tied to an application, such as checking your own score or a lender's pre-screened offer.","u":"Monitoring credit without affecting it.","m":"Checking your own credit never lowers your FICO Score."},
{"t":"Solo 401(k)","a":["individual 401(k)"],"c":"Accounts","l":3,"d":"A 401(k) for a self-employed person with no employees other than a spouse.","u":"High contribution capacity for the self-employed.","m":"You contribute as both employee and employer."},
{"t":"Sortino ratio","c":"Portfolio","l":3,"mod":"INV-057","d":"Average excess return over a minimum acceptable return (often the Treasury bill rate) divided by the downside deviation, which counts only shortfalls. Introduced by Sortino and Price (1994).","u":"Judging return per unit of downside risk, for strategies whose ups and downs are lopsided.","m":"Of two portfolios with the same Sharpe ratio, the one with the higher Sortino ratio earned its return with fewer and smaller bad periods.","a":[]},
{"t":"Special Enrollment Period","c":"Insurance","l":2,"mod":"INV-100","d":"A window outside annual Open Enrollment, usually 60 days, in which a qualifying life event such as losing job-based coverage lets you enroll in a Marketplace health plan (HealthCare.gov).","u":"Getting individual coverage after a job loss, move, marriage or birth.","m":"Mark the 60-day deadline the day coverage ends.","a":[]},
{"t":"Special needs trust","a":["supplemental needs trust"],"c":"Estate","l":3,"d":"A trust that holds assets for a person with a disability without disqualifying them from means-tested benefits.","u":"Planning for a disabled child or relative.","m":"Leaving money outright can cost a beneficiary essential benefits."},
{"t":"Special-use valuation","a":["section 2032A"],"c":"Estate","l":3,"mod":"INV-094","d":"An estate-tax election to value qualifying farm or closely held business real estate at its current use instead of its highest-and-best-use value, reducing the estate by up to $1,460,000 for 2026 deaths (IRC 2032A).","u":"Helping families keep farms and business real estate that would otherwise have to be sold to pay estate tax.","m":"Heirs must keep the qualified use for 10 years, or an additional estate tax recaptures the saving."},
{"t":"Specific identification","a":["specific lot identification"],"c":"Taxes","l":3,"d":"Choosing which tax lots of a security to sell, rather than first-in, first-out.","u":"Controlling realized gains and losses.","m":"Selling the highest-cost lots first often minimizes tax."},
{"t":"Specified service trade or business","a":["SSTB"],"c":"Taxes","l":3,"mod":"INV-101","d":"A category of service business, defined in section 199A, whose income stops qualifying for the QBI deduction once taxable income is above the phase-in range (Instructions for Form 8995).","u":"Limiting the QBI deduction for high-income service professionals.","m":"Below the 2026 threshold the category does not matter; within the phase-in range the deduction is partly allowed."},
{"t":"Speculation","c":"Foundations","l":1,"mod":"INV-001","d":"Buying mainly in the hope that someone will soon pay a higher price, rather than for the income or growth the asset produces.","u":"Short-term trading, chasing fast-rising assets.","m":"Results depend on predicting others' behavior; belongs only with money you can afford to lose."},
{"t":"Spend-down","a":["Medicaid spend-down"],"c":"Retirement","l":2,"mod":"INV-083","d":"Using up income and assets on care and allowed expenses until you meet Medicaid's financial eligibility limits.","u":"The common path from paying privately for long-term care to Medicaid coverage.","m":"A community spouse can keep a protected amount; for 2026 the resource standard runs from $32,532 to $162,660 depending on the state (CMS)."},
{"t":"Spendthrift provision","a":["spendthrift trust","spendthrift clause"],"c":"Estate","l":2,"mod":"INV-087","d":"A trust clause that stops a beneficiary from selling or pledging their interest and stops most of their creditors from reaching it before distribution.","u":"Protecting heirs with debts, addictions, unstable marriages or little money experience.","m":"It protects a beneficiary's inheritance, not your own money: you generally cannot shelter your own assets from your own creditors in a trust for yourself. Child-support claims can often override it."},
{"t":"SPIVA","c":"Strategies","l":2,"d":"S&P Dow Jones Indices' regular scorecards comparing actively managed funds with their benchmark indexes.","u":"Measuring how often active managers beat their benchmarks.","m":"Over long horizons, most active funds in most categories have underperformed."},
{"t":"Spot bitcoin ETP","a":["spot bitcoin ETF","bitcoin ETF"],"c":"Vehicles","l":2,"mod":"INV-015","d":"An exchange-traded product that holds bitcoin itself, through a custodian, rather than futures. The SEC approved the listing and trading of the first spot bitcoin ETP shares on January 10, 2024.","u":"Owning bitcoin exposure in an ordinary brokerage account or IRA.","m":"It solves custody for you and reports taxes on a normal form, but it is still bitcoin: just as volatile. The SEC stated it did not approve or endorse bitcoin."},
{"t":"Spousal benefit","c":"Retirement","l":2,"d":"A Social Security benefit of up to 50% of a spouse's primary insurance amount, reduced if claimed before full retirement age.","u":"Income for lower-earning or non-working spouses.","m":"Does not earn delayed retirement credits beyond FRA."},
{"t":"Spousal consent","c":"Estate","l":2,"mod":"INV-059","d":"A spouse's written agreement, witnessed by a plan representative or notary, that is generally required before a married participant in a 401(k)-type plan can name someone other than the spouse as beneficiary or waive survivor benefits.","u":"Protecting spouses' rights in workplace retirement plans under federal law.","m":"If you are married and want to name your children on a 401(k), your spouse must sign. IRAs follow different, state-influenced rules.","a":[]},
{"t":"Spousal impoverishment rules","a":["community spouse resource allowance","CSRA"],"c":"Retirement","l":3,"mod":"INV-097","d":"Federal Medicaid rules that let the spouse of a nursing home resident keep part of the couple's assets and income.","u":"Preventing the healthy spouse from being left without resources.","m":"For 2026 the community spouse resource allowance is at least $32,532 and at most $162,660, depending on the state."},
{"t":"Spousal IRA","a":["Kay Bailey Hutchison Spousal IRA"],"c":"Accounts","l":2,"mod":"INV-027","d":"A traditional or Roth IRA for a spouse with little or no pay, funded on the strength of the other spouse's taxable compensation when the couple files a joint return.","u":"Letting a non-earning spouse keep saving for retirement in their own name.","m":"For 2026 each spouse can contribute up to $7,500 ($8,600 at 50+), as long as the couple's total does not exceed the compensation on the joint return."},
{"t":"Spousal rollover","a":["treat as own"],"c":"Retirement","l":2,"mod":"INV-091","d":"A surviving spouse's option to treat an inherited IRA as their own, by retitling it or rolling it into their own IRA or plan.","u":"Delaying required distributions to the spouse's own required age and naming new beneficiaries.","m":"Spouses under 59½ who need the money often stay a beneficiary first, because beneficiary withdrawals avoid the 10% early-withdrawal tax."},
{"t":"Stablecoin","c":"Asset classes","l":3,"d":"A crypto asset designed to hold a stable value, usually one US dollar, backed by reserves or mechanisms.","u":"Trading and payments within crypto markets.","m":"Not FDIC-insured or SIPC-protected; depends on the issuer's reserves."},
{"t":"Standard deduction","c":"Taxes","l":1,"d":"A fixed amount that reduces taxable income for taxpayers who do not itemize.","u":"Most households use it instead of itemizing.","m":"Bunching deductions into alternate years can make itemizing worthwhile."},
{"t":"Standard deviation","c":"Foundations","l":2,"mod":"INV-003","d":"A statistical measure of how widely values spread around their average. For bell-shaped returns, about two-thirds fall within one standard deviation.","u":"Quantifying volatility.","m":"US stocks' annual standard deviation was about 19% around an average of about 12% (1928–2025)."},
{"t":"State guaranty association","a":["guaranty association","life and health insurance guaranty association"],"c":"Insurance","l":2,"mod":"INV-017","d":"A state organization, funded by assessments on member insurers, that continues coverage up to legal limits when a life or annuity insurer fails. Most states cover at least $250,000 in present value of annuity benefits and $300,000 of life insurance death benefits (NOLHGA).","u":"Backstopping insurance and annuity promises after an insurer's liquidation.","m":"It is not a government guarantee like FDIC insurance, and limits vary by state; spread large annuity purchases across strong insurers."},
{"t":"State income tax","c":"Taxes","l":2,"d":"Income tax levied by a state; rates and rules vary widely, and several states have no broad income tax.","u":"Relocation and retirement planning.","m":"Some states tax retirement income or Social Security differently from others."},
{"t":"State securities regulator","c":"Advice & regulation","l":2,"mod":"INV-103","d":"The securities agency of each state, which registers and oversees smaller investment advisers.","u":"Oversight of local advisory firms and investor complaints.","m":"If a small local adviser is not on the SEC's register, it is probably registered with your state; you can also report problems there.","a":[]},
{"t":"Status quo bias","c":"Behavior","l":2,"mod":"INV-060","d":"A preference for leaving things as they are, even when a change would be better.","u":"Explaining why default choices in retirement plans are so powerful.","m":"Useful when the default is good (automatic saving); harmful when it is not (an old, expensive fund).","a":[]},
{"t":"Statutory resident","c":"Taxes","l":3,"mod":"INV-041","d":"Someone domiciled elsewhere whom a state taxes as a resident, typically because they keep a permanent home there and spend more than a set number of days (183 in Pennsylvania) in the state.","u":"Taxing people with homes in two states.","m":"Snowbirds should count days and keep records.","a":[]},
{"t":"Step-up in basis","c":"Estate","l":2,"d":"The reset of an inherited asset's cost basis to its value at the owner's death.","u":"Reducing capital gains tax for heirs.","m":"Holding appreciated assets until death, rather than gifting them, can erase the gain for heirs."},
{"t":"Stock","a":["equity","share"],"c":"Asset classes","l":1,"mod":"INV-001","d":"A unit of ownership in a company, entitling the holder to a share of its profits and value.","u":"Long-term growth.","m":"Stocks have been the main engine of long-run growth, with the largest swings."},
{"t":"Stop order","a":["stop-loss order"],"c":"Markets","l":2,"mod":"INV-005","d":"An order that becomes a market order once a specified stop price is reached.","u":"Limiting losses or protecting gains.","m":"In a gap or fast market the fill can be far below the stop."},
{"t":"Stop-limit order","c":"Markets","l":2,"mod":"INV-005","d":"An order that becomes a limit order once a stop price is reached.","u":"Avoiding fills below a chosen price.","m":"May not fill at all if the price falls straight through the limit."},
{"t":"Strategic asset allocation","a":["policy portfolio","target allocation"],"c":"Portfolio","l":2,"mod":"INV-028","d":"The long-term target percentages for each asset class, set from goals and risk profile and changed only when circumstances change.","u":"Anchoring contributions, rebalancing and withdrawals to one agreed mix.","m":"Write it into your investment policy statement; a market move is not a reason to change it."},
{"t":"Stress test","c":"Portfolio","l":2,"mod":"INV-025","d":"Applying a severe historical or hypothetical decline to a plan to see whether its goals still hold.","u":"Measuring risk capacity: whether you could afford a loss, not just whether you could stand it.","m":"If a 1929 or 2008-sized fall at the start would break your essential goals, the mix is beyond your capacity.","a":[]},
{"t":"Strike price","a":["exercise price"],"c":"Asset classes","l":2,"mod":"INV-016","d":"The price at which an option holder may buy (call) or sell (put) the underlying asset.","u":"Defining an option's payoff; with the premium, it sets the breakeven price.","m":"The farther the strike from today's price, the cheaper the option and the less likely it is to pay off."},
{"t":"STRIPS","a":["Treasury STRIPS"],"c":"Asset classes","l":3,"mod":"INV-010","d":"Separate Trading of Registered Interest and Principal of Securities: zero-coupon securities created by separating a Treasury note's or bond's individual interest and principal payments.","u":"Buying a single, certain Treasury payment on a specific future date.","m":"Useful for matching a known future expense; very sensitive to interest rates before maturity."},
{"t":"Strong-form efficiency","a":["strong form"],"c":"Strategies","l":3,"mod":"INV-043","d":"The version of the efficient market hypothesis in which prices reflect all information, public and private. Evidence rejects it: insiders do know more.","u":"The theoretical upper bound of efficiency.","m":"Trading on material non-public information can be illegal. The one reliable edge is one you may not use."},
{"t":"Student Aid Index","a":["SAI"],"c":"Planning","l":2,"mod":"INV-096","d":"The number the FAFSA produces to measure a family's financial strength. It replaced the Expected Family Contribution and can be as low as negative $1,500.","u":"Need-based aid: financial need equals cost of attendance minus the SAI minus other aid.","m":"Income counts far more than savings. A parent-owned dollar, including a 529 for a dependent student, raises it by at most about 5.6 cents; a student-owned dollar by 20 cents."},
{"t":"Student loan interest deduction","c":"Taxes","l":2,"mod":"INV-020","d":"A deduction of up to $2,500 a year of interest paid on qualified education loans, available without itemizing and phased out at higher incomes.","u":"Lowering the after-tax cost of student debt.","m":"For a borrower in the 12% bracket, a 6.8% loan costs about 5.98% after tax, as long as interest stays within the limit.","a":[]},
{"t":"Style drift","a":[],"c":"Portfolio","l":2,"mod":"INV-045","d":"A fund moving away from the kind of securities it was sold to hold, such as a small-value fund buying larger or growthier stocks.","u":"Checking whether a fund still fills its slot in your allocation.","m":"Drift can flatter a record and quietly change your overall mix. SPIVA reports style consistency by category."},
{"t":"Sub-asset allocation","c":"Portfolio","l":2,"mod":"INV-055","d":"The split within each asset class, such as US versus international stocks, or Treasuries versus corporate bonds versus TIPS.","u":"Finishing an allocation after the stock/bond ratio is set.","m":"Decide it once, write it down, and rebalance to it like the main allocation.","a":[]},
{"t":"Subsidy cliff","a":["400% cliff"],"c":"Insurance","l":2,"mod":"INV-074","d":"The point, 400% of the federal poverty line, above which marketplace premium credits stop entirely under the rules in force for 2026.","u":"Managing income in early retirement.","m":"One extra dollar of income can cost the whole credit, often many thousands of dollars. Roth conversions and capital gains count toward income."},
{"t":"Substantially identical","c":"Taxes","l":3,"mod":"INV-037","d":"The wash-sale test for whether a replacement security is too similar to the one sold at a loss; the IRS says to weigh all the facts and circumstances.","u":"Choosing a replacement when harvesting a loss.","m":"Another company's stock ordinarily is not; two funds tracking the same index are a gray area.","a":[]},
{"t":"Success rate","a":["portfolio success rate","probability of success"],"c":"Retirement","l":2,"mod":"INV-076","d":"The share of historical periods, or simulated paths, in which a withdrawal plan paid every planned withdrawal to the end of its horizon.","u":"Summarizing backtests such as the Trinity study and Monte Carlo simulations.","m":"It counts failures but not how bad they are, and it assumes you never adjust spending; compare assumptions before comparing numbers."},
{"t":"Successor trustee","c":"Estate","l":1,"mod":"INV-087","d":"The person or institution named to take over as trustee when the current trustee dies, resigns or becomes incapacitated.","u":"Managing a living trust's assets without a court if the grantor becomes incapacitated, and settling the trust after death.","m":"This is what makes a revocable trust useful for incapacity planning. Tell the person, and name an alternate.","a":[]},
{"t":"Suitability","c":"Advice & regulation","l":2,"mod":"INV-025","d":"The FINRA rule (Rule 2111) that a broker must have a reasonable basis to believe a recommendation fits the customer's investment profile, including age, financial situation, time horizon, liquidity needs and risk tolerance.","u":"Setting a minimum standard for recommendations; retail recommendations are also subject to the SEC's Regulation Best Interest.","m":"The questions a broker asks about you are required for a reason; answer them accurately and ask how the recommendation fits.","a":[]},
{"t":"Summary prospectus","c":"Vehicles","l":2,"mod":"INV-012","d":"A short version of a fund's prospectus with its key facts, including its objective, fee table, principal risks and performance.","u":"Comparing funds quickly before reading the full prospectus.","m":"The fee table near the front shows what $10,000 would cost over 1, 3, 5 and 10 years.","a":[]},
{"t":"Sunk cost fallacy","a":["sunk cost"],"c":"Behavior","l":2,"mod":"INV-060","d":"Letting money already spent, which cannot be recovered, influence a decision about the future.","u":"Explaining why investors hold a losing position 'to get back to even'.","m":"Ask only whether you would buy the investment today at today's price."},
{"t":"Superfunding","a":["five-year gift election"],"c":"Estate","l":3,"mod":"INV-034","d":"Electing to treat a large 529 contribution as if made evenly over five years for gift-tax purposes, so up to five times the annual exclusion ($95,000 per donor per beneficiary at the 2026 exclusion of $19,000) can go in at once.","u":"Front-loading education savings, often by grandparents.","m":"It requires a gift tax return, and part returns to the donor's estate if they die within five years."},
{"t":"Supplemental Security Income","a":["SSI"],"c":"Retirement","l":1,"mod":"INV-102","d":"A needs-based federal program run by SSA that pays a monthly benefit to people who are aged, blind or disabled with very limited income and resources. For 2026 the maximum federal payment is $994 a month for an individual and $1,491 for a couple.","u":"Basic income for food and shelter; in most states it also brings Medicaid eligibility.","m":"Countable resources must stay at or below $2,000 for an individual ($3,000 for a couple), so gifts and inheritances need planning."},
{"t":"Supplemental wage withholding","c":"Taxes","l":2,"mod":"INV-040","d":"The optional flat 22% federal withholding rate on bonuses, RSU income and other supplemental wages, rising to a mandatory 37% on supplemental wages above $1 million in a year.","u":"Knowing how much tax your employer takes from stock pay.","m":"If your marginal rate is higher than 22%, you may owe more at filing time.","a":[]},
{"t":"Supported decision-making","c":"Estate","l":2,"mod":"INV-102","d":"An arrangement in which a person with a disability chooses trusted supporters who help them understand and communicate their own decisions; some states, such as Texas, recognize written agreements by statute.","u":"An alternative to guardianship that keeps the person's legal rights.","m":"The person still decides; the supporters help.","a":[]},
{"t":"Surrender charge","c":"Insurance","l":3,"mod":"INV-007","d":"A fee for withdrawing money from an annuity or insurance policy during an initial period, often several years.","u":"Discouraging early withdrawals.","m":"Can lock money in for years; read the schedule before buying."},
{"t":"Survey of Consumer Finances","a":["SCF"],"c":"Planning","l":2,"mod":"INV-026","d":"A detailed survey of US families' assets, debts and income run every three years by the Federal Reserve Board, with a supplemental sample of wealthy families. The 2022 survey, released in October 2023, is the most recent published.","u":"Measuring wealth, debt and retirement readiness across the population, and setting net-worth benchmarks by age.","m":"Use its medians as context, not as a target; they describe other families in 2022 dollars."},
{"t":"Survey of Household Economics and Decisionmaking","a":["SHED"],"c":"Planning","l":2,"mod":"INV-026","d":"An annual Federal Reserve survey of US adults' financial well-being, published each spring as 'Economic Well-Being of U.S. Households.'","u":"Tracking measures such as the share of adults who could cover a $400 emergency with cash or its equivalent.","m":"Its 2025 results found 63% could, and 35% of non-retirees thought their retirement saving was on track."},
{"t":"Survivor benefit","c":"Retirement","l":2,"d":"A Social Security benefit for a widow or widower of up to 100% of the deceased worker's benefit.","u":"Protecting the surviving spouse.","m":"The higher earner's claiming age largely determines it."},
{"t":"Survivorship bias","c":"Behavior","l":2,"mod":"INV-001","d":"Drawing conclusions only from the successes that survived, ignoring the failures that disappeared.","u":"Judging fund track records and national market histories.","m":"Fund databases drop closed funds; the US was one of history's best markets."},
{"t":"Suspended passive loss","a":["suspended loss","carried-forward passive loss"],"c":"Taxes","l":2,"mod":"INV-068","d":"A passive activity loss that could not be deducted this year and is carried forward to later years.","u":"Offsetting future passive income, and released in full when you sell your entire interest in a fully taxable sale to an unrelated person.","m":"A suspended loss is delayed, not lost; track it every year on Form 8582."},
{"t":"Systematic risk","a":["market risk"],"c":"Foundations","l":2,"mod":"INV-004","d":"Risk that affects the whole market or economy and cannot be removed by holding more securities of the same kind.","u":"Understanding the floor of diversification.","m":"Only other kinds of assets, or holding less in stocks, reduce it."},
{"t":"Tactical asset allocation","c":"Strategies","l":3,"d":"Temporarily shifting an allocation away from its long-term target to exploit perceived opportunities.","u":"Active risk management.","m":"A disciplined form of market timing; evidence of consistent success is limited."},
{"t":"Take-home pay","a":["net pay"],"c":"Planning","l":1,"mod":"INV-018","d":"Pay after taxes and payroll deductions such as retirement contributions and health premiums: the amount that reaches your bank account.","u":"The starting point for a monthly spending plan.","m":"Plan spending from take-home pay, but measure your savings rate against gross pay so pre-tax savings count."},
{"t":"Target-date fund","c":"Vehicles","l":1,"d":"A fund that holds a mix of stocks and bonds and becomes more conservative as a stated target year approaches.","u":"One-fund retirement investing, often a 401(k) default.","m":"Funds with the same target year can hold very different mixes; check the glide path."},
{"t":"Tax alpha","c":"Taxes","l":3,"mod":"INV-037","d":"The extra after-tax return credited to a tax strategy, such as loss harvesting or asset location, compared with not using it.","u":"Measuring the value of tax management.","m":"Research estimates depend heavily on assumed tax rates and on whether deferred taxes are eventually paid.","a":[]},
{"t":"Tax bracket","c":"Taxes","l":1,"d":"A range of taxable income taxed at a particular rate; federal brackets are indexed to inflation each year.","u":"Calculating tax and planning income.","m":"Check the IRS's current-year figures; they change annually."},
{"t":"Tax credit","c":"Taxes","l":1,"mod":"INV-029","d":"An amount subtracted directly from the tax you owe, rather than from income.","u":"Supporting families, work, education and retirement saving: the child tax credit, earned income tax credit, education credits and saver's credit.","m":"A $1,000 credit saves $1,000 in any bracket; a $1,000 deduction saves only $1,000 times your marginal rate.","a":[]},
{"t":"Tax drag","c":"Costs","l":2,"mod":"INV-007","d":"The reduction in return caused by taxes on distributions and realized gains in a taxable account.","u":"Comparing tax efficiency.","m":"Asset location and tax-efficient funds reduce it (Stage 5)."},
{"t":"Tax torpedo","c":"Taxes","l":3,"mod":"INV-081","d":"The jump in effective marginal tax rate when each extra dollar of income also makes up to 85 cents of Social Security taxable: 12% becomes about 22.2% and 22% becomes about 40.7%.","u":"Explaining why a retiree's real tax rate on IRA withdrawals can be far above their bracket.","m":"Roth conversions before Social Security or RMDs begin, and QCDs after 70½, can keep you out of the torpedo zone.","a":[]},
{"t":"Tax-deferred account","c":"Accounts","l":1,"d":"An account in which contributions are often deductible and growth is untaxed until withdrawal, when it is taxed as ordinary income: traditional 401(k), 403(b), IRA.","u":"Retirement saving.","m":"Withdrawals before 59½ generally incur a 10% additional tax unless an exception applies."},
{"t":"Tax-equivalent yield","a":["taxable-equivalent yield","TEY"],"c":"Taxes","l":2,"mod":"INV-010","d":"The yield a taxable bond must pay to leave you with the same after-tax income as a tax-exempt bond: tax-exempt yield ÷ (1 − your tax rate on the taxable alternative).","u":"Comparing municipal bonds with Treasuries, CDs and corporate bonds.","m":"A 3.20% muni is worth 4.21% taxable in the 24% federal bracket but only 3.64% in the 12% bracket (2026 brackets). Munis mostly suit high brackets and taxable accounts."},
{"t":"Tax-free account","a":["Roth account"],"c":"Accounts","l":1,"d":"An account funded with after-tax money whose qualified withdrawals are tax-free: Roth IRA, Roth 401(k).","u":"Retirement saving when you expect equal or higher future tax rates.","m":"Roth IRAs have no required minimum distributions for the original owner."},
{"t":"Tax-gain harvesting","c":"Taxes","l":3,"d":"Realizing long-term gains deliberately in years when they would be taxed at 0%, raising cost basis.","u":"Low-income years, such as early retirement.","m":"Resets basis higher at no tax cost."},
{"t":"Tax-loss harvesting","c":"Taxes","l":2,"d":"Selling investments at a loss to offset capital gains and up to a limited amount of ordinary income, while maintaining similar market exposure.","u":"Reducing taxes in taxable accounts.","m":"Must respect the wash-sale rule; defers rather than always eliminates tax."},
{"t":"Taxable account","c":"Accounts","l":1,"d":"An ordinary brokerage account with no special tax treatment; dividends, interest and realized gains are taxed each year.","u":"Flexible investing beyond retirement accounts.","m":"No contribution limits or withdrawal restrictions."},
{"t":"Taxable bridge","c":"Independence","l":2,"mod":"INV-074","d":"Money in ordinary brokerage accounts, savings or CDs used to pay for early-retirement years, since it has no age restrictions.","u":"Covering the years before the first Roth conversions mature or before 59½.","m":"Only the gain is taxed when you sell, and for 2026 long-term gains are taxed at 0% up to $98,900 of taxable income for joint filers.","a":[]},
{"t":"Taxable income","c":"Taxes","l":1,"mod":"INV-029","d":"Adjusted gross income minus the standard or itemized deduction and certain other deductions. The tax brackets are applied to this number.","u":"Calculating income tax and finding your marginal bracket and capital-gains rate.","m":"For most households it is far below salary: Maya's $62,000 salary becomes $40,280 of taxable income for 2026.","a":[]},
{"t":"Temporary hold","c":"Advice & regulation","l":2,"mod":"INV-062","d":"Under FINRA Rule 2165, a brokerage's power to delay a disbursement from the account of a 'specified adult' (age 65 or older, or impaired) when it reasonably suspects financial exploitation.","u":"Stopping money from leaving while a suspected scam is reviewed.","m":"A hold can feel frustrating, but it exists to protect you from a fraud in progress.","a":[]},
{"t":"Tenancy by the entirety","a":["tenants by the entirety","tenants by the entireties"],"c":"Estate","l":2,"mod":"INV-085","d":"Joint ownership available only to married couples, with right of survivorship, in which neither spouse alone can sell or encumber the property. Recognized in some states, including North Carolina and Pennsylvania.","u":"Holding a married couple's home so it passes to the survivor without probate.","m":"In some states it also protects the property from creditors of only one spouse. Check your deed's wording to see which form you have."},
{"t":"Tenancy in common","c":"Estate","l":2,"mod":"INV-085","d":"Co-ownership without survivorship: each owner holds a share, not necessarily equal, that passes under that owner's will or by intestacy.","u":"Unmarried co-buyers, siblings who inherit a property together, and investors.","m":"Your share goes through probate at your death unless it is in a trust or covered by a transfer-on-death deed where allowed.","a":[]},
{"t":"Tenant screening report","a":["tenant background check"],"c":"Real estate","l":1,"mod":"INV-067","d":"A consumer report on a rental applicant, which can include credit history, eviction records and criminal records, prepared by a screening company.","u":"Assessing whether an applicant is likely to pay and follow the lease.","m":"If you reject or charge more because of a report, federal law requires an adverse action notice naming the company."},
{"t":"Term life insurance","c":"Insurance","l":1,"d":"Life insurance for a set period, such as 20 years, paying only if the insured dies during the term.","u":"Protecting dependents during working years.","m":"Usually the most cost-effective way to replace income for a family."},
{"t":"Testamentary trust","c":"Estate","l":2,"mod":"INV-087","d":"A trust created by a will, which comes into existence after the will is probated.","u":"Holding money for minor children or other heirs at low setup cost.","m":"The usual choice for young parents. It does not avoid probate for the will's assets and offers no incapacity planning.","a":[]},
{"t":"Third-party special needs trust","c":"Estate","l":2,"mod":"INV-102","d":"A trust funded with the assets of someone other than the disabled beneficiary or their spouse, such as parents or grandparents, that is not the beneficiary's resource if they cannot end it and take the assets (SSA POMS SI 01120.200).","u":"Leaving inheritances and making gifts to a person with a disability without affecting benefits.","m":"Name the trust, not the person, in wills and on beneficiary designations; the creator chooses who receives what is left.","a":[]},
{"t":"Three-fund portfolio","c":"Portfolio","l":2,"d":"A simple portfolio of a total US stock fund, a total international stock fund and a total bond fund, popularized by the Bogleheads community.","u":"Low-cost, broadly diversified DIY investing.","m":"Covers most of the world's investable markets in three holdings."},
{"t":"Threshold rebalancing","a":["band rebalancing"],"c":"Portfolio","l":1,"mod":"INV-056","d":"Checking a portfolio on a schedule but trading only when an asset's weight moves outside a band around its target, for example more than 5 percentage points.","u":"Trading only when drift matters, which cuts trades, costs and taxes.","m":"In calm years you may do nothing at all. In a crash, the band tells you when to buy."},
{"t":"Thrift Savings Plan","a":["TSP"],"c":"Accounts","l":3,"d":"The federal government's defined-contribution retirement plan for federal employees and service members.","u":"Low-cost retirement saving for federal workers.","m":"Its index funds are among the cheapest available."},
{"t":"Through glide path","a":["\"through\" glide path","through-retirement glide path"],"c":"Retirement","l":2,"mod":"INV-050","d":"A target-date glide path that keeps reducing stocks after the target year, reaching its final mix years or decades later.","u":"Investors who will stay in the fund and draw it down gradually in retirement.","m":"More stocks at retirement: more long-run growth, and a bigger loss if a crash comes right around your retirement date."},
{"t":"Tiered Standard repayment plan","a":["Tiered Standard plan"],"c":"Planning","l":2,"mod":"INV-020","d":"A fixed-payment federal student-loan plan for loans made on or after July 1, 2026, with a 10-, 15-, 20- or 25-year term depending on the total borrowed and a minimum payment of $50 a month.","u":"The default plan for new federal loans.","m":"Fixed payments repay the loan on schedule; the longer tiers lower the payment but raise total interest."},
{"t":"Time decay","a":["theta"],"c":"Asset classes","l":3,"mod":"INV-016","d":"The loss of an option's time value as expiration approaches, all else equal. The CFTC describes time value as the part of the premium above intrinsic value, larger the longer the time remaining.","u":"Explaining why option buyers need the price to move soon, and why sellers collect income.","m":"Holding a bought option while waiting costs money every day, fastest in the final weeks."},
{"t":"Time horizon","c":"Planning","l":1,"mod":"INV-001","d":"The time until money will be needed.","u":"Choosing between saving and investing, and how much risk to take.","m":"Retirement is not the end of your horizon; money may be spent decades later."},
{"t":"Time value of money","c":"Foundations","l":1,"mod":"INV-002","d":"The principle that a dollar today is worth more than a dollar in the future, because today's dollar can be invested.","u":"Every comparison of money across time.","m":"Explains why starting early matters and why delayed payments must be discounted."},
{"t":"Time-weighted return","c":"Portfolio","l":3,"d":"A return measure that removes the effect of deposits and withdrawals, used to judge a manager.","u":"Fund and manager performance.","m":"Tells you how the investments did, not how you did."},
{"t":"TIPS","a":["Treasury Inflation-Protected Securities"],"c":"Asset classes","l":2,"d":"Treasury securities whose principal is adjusted for changes in the CPI-U, with interest paid on the adjusted principal.","u":"Protecting part of a portfolio against inflation.","m":"Their prices still move with real interest rates before maturity."},
{"t":"To glide path","a":["\"to\" glide path","to-retirement glide path"],"c":"Retirement","l":2,"mod":"INV-050","d":"A target-date glide path that reaches its most conservative allocation at the target year and then holds it steady.","u":"Investors who may move their money out of the fund at retirement.","m":"Less stock exposure around retirement; less growth for a long retirement if you stay in the fund."},
{"t":"Today's dollars","a":["constant dollars","real dollars"],"c":"Foundations","l":1,"mod":"INV-024","d":"An amount expressed in the buying power of money now, rather than in the larger number of dollars that will be needed in the future.","u":"Pricing goals and reading long-term projections without guessing future prices.","m":"Pair a goal priced in today's dollars with an after-inflation return; pair a future-dollar goal with a normal return."},
{"t":"Total return","c":"Foundations","l":1,"mod":"INV-001","d":"The return including both price change and all income (dividends or interest) reinvested.","u":"Fair comparison of investments that pay different amounts of income.","m":"Price-only charts understate stocks' results; dividends have been a large share of long-run stock returns."},
{"t":"Total stock market index fund","a":["total-market fund","total market index fund"],"c":"Vehicles","l":1,"mod":"INV-044","d":"A fund tracking an index of nearly all publicly traded US companies, large and small, weighted by market value.","u":"Owning the whole US stock market in one fund.","m":"It behaves almost exactly like an S&P 500 fund, because the largest companies dominate by value; either is a sound core."},
{"t":"Total-return investing","a":["total-return approach"],"c":"Retirement","l":1,"mod":"INV-047","d":"Building a portfolio for its combined return from dividends, interest and price changes, and funding spending from any of them.","u":"Steady, planned retirement withdrawals independent of dividend policy.","m":"'Touching principal' is not a failure; it is the plan. What matters is whether the withdrawal rate is sustainable."},
{"t":"Tracking error","a":[],"c":"Portfolio","l":2,"mod":"INV-044","d":"The standard deviation of the difference between a fund's return and its benchmark's return.","u":"Judging how faithfully an index fund tracks, or how far an active or factor fund strays.","m":"High tracking error means long stretches behind the index even if the strategy is sound. Ask whether you would stay through them."},
{"t":"Transaction-fee fund","c":"Costs","l":2,"mod":"INV-104","d":"A mutual fund that a particular brokerage charges a transaction fee to buy or sell.","u":"Comparing the real cost of holding a given fund at different brokerages.","m":"The same fund can be free to trade at one broker and cost a fee at another; ETFs usually avoid the issue.","a":[]},
{"t":"Transfer incident to divorce","c":"Accounts","l":2,"mod":"INV-095","d":"Moving all or part of an IRA to a spouse or former spouse under a divorce or separation instrument. It is not taxable, and the money becomes the receiving spouse's own IRA.","u":"Dividing traditional and Roth IRAs, which do not use QDROs.","m":"Use a direct transfer between custodians. Withdrawing the money first and handing it over is taxable to the owner, and withdrawals from the new IRA before 59 and a half can owe the 10% tax.","a":[]},
{"t":"Transfer on death","a":["TOD","POD","payable on death"],"c":"Estate","l":2,"d":"Registrations that pass brokerage or bank accounts, and in some states real estate, directly to named beneficiaries at death.","u":"Avoiding probate simply.","m":"Easy to set up and often overlooked."},
{"t":"Transfer-on-death deed","a":["beneficiary deed","TOD deed"],"c":"Estate","l":2,"mod":"INV-085","d":"A deed, signed and recorded during the owner's life, that transfers real estate to a named beneficiary only at the owner's death. It can be revoked and gives the beneficiary no rights while the owner lives.","u":"Passing a home outside probate without a trust or joint ownership, in states whose law authorizes it.","m":"As of September 2026, Arizona, Colorado and Ohio authorize them; Pennsylvania and North Carolina do not. A deed that is not recorded before death generally fails."},
{"t":"Treasury bill","a":["T-bill","T-bills"],"c":"Asset classes","l":1,"mod":"INV-001","d":"A short-term US government debt security maturing in one year or less, sold at a discount to face value.","u":"Very safe short-term savings; a benchmark for the risk-free rate.","m":"Safe in dollars; after inflation they lost ground in 40 of 98 years (1928–2025)."},
{"t":"Treasury note and bond","a":["Treasuries","Treasury bond"],"c":"Asset classes","l":1,"d":"US government debt maturing in 2–10 years (notes) or 20–30 years (bonds), paying interest every six months.","u":"High-quality income; portfolio ballast.","m":"Free of default risk in practice, but not of interest-rate or inflation risk."},
{"t":"Trend following","a":["moving-average rule","moving average timing"],"c":"Strategies","l":3,"mod":"INV-052","d":"A rule that holds an asset while its price is above its average over a recent period and exits when it falls below.","u":"Trying to avoid the middle of long bear markets.","m":"It has tended to reduce the deepest falls, often at the cost of lower returns, frequent switches and taxes."},
{"t":"Trinity study","c":"Retirement","l":3,"d":"A 1998 study by Cooley, Hubbard and Walz estimating the success rates of different withdrawal rates and portfolio mixes over US history.","u":"Evidence behind the 4% rule.","m":"Success rates fell sharply above about 5% for 30-year periods."},
{"t":"Trump account","a":["section 530A account","530A account"],"c":"Accounts","l":2,"mod":"INV-096","d":"A children's investment account created by the 2025 tax law. Until the year the child turns 18 it can hold only low-cost index funds of mainly U.S. stocks; after that it is generally treated as a traditional IRA. Children born 2025 through 2028 can receive a one-time $1,000 federal deposit.","u":"Giving children an early start on investing, with contributions from family (up to $5,000 a year combined), employers (up to $2,500), governments and charities.","m":"It is not a college fund: earnings are taxed as ordinary income when withdrawn. File Form 4547 to open one and claim the pilot deposit."},
{"t":"Trust","c":"Estate","l":2,"d":"A legal arrangement in which a trustee holds assets for beneficiaries under written terms.","u":"Avoiding probate, managing assets for heirs, and some tax planning.","m":"A trust only controls assets that are actually retitled into it."},
{"t":"Trust funding","a":["funding a trust"],"c":"Estate","l":1,"mod":"INV-087","d":"Transferring assets into a trust by retitling them (new deeds, account registrations) or naming the trust as beneficiary.","u":"Making a trust actually control the assets it is meant to hold.","m":"An unfunded trust does nothing. Never retitle an IRA or 401(k) to a trust during life; name the trust as beneficiary instead if appropriate."},
{"t":"Trusted contact person","a":["trusted contact"],"c":"Advice & regulation","l":1,"mod":"INV-097","d":"A person age 18 or older whom a brokerage firm may contact about a customer's account, under FINRA Rule 4512.","u":"Letting the firm address possible financial exploitation or confirm the customer's health, contact details or legal representatives.","m":"The trusted contact cannot trade or withdraw. For customers 65 and older, a firm that suspects exploitation may place a temporary hold on a disbursement and must notify the trusted contact."},
{"t":"Trustee","c":"Estate","l":1,"mod":"INV-087","d":"The person or institution that holds legal title to trust property and manages it for the beneficiaries, owing fiduciary duties of loyalty, prudence and impartiality.","u":"Investing, distributing, keeping records and filing the trust's tax returns.","m":"A trust works only as well as its trustee. Choose for honesty and organization, and name a successor.","a":[]},
{"t":"Tuition and medical exclusion","a":["qualified transfer"],"c":"Estate","l":2,"mod":"INV-092","d":"The rule that tuition paid directly to a qualifying school, and payments made directly to a medical-care provider (including health insurance premiums), are not gifts at all, with no dollar limit (IRC 2503(e)).","u":"Helping with education and health costs without using the annual exclusion or lifetime exemption.","m":"Pay the school or hospital, not the student or patient. Room, board and books do not qualify."},
{"t":"Turnover","c":"Costs","l":3,"mod":"INV-007","d":"The share of a fund's holdings replaced during a year.","u":"Estimating hidden trading costs and tax distributions.","m":"High turnover usually means higher costs and less tax efficiency."},
{"t":"Umbrella insurance","c":"Insurance","l":2,"d":"Extra liability coverage above home and auto policies.","u":"Protecting assets from large lawsuits.","m":"Inexpensive relative to the protection for households with growing net worth."},
{"t":"Unemployment insurance","a":["UI","unemployment benefits","unemployment compensation"],"c":"Planning","l":1,"mod":"INV-100","d":"A federal-state program, run by each state within federal guidelines, paying temporary benefits to eligible workers unemployed through no fault of their own; benefits last up to 26 weeks in most states (U.S. Department of Labor).","u":"Replacing part of lost wages during a job search.","m":"File as soon as the job ends; benefits are subject to federal income tax."},
{"t":"Unified credit","a":["applicable credit amount"],"c":"Estate","l":2,"mod":"INV-088","d":"A credit equal to the tentative tax on the applicable exclusion amount, usable against gift tax during life and estate tax at death. For 2026 the credit on $15,000,000 is $5,945,800 (IRS).","u":"Offsetting federal gift and estate tax.","m":"Gifts and estates share one credit, so taxable gifts during life leave less for your estate."},
{"t":"Uniform Lifetime Table","a":["applicable denominator","Table III"],"c":"Retirement","l":2,"mod":"INV-081","d":"IRS Publication 590-B, Appendix B, Table III: the divisor for each age used to compute required minimum distributions, for example 26.5 at 73, 24.6 at 75 and 16.0 at 85.","u":"Calculating an RMD: prior December 31 balance divided by the divisor for this year's age.","m":"A spouse more than 10 years younger who is your sole beneficiary lets you use Table II instead, which gives a smaller RMD."},
{"t":"Unlevered return","a":["unleveraged return"],"c":"Real estate","l":3,"mod":"INV-071","d":"The return a property earns on its full value, as if bought without a mortgage: net operating income yield plus price change.","u":"Comparing properties, and comparing real estate with stocks on equal terms.","m":"Borrowing raises your return on equity only when the unlevered return exceeds the loan's interest rate."},
{"t":"Unrecaptured section 1250 gain","c":"Taxes","l":3,"mod":"INV-030","d":"The part of a gain on selling depreciated real estate that reflects depreciation previously deducted, taxed at a maximum 25% rate rather than the usual long-term rates.","u":"Taxing rental property sales.","m":"Depreciation deductions on a rental are partly repaid when you sell (INV-068).","a":[]},
{"t":"Unrecoverable cost","a":["unrecoverable costs"],"c":"Real estate","l":2,"mod":"INV-063","d":"Money spent on housing that does not come back as equity: rent for a renter; property tax, maintenance, insurance, mortgage interest and the return given up on the down payment (less expected price growth) for an owner.","u":"Comparing renting and owning on equal terms, since principal repayment is saving, not a cost.","m":"If a comparable rent is lower than an owner's unrecoverable cost, renting is the cheaper way to live there, before transaction costs."},
{"t":"Unregistered offering","c":"Advice & regulation","l":2,"mod":"INV-062","d":"A sale of securities that has not been registered with the SEC or a state; some are legal under specific exemptions, but most Ponzi schemes are unregistered.","u":"Judging how much information and protection an offering provides.","m":"Ask which exemption applies and verify it; 'private' is not the same as 'legal'.","a":[]},
{"t":"Unsystematic risk","a":["company-specific risk","idiosyncratic risk"],"c":"Foundations","l":2,"mod":"INV-004","d":"Risk specific to one company or industry, which can be diversified away.","u":"Explaining why single stocks are riskier than funds.","m":"Because it can be removed for free, markets do not reward you for bearing it."},
{"t":"UTMA/UGMA account","a":["custodial account"],"c":"Accounts","l":2,"d":"An account holding assets for a minor, managed by a custodian, that become the child's property at the age of majority set by state law.","u":"Gifts to children.","m":"The money legally belongs to the child and can affect financial aid."},
{"t":"Vacancy rate","c":"Real estate","l":1,"mod":"INV-065","d":"The share of rental units, or of a year's rent, that is empty or uncollected. The Census Bureau publishes a national rental vacancy rate each quarter.","u":"Estimating how much of potential rent a landlord actually collects.","m":"Budget for vacancy even on a single house: one empty month a year is about 8% of the rent.","a":[]},
{"t":"Value investing","c":"Strategies","l":2,"d":"Buying securities that appear cheap relative to measures of fundamental value such as earnings or book value.","u":"A major investment philosophy associated with Benjamin Graham and Warren Buffett.","m":"Value can lag for long stretches, as it did for much of the 2010s."},
{"t":"Value premium","a":["HML","high minus low"],"c":"Strategies","l":2,"mod":"INV-046","d":"The extra average return of value stocks over growth stocks. Fama and French's HML factor is value minus growth by book-to-market.","u":"Justifying value tilts and value funds.","m":"US value beat growth by about 2.9 points a year from 1927 to 2025, but lagged in every 10-year period ending 2011 through 2025."},
{"t":"VantageScore","c":"Planning","l":2,"mod":"INV-021","d":"A credit-scoring model created by the three nationwide credit bureaus. VantageScore 4.0 uses a 300 to 850 range and weights payment history most heavily.","u":"Credit decisions, and since 2025 an alternative to Classic FICO for mortgages sold to Fannie Mae and Freddie Mac.","m":"The same habits (on-time payment, low utilization) raise both FICO and VantageScore.","a":[]},
{"t":"Variable expense","c":"Planning","l":1,"mod":"INV-018","d":"A cost that changes from month to month with your choices and circumstances, such as groceries, fuel or dining out.","u":"Deciding which categories to watch closely.","m":"Variable costs are where tracking pays off; fixed costs are where the big decisions are.","a":[]},
{"t":"Variable percentage withdrawal","a":["VPW"],"c":"Retirement","l":3,"d":"A method, popularized by the Bogleheads community, that withdraws a changing percentage of the portfolio each year based on age and allocation.","u":"Spending that adapts to markets.","m":"Never runs out by design, but income varies."},
{"t":"Vesting","c":"Accounts","l":2,"d":"The schedule by which employer contributions or equity awards become fully yours.","u":"Retaining employees.","m":"Leaving before you are vested can forfeit employer money."},
{"t":"Volatility","c":"Foundations","l":1,"mod":"INV-003","d":"How much an investment's returns vary from period to period, usually measured by standard deviation.","u":"Comparing the bumpiness of investments; building portfolios.","m":"Volatility is uncomfortable but only dangerous if you must sell during a fall."},
{"t":"Volatility drag","c":"Foundations","l":3,"mod":"INV-003","d":"The gap between arithmetic and geometric average returns caused by volatility; roughly half the variance.","u":"Explaining why steadier portfolios can compound closer to volatile ones than their averages suggest.","m":"A 50% loss followed by a 50% gain leaves you at 75%."},
{"t":"Wash trading","c":"Markets","l":3,"mod":"INV-062","d":"Buying and selling the same asset with yourself or a partner to create fake trading volume, without any real change in ownership.","u":"Making a thinly traded security look popular; illegal in US securities markets.","m":"High reported volume in an obscure token is not evidence of real demand.","a":[]},
{"t":"Wash-sale rule","c":"Taxes","l":2,"d":"A rule disallowing a loss if you buy a substantially identical security within 30 days before or after the sale.","u":"Limits on tax-loss harvesting.","m":"Purchases in IRAs and a spouse's accounts can also trigger it."},
{"t":"Weak-form efficiency","a":["weak form"],"c":"Strategies","l":2,"mod":"INV-043","d":"The version of the efficient market hypothesis in which prices already reflect all information in past prices and trading, so price history alone cannot predict future returns.","u":"Testing chart-based and trend-following trading rules.","m":"A stock is not cheap just because it has fallen, or expensive just because it has risen. Momentum is the best-known exception."},
{"t":"Whole life insurance","a":["permanent life insurance","cash value life insurance"],"c":"Insurance","l":2,"d":"Life insurance that lasts for life and builds a cash value, with higher premiums than term insurance.","u":"Permanent coverage needs; some estate planning.","m":"For most people who mainly need protection, term insurance plus investing costs less."},
{"t":"Widow's limit","a":["RIB-LIM","widow(er)'s limit"],"c":"Retirement","l":3,"mod":"INV-078","d":"If a worker claimed early and died, the widow(er)'s benefit is limited to the larger of the worker's reduced benefit or 82.5% of the worker's PIA (SSA POMS RS 00615.320).","u":"Calculating survivor benefits.","m":"A higher earner who claims at 62 permanently lowers the survivor's check; one who waits to 70 raises it."},
{"t":"Widow's penalty","a":["widow's tax penalty","survivor's penalty"],"c":"Taxes","l":2,"mod":"INV-098","d":"The tendency for a surviving spouse's federal tax to fall less than income, or even to rise, because single-filer brackets, a smaller standard deduction and lower Social Security thresholds apply after the year of death.","u":"Planning withdrawals, Roth conversions and Social Security claiming while both spouses are alive.","m":"Roth conversions in joint-filing years and a higher earner who delays Social Security both reduce it."},
{"t":"Will","a":["last will and testament"],"c":"Estate","l":1,"d":"A legal document directing how assets pass at death and naming an executor and, for minor children, a guardian.","u":"Distributing probate assets.","m":"Without one, state intestacy law decides."},
{"t":"Windfall","a":["sudden money","sudden wealth"],"c":"Planning","l":1,"mod":"INV-099","d":"A large sum received outside normal income: an inheritance, life insurance payout, gift, legal settlement, business or home sale, large bonus, or gambling or lottery winnings.","u":"Planning language for events whose tax treatment differs but whose decisions follow the same order: pause, tax check, foundations, invest.","m":"The source decides the tax; the order of decisions is the same for all of them."},
{"t":"Windfall Elimination Provision","a":["WEP"],"c":"Retirement","l":3,"mod":"INV-078","d":"A rule, repealed by the Social Security Fairness Act, that reduced the Social Security benefit of people who also received a pension from work not covered by Social Security.","u":"It affected many public-sector workers; it no longer applies to benefits payable from January 2024.","m":"People with non-covered pensions who never applied because of it may now need to file."},
{"t":"Withdrawal rate","c":"Retirement","l":1,"mod":"INV-072","d":"The share of a portfolio taken out in the first year of retirement. Under the classic rule the dollar amount then rises with inflation each year, whatever markets do.","u":"Turning a portfolio into income, or turning a spending level into a portfolio target (spending ÷ withdrawal rate).","m":"4% of $1,000,000 is $40,000 in year one. A lower rate needs a bigger portfolio but lasts longer.","a":[]},
{"t":"Withdrawal sequencing","a":["withdrawal order"],"c":"Retirement","l":2,"mod":"INV-042","d":"The choice of which accounts - taxable, tax-deferred or Roth - pay for spending in retirement, and in what order.","u":"Lowering lifetime taxes on the same spending.","m":"The conventional order (taxable, tax-deferred, Roth) is a default, not always the best."},
{"t":"Wrap fee","c":"Costs","l":3,"mod":"INV-007","d":"A single percentage-of-assets fee covering management, trading and administration in a bundled account.","u":"Managed account programs.","m":"Add underlying fund expenses to see the true total cost."},
{"t":"Years to financial independence","a":["years to FI"],"c":"Independence","l":2,"mod":"INV-072","d":"How long it takes invested savings to reach the FI number. Starting from zero: n = ln[1 + r(1 − s) ÷ (s × w)] ÷ ln(1 + r), with savings rate s, real return r and withdrawal rate w.","u":"Comparing savings rates and assumptions on a common scale.","m":"At 5% real and a 4% withdrawal rate, saving 50% of take-home pay takes about 16.6 years; saving 10% takes about 51."},
{"t":"Yield","c":"Asset classes","l":1,"d":"The income an investment produces as a percentage of its price.","u":"Comparing income investments.","m":"For bonds, yield moves opposite to price."},
{"t":"Yield curve","a":["term structure of interest rates"],"c":"Asset classes","l":1,"mod":"INV-009","d":"A line connecting the yields of bonds of the same credit quality, usually Treasuries, across maturities from one month to 30 years. The US Treasury publishes it daily.","u":"Seeing what the market pays for lending over different periods; pricing other bonds as spreads over Treasuries.","m":"When it slopes upward, you are paid more for tying money up longer; when it is flat or inverted, staying short costs little."},
{"t":"Yield to maturity","a":["YTM"],"c":"Asset classes","l":3,"d":"The total annual return a bond would earn if held to maturity with all payments made as scheduled.","u":"Comparing bonds with different prices and coupons.","m":"The best single estimate of a high-quality bond's return if held to maturity."},
{"t":"Yield to worst","c":"Asset classes","l":3,"mod":"INV-009","d":"The lowest of a callable bond's yield to maturity and its yields to each possible call date.","u":"Quoting a conservative yield for callable bonds.","m":"For a callable bond priced above par, treat yield to worst as the realistic yield.","a":[]},
{"t":"Yield trap","c":"Valuation","l":2,"mod":"INV-006","d":"A stock whose high dividend yield reflects a falling price and a likely dividend cut.","u":"Screening income investments.","m":"If the dividend is cut, both income and price often fall."},
{"t":"Zero percent capital gains rate","a":["0% capital gains rate","0% bracket"],"c":"Taxes","l":2,"mod":"INV-037","d":"The 0% federal rate on long-term gains and qualified dividends that fit under a taxable-income threshold: for 2026, $49,450 single, $98,900 joint and $66,200 head of household.","u":"Harvesting gains or selling appreciated holdings in low-income years.","m":"Only the room between your ordinary taxable income and the threshold is taxed at 0%."},
{"t":"Zero-based budget","a":["zero-based budgeting"],"c":"Planning","l":1,"mod":"INV-018","d":"A spending plan in which every dollar of expected income is assigned a job (spending, saving or debt) until nothing is left unassigned.","u":"Tight months, debt payoff, and stopping a surplus from disappearing into unplanned spending.","m":"'Zero' refers to unassigned money, not to your bank balance; savings are one of the jobs."},
{"t":"Zero-coupon bond","c":"Asset classes","l":2,"mod":"INV-009","d":"A bond that pays no periodic interest; it is bought at a discount and pays its face value at maturity. Treasury STRIPS are an example.","u":"Funding a single future payment with no reinvestment of coupons.","m":"It has the longest duration for its maturity, so its price swings the most when rates change. In taxable accounts, the imputed interest is taxed each year.","a":[]}];
